INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-show-disney', 'Name a Disney animated film (not Pixar).', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Snow White and the Seven Dwarfs (1937) was the first full-length cel-animated feature. People called it ''Disney''s Folly'' until it became the highest-grossing film of its time.', 'https://en.wikipedia.org/wiki/List_of_Walt_Disney_Animation_Studios_films', 'Wikipedia: List of Walt Disney Animation Studios films', '2026-11-21', 'CC BY-SA 4.0', 'film', 1, 0, '[{"canonical":"The Lion King","prior":18,"aliases":["Lion King"]},{"canonical":"Frozen","prior":14,"aliases":["Frozen 2","Frozen II"]},{"canonical":"Aladdin","prior":8,"aliases":[]},{"canonical":"Moana","prior":6,"aliases":["Moana 2"]},{"canonical":"Cinderella","prior":5,"aliases":[]},{"canonical":"Snow White and the Seven Dwarfs","prior":5,"aliases":["Snow White"]},{"canonical":"Beauty and the Beast","prior":5,"aliases":[]},{"canonical":"The Jungle Book","prior":5,"aliases":["Jungle Book"]},{"canonical":"The Little Mermaid","prior":4,"aliases":["Little Mermaid"]},{"canonical":"Tangled","prior":4,"aliases":[]},{"canonical":"Mulan","prior":3,"aliases":[]},{"canonical":"Zootopia","prior":3,"aliases":["Zootropolis"]},{"canonical":"Encanto","prior":3,"aliases":[]},{"canonical":"Bambi","prior":2,"aliases":[]},{"canonical":"Dumbo","prior":2,"aliases":[]},{"canonical":"Pinocchio","prior":2,"aliases":[]},{"canonical":"Peter Pan","prior":2,"aliases":[]},{"canonical":"Sleeping Beauty","prior":2,"aliases":[]},{"canonical":"Alice in Wonderland","prior":2,"aliases":[]},{"canonical":"One Hundred and One Dalmatians","prior":2,"aliases":["101 Dalmatians","101 Dalmations"]},{"canonical":"Lady and the Tramp","prior":1,"aliases":[]},{"canonical":"Hercules","prior":1,"aliases":[]},{"canonical":"Tarzan","prior":1,"a