l":"Tintin","prior":0.5,"aliases":["Tin Tin"]},{"canonical":"Abhijeet","prior":0.5,"aliases":["Inspector Abhijeet"]},{"canonical":"Detective Pikachu","prior":0.5,"aliases":[]},{"canonical":"Sam Spade","prior":0.3,"aliases":[]},{"canonical":"Philip Marlowe","prior":0.3,"aliases":["Marlowe"]},{"canonical":"Inspector Morse","prior":0.3,"aliases":["Morse"]},{"canonical":"Jessica Fletcher","prior":0.3,"aliases":[]},{"canonical":"Father Brown","prior":0.3,"aliases":[]},{"canonical":"Dick Tracy","prior":0.3,"aliases":[]},{"canonical":"Kakababu","prior":0.3,"aliases":[]},{"canonical":"Jack Reacher","prior":0.3,"aliases":["Reacher"]},{"canonical":"Ellery Queen","prior":0.2,"aliases":[]},{"canonical":"Lisbeth Salander","prior":0.2,"aliases":[]},{"canonical":"Kiriti Roy","prior":0.2,"aliases":[]},{"canonical":"Adrian Monk","prior":0.2,"aliases":["Monk"]},{"canonical":"Encyclopedia Brown","prior":0.1,"aliases":[]},{"canonical":"Precious Ramotswe","prior":0.1,"aliases":["Mma Ramotswe"]},{"canonical":"Kurt Wallander","prior":0.1,"aliases":["Wallander"]},{"canonical":"Harry Bosch","prior":0.1,"aliases":[]},{"canonical":"Veronica Mars","prior":0.1,"aliases":[]},{"canonical":"Lord Peter Wimsey","prior":0.1,"aliases":["Peter Wimsey"]},{"canonical":"Mike Hammer","prior":0.1,"aliases":[]},{"canonical":"Cormoran Strike","prior":0.1,"aliases":[]},{"canonical":"Detective Dee","prior":0.1,"aliases":["Dee Renjie"]}]', NULL, 'Think of Baker Street, Bengali bookshelves, Agatha Christie and the Sony TV show with the door-breaking inspector.');
