INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-show-bond', 'Name a James Bond film.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Octopussy (1983) was partly filmed in Udaipur, where both the Lake Palace and the Monsoon Palace appear. Ian Fleming took his spy''s name from an American ornithologist, the author of ''Birds of the West Indies''.', 'https://en.wikipedia.org/wiki/List_of_James_Bond_films', 'Wikipedia: List of James Bond films', '2026-11-21', 'CC BY-SA 4.0', 'film', 2, 0, '[{"canonical":"Skyfall","prior":14,"aliases":[]},{"canonical":"Casino Royale","prior":12,"aliases":[]},{"canonical":"No Time to Die","prior":8,"aliases":[]},{"canonical":"Spectre","prior":6,"aliases":[]},{"canonical":"GoldenEye","prior":6,"aliases":["Golden Eye"]},{"canonical":"Goldfinger","prior":5,"aliases":[]},{"canonical":"Quantum of Solace","prior":4,"aliases":[]},{"canonical":"Dr. No","prior":3,"aliases":["Dr No","Doctor No"]},{"canonical":"Die Another Day","prior":3,"aliases":[]},{"canonical":"From Russia with Love","prior":2,"aliases":[]},{"canonical":"The World Is Not Enough","prior":2,"aliases":["World Is Not Enough"]},{"canonical":"Tomorrow Never Dies","prior":2,"aliases":[]},{"canonical":"Thunderball","prior":1,"aliases":[]},{"canonical":"You Only Live Twice","prior":1,"aliases":[]},{"canonical":"Diamonds Are Forever","prior":1,"aliases":[]},{"canonical":"Live and Let Die","prior":1,"aliases":[]},{"canonical":"The Man with the Golden Gun","prior":1,"aliases":["Man with the Golden Gun"]},{"canonical":"The Spy Who Loved Me","prior":1,"aliases":["Spy Who Loved Me"]},{"canonical":"Moonraker","prior":1,"aliases":[]},{"canonical":"For Your Eyes Only","prior":1,"aliases":[]},{"canonical":"Octopussy","prior":1,"aliases":[]},{"canonical":"On Her Majesty''s Secret Service","prior":0.5,"aliases":[]},{"canonical":"A View to a Kill","prior":0.5,"aliases":["View to a Kill"]},{"canonical":"The Living Daylights","prior":0.5,"aliases":["Living Daylights"]},{"canonical":"Licence to Kill","prior":0.5,"aliases":["License to Kill"]},{"canonical":"Never Say Never Again","prior":0.3,"aliases":[]}]', NULL, 'Think of one-word titles, a song about gold, and the film shot among Udaipur''s palaces.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-show-fly', 'Name a superhero who can fly.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Superman couldn''t fly at first: in his 1938 debut he could only ''leap an eighth of a mile''. He took to the air in the early 1940s, partly because the leaps looked silly in the animated cartoons.', 'https://en.wikipedia.org/wiki/Superman', 'Wikipedia: Superman', '2026-11-21', 'CC BY-SA 4.0', 'film', 1, 0, '[{"canonical":"Superman","prior":28,"aliases":["Clark Kent","Kal-El"]},{"canonical":"Iron Man","prior":12,"aliases":["Tony Stark","Ironman"]},{"canonical":"Shaktimaan","prior":8,"aliases":["Shaktiman","Gangadhar"]},{"canonical":"Thor","prior":6,"aliases":[]},{"canonical":"Krrish","prior":6,"aliases":["Krish"]},{"canonical":"Captain Marvel","prior":4,"aliases":["Carol Danvers"]},{"canonical":"Wonder Woman","prior":3,"aliases":["Diana Prince"]},{"canonical":"Supergirl","prior":2,"aliases":["Kara Zor-El"]},{"canonical":"Shazam","prior":1,"aliases":[]},{"canonical":"Storm","prior":1,"aliases":[]},{"canonical":"Vision","prior":1,"aliases":[]},{"canonical":"Falcon","prior":1,"aliases":["Sam Wilson"]},{"canonical":"Green Lantern","prior":1,"aliases":["Hal Jordan"]},{"canonical":"Silver Surfer","prior":1,"aliases":[]},{"canonical":"Doctor Strange","prior":1,"aliases":["Dr Strange"]},{"canonical":"Human Torch","prior":1,"aliases":[]},{"canonical":"Goku","prior":1,"aliases":["Son Goku"]},{"canonical":"A Flying Jatt","prior":1,"aliases":["Flying Jatt"]},{"canonical":"Martian Manhunter","prior":0.5,"aliases":[]},{"canonical":"Scarlet Witch","prior":0.5,"aliases":["Wanda"]},{"canonical":"Star-Lord","prior":0.5,"aliases":["Star Lord"]},{"canonical":"War Machine","prior":0.5,"aliases":[]},{"canonical":"Hancock","prior":0.5,"aliases":[]},{"canonical":"Parmanu","prior":0.5,"a