INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-show-robot', 'Name a famous robot from a film, show, game or book.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The word ''robot'' comes from Karel Čapek''s 1920 Czech play ''R.U.R.'', from ''robota'', forced labour. India''s most famous film robot, Chitti, first appeared in Enthiran in 2010.', 'https://en.wikipedia.org/wiki/Robot', 'Wikipedia: Robot', '2026-11-21', 'CC BY-SA 4.0', 'film', 2, 0, '[{"canonical":"WALL-E","prior":14,"aliases":["Wall-E","Walle","Wall E"]},{"canonical":"R2-D2","prior":10,"aliases":["R2D2","R2","Artoo","Artoo-Detoo"]},{"canonical":"Terminator","prior":10,"aliases":["The Terminator","T-800","T-1000"]},{"canonical":"C-3PO","prior":8,"aliases":["C3PO","C3P0","Threepio"]},{"canonical":"Chitti","prior":8,"aliases":["Chitti the Robot","Enthiran"]},{"canonical":"Optimus Prime","prior":6,"aliases":["Optimus"]},{"canonical":"Doraemon","prior":6,"aliases":[]},{"canonical":"Bumblebee","prior":4,"aliases":[]},{"canonical":"Baymax","prior":4,"aliases":[]},{"canonical":"EVE","prior":2,"aliases":["Eve"]},{"canonical":"RoboCop","prior":2,"aliases":["Robocop","Robo Cop"]},{"canonical":"Iron Giant","prior":1,"aliases":["The Iron Giant"]},{"canonical":"Ultron","prior":1,"aliases":[]},{"canonical":"Astro Boy","prior":1,"aliases":["Astroboy","Tetsuwan Atom"]},{"canonical":"HAL 9000","prior":1,"aliases":["HAL","Hal 9000"]},{"canonical":"BB-8","prior":1,"aliases":["BB8"]},{"canonical":"Vision","prior":0.5,"aliases":[]},{"canonical":"Data","prior":0.5,"aliases":["Lieutenant Commander Data"]},{"canonical":"Bender","prior":0.5,"aliases":["Bender Rodriguez"]},{"canonical":"Megatron","prior":0.5,"aliases":[]},{"canonical":"Daleks","prior":0.5,"aliases":["Dalek"]},{"canonical":"Tin Man","prior":0.5,"aliases":["The Tin Man","Tin Woodman"]},{"canonical":"Ra.One","prior":0.5,"aliases":["Ra One","RaOne"]},{"canonical":"TARS","prior":0.5,"aliases":[]},{"canonical":"Marvin","prior":0.3,"aliases":["Marvin the Paranoid Android"]},{"canonical":"Johnny 5","prior":0.3,"aliases":["Number 5","Johnny Five"]},{"canonical":"Robby the Robot","prior":0.3,"aliases":["Robby"]},{"canonical":"Rosie","prior":0.3,"aliases":["Rosie the Robot","Rosey"]},{"canonical":"K-2SO","prior":0.3,"aliases":["K2SO"]},{"canonical":"Sonny","prior":0.3,"aliases":[]},{"canonical":"Gundam","prior":0.3,"aliases":[]},{"canonical":"Voltron","prior":0.3,"aliases":[]},{"canonical":"Mega Man","prior":0.3,"aliases":["Megaman","Rockman"]},{"canonical":"G.One","prior":0.3,"aliases":["G One","GOne"]},{"canonical":"Chappie","prior":0.3,"aliases":[]},{"canonical":"Ava","prior":0.2,"aliases":[]},{"canonical":"Mazinger Z","prior":0.2,"aliases":["Mazinger"]},{"canonical":"K-9","prior":0.2,"aliases":["K9"]},{"canonical":"Maria","prior":0.2,"aliases":["False Maria","Maschinenmensch"]},{"canonical":"GLaDOS","prior":0.2,"aliases":["Glados"]},{"canonical":"Gort","prior":0.1,"aliases":[]},{"canonical":"Atom","prior":0.1,"aliases":[]},{"canonical":"M-O","prior":0.1,"aliases":[]},{"canonical":"Bishop","prior":0.1,"aliases":[]},{"canonical":"Clank","prior":0.1,"aliases":[]}]', NULL, 'Think of a galaxy far away, a Pixar trash compactor, a Rajinikanth double role and a blue cat from the future.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-play-net', 'Name a sport that uses a net.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Badminton takes its name from Badminton House, the Duke of Beaufort''s home in England, but British officers were already playing it in India in the 1870s, where it was known as ''Poona''.', 'https://en.wikipedia.org/wiki/Badminton', 'Wikipedia: Badminton', '2026-11-21', 'CC BY-SA 4.0', 'sport', 1, 0, '[{"canonical":"Badminton","prior":16,"aliases":[]},{"canonical":"Tennis","prior":16,"aliases":["Lawn tennis"]},{"canonical":"Volleyball","prior":12,"aliases":["Beach volleyball"]},{"canonical":"Football","prior":10,"aliases":["Soccer"]},{"canonical":"Basketball","prior":8,"aliases":[]},{"canonical":"Table tennis","prior":6,"aliases":["Ping pong","Ping-pong","TT"]},{"canonical":"Hockey","prior":6,"aliases":["Field hockey","Ice hockey"]},{"canonical":"Netball","prior":3,"aliases":[]},{"canonical":"Throwball","prior":2,"aliases":[]},{"canonical":"Handball","prior":2,"aliases":[]},{"canonical":"Water polo","prior":2,"aliases":[]},{"canonical":"Pickleball","prior":2,"aliases":[]},{"canonical":"Sepak takraw","prior":1,"aliases":["Takraw","Kick volleyball"]},{"canonical":"Lacrosse","prior":0.5,"aliases":[]},{"canonical":"Cricket","prior":0.5,"aliases":[]},{"canonical":"Padel","prior":0.5,"aliases":["Paddle tennis"]},{"canonical":"Futsal","prior":0.5,"aliases":[]},{"canonical":"Tennikoit","prior":0.5,"aliases":["Ring tennis","Deck tennis"]},{"canonical":"Footvolley","prior":0.3,"aliases":[]},{"canonical":"Ball badminton","prior":0.3,"aliases":[]},{"canonical":"Gaelic football","prior":0.2,"aliases":[]},{"canonical":"Hurling","prior":0.2,"aliases":[]},{"canonical":"Floorball","prior":0.2,"aliases":[]},{"canonical":"Beach tennis","prior":0.1,"aliases":[]},{"canonical":"Bossaball","prior":0.1,"aliases":[]},{"canonical":"Sitting volleyball","prior":0.1,"aliases":[]}]', NULL, 'Think of rackets, goals, hoops and the courts in a school playground.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-play-martial', 'Name a martial art.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Kalaripayattu from Kerala is one of the oldest fighting systems still practised. A legend says Bodhidharma, a monk from South India, carried martial exercises to China''s Shaolin Temple, though historians doubt it.', 'https://en.wikipedia.org/wiki/Kalaripayattu', 'Wikipedia: Kalaripayattu', '2026-11-21', 'CC BY-SA 4.0', 'sport', 1, 0, '[{"canonical":"Karate","prior":26,"aliases":[]},{"canonical":"Kung fu","prior":14,"aliases":["Kungfu","Gongfu"]},{"canonical":"Taekwondo","prior":12,"aliases":["Tae kwon do"]},{"canonical":"Judo","prior":10,"aliases":[]},{"canonical":"Kalaripayattu","prior":6,"aliases":["Kalari","Kalaripayat"]},{"canonical":"Boxing","prior":4,"aliases":[]},{"canonical":"Jiu-jitsu","prior":4,"aliases":["Jujutsu","Ju-jitsu","Brazilian jiu-jitsu","BJJ","Jujitsu"]},{"canonical":"Muay Thai","prior":3,"aliases":["Thai boxing"]},{"canonical":"Kickboxing","prior":2,"aliases":["Kick boxing"]},{"canonical":"Wrestling","prior":2,"aliases":["Kushti","Pehlwani","Kusti"]},{"canonical":"Aikido","prior":2,"aliases":[]},{"canonical":"Krav Maga","prior":2,"aliases":[]},{"canonical":"Capoeira","prior":2,"aliases":[]},{"canonical":"Mixed martial arts","prior":2,"aliases":["MMA"]},{"canonical":"Tai chi","prior":2,"aliases":["Tai chi chuan","Taiji"]},{"canonical":"Wushu","prior":1,"aliases":[]},{"canonical":"Kendo","prior":1,"aliases":[]},{"canonical":"Sumo","prior":1,"aliases":["Sumo wrestling"]},{"canonical":"Silambam","prior":1,"aliases":[]},{"canonical":"Gatka","prior":1,"aliases":[]},{"canonical":"Wing Chun","prior":1,"aliases":[]},{"canonical":"Thang-ta","prior":0.5,"aliases":["Huyen langlon","Thang ta"]},{"canonical":"Mallakhamb","prior":0.5,"aliases":["Mallakhamba"]},{"canonical":"Jeet Kune Do","prior":0.5,"aliases":[]},{"canonical":"Sambo","prior":0.5,"aliases":[]},{"canonical":"Fencing","prior":0.5,"aliases":[]},{"canonical":"Shaolin kung fu","prior":0.5,"aliases":["Shaolin"]},{"canonical":"Hapkido","prior":0.3,"aliases":[]},{"canonical":"Kyokushin","prior":0.3,"aliases":[]},{"canonical":"Shotokan","prior":0.3,"aliases":[]},{"canonical":"Ninjutsu","prior":0.3,"aliases":[]},{"canonical":"Pencak silat","prior":0.3,"aliases":["Silat"]},{"canonical":"Lathi khela","prior":0.3,"aliases":["Lathi"]},{"canonical":"Savate","prior":0.2,"aliases":[]},{"canonical":"Eskrima","prior":0.2,"aliases":["Kali","Arnis","Escrima"]},{"canonical":"Kyudo","prior":0.2,"aliases":[]},{"canonical":"Iaido","prior":0.2,"aliases":[]},{"canonical":"Musti yuddha","prior":0.2,"aliases":["Mushti yuddha"]},{"canonical":"Varma kalai","prior":0.2,"aliases":[]},{"canonical":"Pradal Serey","prior":0.1,"aliases":[]},{"canonical":"Lethwei","prior":0.1,"aliases":[]},{"canonical":"Systema","prior":0.1,"aliases":[]},{"canonical":"Bartitsu","prior":0.1,"aliases":[]},{"canonical":"Sanda","prior":0.1,"aliases":["Sanshou"]}]', NULL, 'Think of Japan, Korea, Brazil, Israel and Kerala, and of fights with sticks and swords.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-play-board', 'Name a board game.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Snakes and ladders began in India as Moksha Patam, a game about virtue and vice: ladders were good deeds and snakes were sins. Chess also began in India, as chaturanga, around the 6th century.', 'https://en.wikipedia.org/wiki/Snakes_and_ladders', 'Wikipedia: Snakes and ladders', '2026-11-21', 'CC BY-SA 4.0', 'games', 1, 0, '[{"canonical":"Chess","prior":20,"aliases":["Shatranj"]},{"canonical":"Ludo","prior":18,"aliases":[]},{"canonical":"Snakes and ladders","prior":14,"aliases":["Snake and ladder","Snake and ladders","Snakes and ladder","Moksha Patam","Chutes and ladders"]},{"canonical":"Monopoly","prior":10,"aliases":["Business","Business game"]},{"canonical":"Carrom","prior":6,"aliases":["Carrom board","Carom"]},{"canonical":"Scrabble","prior":6,"aliases":[]},{"canonical":"Checkers","prior":3,"aliases":["Draughts"]},{"canonical":"Cluedo","prior":2,"aliases":["Clue"]},{"canonical":"Catan","prior":2,"aliases":["Settlers of Catan"]},{"canonical":"Trivial Pursuit","prior":1,"aliases":[]},{"canonical":"Risk","prior":1,"aliases":[]},{"canonical":"Pictionary","prior":1,"aliases":[]},{"canonical":"The Game of Life","prior":1,"aliases":["Game of Life","Life"]},{"canonical":"Backgammon","prior":1,"aliases":[]},{"canonical":"Go","prior":1,"aliases":["Weiqi","Baduk"]},{"canonical":"Chinese checkers","prior":1,"aliases":[]},{"canonical":"Battleship","prior":1,"aliases":[]},{"canonical":"Connect Four","prior":1,"aliases":["Connect 4"]},{"canonical":"Othello","prior":1,"aliases":["Reversi"]},{"canonical":"Pachisi","prior":1,"aliases":["Chaupar","Chausar"]},{"canonical":"Mancala","prior":0.5,"aliases":["Oware","Pallanguzhi","Ali guli mane"]},{"canonical":"Scotland Yard","prior":0.5,"aliases":[]},{"canonical":"Ticket to Ride","prior":0.5,"aliases":[]},{"canonical":"Mahjong","prior":0.5,"aliases":["Mah-jong"]},{"canonical":"Guess Who","prior":0.5,"aliases":[]},{"canonical":"Pandemic","prior":0.3,"aliases":[]},{"canonical":"Carcassonne","prior":0.3,"aliases":[]},{"canonical":"Dominoes","prior":0.3,"aliases":["Domino"]},{"canonical":"Nine men''s morris","prior":0.3,"aliases":["Morris","Mill"]},{"canonical":"Mastermind","prior":0.3,"aliases":[]},{"canonical":"Codenames","prior":0.3,"aliases":[]},{"canonical":"Stratego","prior":0.2,"aliases":[]},{"canonical":"Operation","prior":0.2,"aliases":[]},{"canonical":"Sorry!","prior":0.2,"aliases":["Sorry"]},{"canonical":"Shogi","prior":0.2,"aliases":[]},{"canonical":"Xiangqi","prior":0.2,"aliases":["Chinese chess"]},{"canonical":"Senet","prior":0.2,"aliases":[]},{"canonical":"Royal Game of Ur","prior":0.2,"aliases":["Game of Ur"]},{"canonical":"Bagh-chal","prior":0.2,"aliases":["Bagh chal","Aadu puli attam","Goats and tigers","Lambs and tigers"]},{"canonical":"Mouse Trap","prior":0.1,"aliases":[]},{"canonical":"Hnefatafl","prior":0.1,"aliases":["Tafl"]},{"canonical":"Azul","prior":0.1,"aliases":[]},{"canonical":"Splendor","prior":0.1,"aliases":[]}]', NULL, 'Think of family nights, Sunday afternoons at a grandparent''s house, and the oldest games in the world.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-play-cards', 'Name a card game.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Playing cards came to India with the Mughals as ganjifa: round, hand-painted cards in sets of eight or more suits. Teen Patti, the three-card game played across India at Diwali, is a cousin of the British game three-card brag.', 'https://en.wikipedia.org/wiki/Ganjifa', 'Wikipedia: Ganjifa', '2026-11-21', 'CC BY-SA 4.0', 'games', 1, 0, '[{"canonical":"Rummy","prior":14,"aliases":["Indian rummy","Gin rummy"]},{"canonical":"Poker","prior":12,"aliases":["Texas hold ''em","Texas holdem"]},{"canonical":"UNO","prior":12,"aliases":["Uno"]},{"canonical":"Teen Patti","prior":10,"aliases":["Teen patti","Flash","Flush","3 Patti"]},{"canonical":"Bluff","prior":6,"aliases":["Cheat","I doubt it"]},{"canonical":"Solitaire","prior":6,"aliases":["Patience","Klondike","Spider Solitaire"]},{"canonical":"Blackjack","prior":4,"aliases":["21","Twenty-one","Pontoon"]},{"canonical":"Bridge","prior":3,"aliases":["Contract bridge"]},{"canonical":"Go Fish","prior":2,"aliases":[]},{"canonical":"Bhabhi","prior":2,"aliases":["Getaway","Get Away","Thulla"]},{"canonical":"Snap","prior":1,"aliases":[]},{"canonical":"Old Maid","prior":1,"aliases":["Donkey","Gadha"]},{"canonical":"Crazy Eights","prior":1,"aliases":[]},{"canonical":"Hearts","prior":1,"aliases":[]},{"canonical":"Spades","prior":1,"aliases":[]},{"canonical":"Mendicot","prior":1,"aliases":["Mendhi coat","Mindi","Mendhikot","Dehla pakad"]},{"canonical":"Court piece","prior":1,"aliases":["Coat piece","Rang","Hokm"]},{"canonical":"Twenty-nine","prior":1,"aliases":["29"]},{"canonical":"Literature","prior":0.5,"aliases":[]},{"canonical":"Memory","prior":0.5,"aliases":["Concentration","Pairs","Pelmanism"]},{"canonical":"War","prior":0.5,"aliases":[]},{"canonical":"Baccarat","prior":0.5,"aliases":[]},{"canonical":"Canasta","prior":0.5,"aliases":[]},{"canonical":"Ganjifa","prior":0.5,"aliases":[]},{"canonical":"Pokémon Trading Card Game","prior":0.5,"aliases":["Pokemon TCG","Pokemon cards","Pokémon cards"]},{"canonical":"Top Trumps","prior":0.5,"aliases":["Trump cards","WWE trump cards"]},{"canonical":"Sequence","prior":0.5,"aliases":[]},{"canonical":"Cribbage","prior":0.3,"aliases":[]},{"canonical":"President","prior":0.3,"aliases":["Scum"]},{"canonical":"Whist","prior":0.3,"aliases":[]},{"canonical":"Magic: The Gathering","prior":0.3,"aliases":["Magic the Gathering","MTG"]},{"canonical":"Yu-Gi-Oh!","prior":0.3,"aliases":["Yugioh","Yu-Gi-Oh"]},{"canonical":"Exploding Kittens","prior":0.3,"aliases":[]},{"canonical":"Euchre","prior":0.2,"aliases":[]},{"canonical":"Speed","prior":0.2,"aliases":["Spit"]},{"canonical":"Pinochle","prior":0.2,"aliases":[]},{"canonical":"Piquet","prior":0.1,"aliases":[]},{"canonical":"Spoons","prior":0.1,"aliases":[]},{"canonical":"Kemps","prior":0.1,"aliases":[]}]', NULL, 'Think of Diwali nights, long train journeys, casino tables and the game that came with every Windows computer.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-play-olympic', 'Name an Indian who has won an individual medal at the Summer Olympics (up to Paris 2024).', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Abhinav Bindra won India''s first individual Olympic gold, in the 10 m air rifle at Beijing 2008. Neeraj Chopra''s javelin gold at Tokyo was India''s first Olympic medal in athletics since independence.', 'https://en.wikipedia.org/wiki/India_at_the_Olympics', 'Wikipedia: India at the Olympics', '2026-11-21', 'CC BY-SA 4.0', 'sport', 2, 0, '[{"canonical":"Neeraj Chopra","prior":22,"aliases":["Neeraj"]},{"canonical":"PV Sindhu","prior":14,"aliases":["P. V. Sindhu","Sindhu","Pusarla Venkata Sindhu"]},{"canonical":"Abhinav Bindra","prior":8,"aliases":["Bindra"]},{"canonical":"Mary Kom","prior":8,"aliases":["MC Mary Kom","M. C. Mary Kom"]},{"canonical":"Saina Nehwal","prior":6,"aliases":["Saina"]},{"canonical":"Mirabai Chanu","prior":5,"aliases":["Saikhom Mirabai Chanu","Mirabai"]},{"canonical":"Manu Bhaker","prior":5,"aliases":["Manu Bhakar","Manu"]},{"canonical":"Sakshi Malik","prior":4,"aliases":["Sakshi"]},{"canonical":"Sushil Kumar","prior":4,"aliases":[]},{"canonical":"Bajrang Punia","prior":3,"aliases":["Bajrang"]},{"canonical":"Lovlina Borgohain","prior":2,"aliases":["Lovlina"]},{"canonical":"Ravi Kumar Dahiya","prior":2,"aliases":["Ravi Dahiya"]},{"canonical":"Yogeshwar Dutt","prior":2,"aliases":[]},{"canonical":"Vijender Singh","prior":2,"aliases":["Vijender"]},{"canonical":"Karnam Malleswari","prior":2,"aliases":["Malleswari"]},{"canonical":"Leander Paes","prior":2,"aliases":[]},{"canonical":"Rajyavardhan Singh Rathore","prior":2,"aliases":["Rajyavardhan Rathore","Rathore"]},{"canonical":"Gagan Narang","prior":2,"aliases":[]},{"canonical":"Vijay Kumar","prior":1,"aliases":[]},{"canonical":"Swapnil Kusale","prior":1,"aliases":["Swapnil"]},{"canonical":"Aman Sehrawat","prior":1,"aliases":["Aman"]},{"canonical":"KD Jadhav","prior":1,"aliases":["K. D. Jadhav","Khashaba Dadasaheb Jadhav","Khashaba Jadhav"]},{"canonical":"Norman Pritchard","prior":0.5,"aliases":[]}]', NULL, 'Think of the shooting range, the wrestling mat, the boxing ring and the badminton court.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-play-gym', 'Name a piece of gym equipment.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The treadmill began as a punishment: in 1818 William Cubitt built treadwheels for English prisons, where inmates climbed for hours to grind grain. Indian wrestlers have trained with the heavy wooden mudgar for centuries.', 'https://en.wikipedia.org/wiki/Treadmill', 'Wikipedia: Treadmill', '2026-11-21', 'CC BY-SA 4.0', 'sport', 1, 0, '[{"canonical":"Treadmill","prior":22,"aliases":[]},{"canonical":"Dumbbell","prior":18,"aliases":["Dumbbells"]},{"canonical":"Barbell","prior":6,"aliases":["Barbells","Olympic bar","Rod"]},{"canonical":"Exercise bike","prior":6,"aliases":["Stationary bike","Exercise cycle","Spin bike","Static cycle","Gym cycle","Cycle"]},{"canonical":"Bench","prior":4,"aliases":["Bench press","Weight bench","Flat bench","Incline bench"]},{"canonical":"Kettlebell","prior":4,"aliases":["Kettle bell"]},{"canonical":"Elliptical","prior":3,"aliases":["Cross trainer","Elliptical trainer","Elliptical machine"]},{"canonical":"Skipping rope","prior":3,"aliases":["Jump rope","Skipping"]},{"canonical":"Rowing machine","prior":2,"aliases":["Rower","Ergometer","Erg"]},{"canonical":"Weight plates","prior":2,"aliases":["Plates","Weights"]},{"canonical":"Pull-up bar","prior":2,"aliases":["Chin-up bar","Pullup bar"]},{"canonical":"Yoga mat","prior":2,"aliases":["Mat","Exercise mat"]},{"canonical":"Resistance band","prior":2,"aliases":["Resistance bands","Theraband"]},{"canonical":"Medicine ball","prior":1,"aliases":["Med ball"]},{"canonical":"Swiss ball","prior":1,"aliases":["Exercise ball","Gym ball","Stability ball","Yoga ball"]},{"canonical":"Smith machine","prior":1,"aliases":[]},{"canonical":"Cable machine","prior":1,"aliases":["Cable crossover"]},{"canonical":"Lat pulldown machine","prior":1,"aliases":["Lat pulldown","Lat machine"]},{"canonical":"Leg press","prior":1,"aliases":["Leg press machine"]},{"canonical":"Squat rack","prior":1,"aliases":["Power rack","Squat cage"]},{"canonical":"Punching bag","prior":1,"aliases":["Boxing bag","Heavy bag","Punch bag"]},{"canonical":"Foam roller","prior":0.5,"aliases":[]},{"canonical":"Battle ropes","prior":0.5,"aliases":["Battle rope"]},{"canonical":"Stair climber","prior":0.5,"aliases":["Stepper","Stepmill","Step machine"]},{"canonical":"Pec deck","prior":0.5,"aliases":["Pec fly","Butterfly machine","Chest fly machine"]},{"canonical":"Ab roller","prior":0.5,"aliases":["Ab wheel"]},{"canonical":"Leg extension machine","prior":0.3,"aliases":["Leg extension"]},{"canonical":"Leg curl machine","prior":0.3,"aliases":["Leg curl","Hamstring curl"]},{"canonical":"Plyo box","prior":0.3,"aliases":["Jump box","Plyometric box"]},{"canonical":"EZ bar","prior":0.3,"aliases":["Curl bar","EZ curl bar"]},{"canonical":"Hand gripper","prior":0.3,"aliases":["Gripper","Hand grip"]},{"canonical":"TRX","prior":0.3,"aliases":["Suspension trainer"]},{"canonical":"Chest press machine","prior":0.3,"aliases":["Chest press"]},{"canonical":"Mudgar","prior":0.3,"aliases":["Gada","Indian club","Indian clubs","Mace"]},{"canonical":"Weighing scale","prior":0.3,"aliases":["Scale","Weighing machine"]},{"canonical":"Hack squat machine","prior":0.2,"aliases":["Hack squat"]},{"canonical":"Shoulder press machine","prior":0.2,"aliases":["Shoulder press"]},{"canonical":"Sandbag","prior":0.2,"aliases":[]},{"canonical":"Dip station","prior":0.2,"aliases":["Dip bar","Parallel bars"]},{"canonical":"Mirror","prior":0.2,"aliases":[]},{"canonical":"Air bike","prior":0.1,"aliases":["Assault bike"]},{"canonical":"Sled","prior":0.1,"aliases":["Prowler"]}]', NULL, 'Think of what you lift, what you run or pedal on without going anywhere, and what a pehlwan swings in an akhada.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-play-champions', 'Name a football club that has been champion of England.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Preston North End won the first league title in 1889 without losing a game, earning the name ''the Invincibles''. Arsenal matched that unbeaten season in 2003-04, and Leicester City won in 2016 at odds of 5,000 to 1.', 'https://en.wikipedia.org/wiki/List_of_English_football_champions', 'Wikipedia: List of English football champions', '2026-11-21', 'CC BY-SA 4.0', 'sport', 2, 0, '[{"canonical":"Manchester United","prior":20,"aliases":["Man United","Man Utd","Manchester Utd","Man U","United"]},{"canonical":"Liverpool","prior":14,"aliases":["Liverpool FC"]},{"canonical":"Manchester City","prior":12,"aliases":["Man City","City"]},{"canonical":"Chelsea","prior":12,"aliases":["Chelsea FC"]},{"canonical":"Arsenal","prior":12,"aliases":["The Gunners","Gunners"]},{"canonical":"Leicester City","prior":4,"aliases":["Leicester"]},{"canonical":"Tottenham Hotspur","prior":3,"aliases":["Tottenham","Spurs"]},{"canonical":"Blackburn Rovers","prior":2,"aliases":["Blackburn"]},{"canonical":"Everton","prior":2,"aliases":[]},{"canonical":"Aston Villa","prior":2,"aliases":["Villa"]},{"canonical":"Leeds United","prior":1,"aliases":["Leeds"]},{"canonical":"Newcastle United","prior":1,"aliases":["Newcastle"]},{"canonical":"Sunderland","prior":0.5,"aliases":[]},{"canonical":"Wolverhampton Wanderers","prior":0.5,"aliases":["Wolves","Wolverhampton"]},{"canonical":"Nottingham Forest","prior":0.5,"aliases":["Forest","Nottm Forest"]},{"canonical":"Derby County","prior":0.5,"aliases":["Derby"]},{"canonical":"Preston North End","prior":0.3,"aliases":["Preston"]},{"canonical":"Sheffield Wednesday","prior":0.3,"aliases":[]},{"canonical":"Huddersfield Town","prior":0.3,"aliases":["Huddersfield"]},{"canonical":"Burnley","prior":0.3,"aliases":[]},{"canonical":"Sheffield United","prior":0.2,"aliases":[]},{"canonical":"Portsmouth","prior":0.2,"aliases":[]},{"canonical":"West Bromwich Albion","prior":0.2,"aliases":["West Brom","WBA"]},{"canonical":"Ipswich Town","prior":0.2,"aliases":["Ipswich"]}]', NULL, 'Think of the big clubs from Manchester and London, then the old champions from Lancashire, Yorkshire and the Midlands.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-word-rhyme', 'Name a word that rhymes with "cat".', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'English has well over a hundred words ending in the ''-at'' sound. ''Aristocrat'', ''democrat'' and ''bureaucrat'' all share the Greek root ''kratos'', power.', 'https://en.wikipedia.org/wiki/Rhyme', 'Wikipedia: Rhyme', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"Hat","prior":18,"aliases":[]},{"canonical":"Bat","prior":18,"aliases":[]},{"canonical":"Mat","prior":14,"aliases":[]},{"canonical":"Rat","prior":14,"aliases":[]},{"canonical":"Fat","prior":6,"aliases":[]},{"canonical":"Sat","prior":4,"aliases":[]},{"canonical":"Pat","prior":3,"aliases":[]},{"canonical":"Chat","prior":3,"aliases":[]},{"canonical":"Flat","prior":3,"aliases":[]},{"canonical":"Vat","prior":1,"aliases":[]},{"canonical":"Brat","prior":1,"aliases":[]},{"canonical":"Gnat","prior":1,"aliases":[]},{"canonical":"Spat","prior":1,"aliases":[]},{"canonical":"Splat","prior":1,"aliases":[]},{"canonical":"Acrobat","prior":1,"aliases":[]},{"canonical":"Format","prior":1,"aliases":[]},{"canonical":"Habitat","prior":1,"aliases":[]},{"canonical":"Combat","prior":1,"aliases":[]},{"canonical":"Diplomat","prior":1,"aliases":[]},{"canonical":"Doormat","prior":1,"aliases":["Door mat"]},{"canonical":"Copycat","prior":0.5,"aliases":["Copy cat"]},{"canonical":"Thermostat","prior":0.5,"aliases":[]},{"canonical":"Aristocrat","prior":0.5,"aliases":[]},{"canonical":"Democrat","prior":0.5,"aliases":[]},{"canonical":"Bureaucrat","prior":0.5,"aliases":[]},{"canonical":"Wombat","prior":0.5,"aliases":[]},{"canonical":"Drat","prior":0.3,"aliases":[]},{"canonical":"Scat","prior":0.3,"aliases":[]},{"canonical":"Slat","prior":0.3,"aliases":[]},{"canonical":"Tat","prior":0.3,"aliases":[]},{"canonical":"Frat","prior":0.3,"aliases":[]},{"canonical":"Stat","prior":0.3,"aliases":[]},{"canonical":"Sprat","prior":0.3,"aliases":[]},{"canonical":"Tomcat","prior":0.3,"aliases":[]},{"canonical":"Bobcat","prior":0.3,"aliases":[]},{"canonical":"Meerkat","prior":0.3,"aliases":[]},{"canonical":"Autocrat","prior":0.3,"aliases":[]},{"canonical":"Cravat","prior":0.3,"aliases":[]},{"canonical":"Laundromat","prior":0.3,"aliases":[]},{"canonical":"Technocrat","prior":0.2,"aliases":[]},{"canonical":"Wildcat","prior":0.2,"aliases":[]},{"canonical":"Muskrat","prior":0.2,"aliases":[]},{"canonical":"Chitchat","prior":0.2,"aliases":["Chit-chat"]},{"canonical":"Dingbat","prior":0.1,"aliases":[]},{"canonical":"Ziggurat","prior":0.1,"aliases":[]},{"canonical":"Concordat","prior":0.1,"aliases":[]},{"canonical":"Rheostat","prior":0.1,"aliases":[]},{"canonical":"Photostat","prior":0.1,"aliases":[]},{"canonical":"Polecat","prior":0.1,"aliases":[]},{"canonical":"Begat","prior":0.1,"aliases":[]},{"canonical":"Automat","prior":0.1,"aliases":[]},{"canonical":"Hazmat","prior":0.1,"aliases":[]},{"canonical":"Bathmat","prior":0.1,"aliases":[]},{"canonical":"Cowpat","prior":0.1,"aliases":[]},{"canonical":"Mudflat","prior":0.1,"aliases":[]}]', NULL, 'Think of cricket gear, things on your head, rodents, and long words for people who govern.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-word-silentk', 'Name an English word with a silent K.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The K in knight, knee and knife was once pronounced, as it still is in German ''Knie''. English speakers stopped saying it in the 1600s, but printers had already fixed the spelling.', 'https://en.wikipedia.org/wiki/Silent_letter', 'Wikipedia: Silent letter', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"Knife","prior":22,"aliases":["Knives"]},{"canonical":"Knee","prior":14,"aliases":["Knees"]},{"canonical":"Know","prior":14,"aliases":["Known","Knew","Knows","Knowing"]},{"canonical":"Knock","prior":10,"aliases":["Knocking","Knocked","Knocks"]},{"canonical":"Knight","prior":8,"aliases":["Knights"]},{"canonical":"Knot","prior":6,"aliases":["Knots"]},{"canonical":"Knit","prior":4,"aliases":["Knitting","Knitted"]},{"canonical":"Knowledge","prior":4,"aliases":[]},{"canonical":"Knob","prior":3,"aliases":["Knobs"]},{"canonical":"Knuckle","prior":3,"aliases":["Knuckles"]},{"canonical":"Kneel","prior":2,"aliases":["Kneeling","Knelt"]},{"canonical":"Knack","prior":1,"aliases":[]},{"canonical":"Knead","prior":1,"aliases":[]},{"canonical":"Knapsack","prior":1,"aliases":[]},{"canonical":"Knickers","prior":1,"aliases":["Knicker"]},{"canonical":"Knave","prior":0.5,"aliases":[]},{"canonical":"Doorknob","prior":0.5,"aliases":["Door knob"]},{"canonical":"Acknowledge","prior":0.5,"aliases":["Acknowledgement","Acknowledgment"]},{"canonical":"Unknown","prior":0.5,"aliases":[]},{"canonical":"Kneecap","prior":0.5,"aliases":["Knee cap"]},{"canonical":"Knoll","prior":0.3,"aliases":[]},{"canonical":"Knell","prior":0.3,"aliases":[]},{"canonical":"Knickknack","prior":0.3,"aliases":["Knick-knack","Knick knack"]},{"canonical":"Penknife","prior":0.3,"aliases":[]},{"canonical":"Knockout","prior":0.3,"aliases":[]},{"canonical":"Know-how","prior":0.2,"aliases":["Knowhow"]},{"canonical":"Knighthood","prior":0.2,"aliases":[]},{"canonical":"Knitwear","prior":0.2,"aliases":[]},{"canonical":"Knobbly","prior":0.1,"aliases":[]},{"canonical":"Knapweed","prior":0.1,"aliases":[]},{"canonical":"Knurl","prior":0.1,"aliases":[]}]', NULL, 'Think of the body, the kitchen drawer, the chessboard and the front door.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-word-palindrome', 'Name a word that reads the same backwards.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Malayalam, the language of Kerala, is a palindrome in English spelling. The longest palindromic word in the Oxford English Dictionary is ''tattarrattat'', James Joyce''s word for a knock on the door.', 'https://en.wikipedia.org/wiki/Palindrome', 'Wikipedia: Palindrome', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"Madam","prior":18,"aliases":[]},{"canonical":"Level","prior":14,"aliases":[]},{"canonical":"Racecar","prior":10,"aliases":["Race car"]},{"canonical":"Radar","prior":10,"aliases":[]},{"canonical":"Mom","prior":6,"aliases":[]},{"canonical":"Dad","prior":6,"aliases":[]},{"canonical":"Noon","prior":6,"aliases":[]},{"canonical":"Civic","prior":4,"aliases":[]},{"canonical":"Kayak","prior":4,"aliases":[]},{"canonical":"Malayalam","prior":4,"aliases":[]},{"canonical":"Refer","prior":3,"aliases":[]},{"canonical":"Wow","prior":3,"aliases":[]},{"canonical":"Rotor","prior":2,"aliases":[]},{"canonical":"Tenet","prior":2,"aliases":[]},{"canonical":"Eye","prior":2,"aliases":[]},{"canonical":"Pop","prior":2,"aliases":[]},{"canonical":"Stats","prior":1,"aliases":[]},{"canonical":"Nun","prior":1,"aliases":[]},{"canonical":"Did","prior":1,"aliases":[]},{"canonical":"Peep","prior":1,"aliases":[]},{"canonical":"Deed","prior":1,"aliases":[]},{"canonical":"Sees","prior":1,"aliases":[]},{"canonical":"Solos","prior":1,"aliases":[]},{"canonical":"Rotator","prior":1,"aliases":[]},{"canonical":"Bob","prior":1,"aliases":[]},{"canonical":"Redder","prior":0.5,"aliases":[]},{"canonical":"Hannah","prior":0.5,"aliases":[]},{"canonical":"Pup","prior":0.5,"aliases":[]},{"canonical":"Sis","prior":0.5,"aliases":[]},{"canonical":"Nitin","prior":0.5,"aliases":[]},{"canonical":"Repaper","prior":0.3,"aliases":[]},{"canonical":"Reviver","prior":0.3,"aliases":[]},{"canonical":"Deified","prior":0.3,"aliases":[]},{"canonical":"Minim","prior":0.3,"aliases":[]},{"canonical":"Sagas","prior":0.3,"aliases":[]},{"canonical":"Nan","prior":0.3,"aliases":[]},{"canonical":"Pip","prior":0.3,"aliases":[]},{"canonical":"Tot","prior":0.3,"aliases":[]},{"canonical":"Toot","prior":0.3,"aliases":[]},{"canonical":"Gag","prior":0.3,"aliases":[]},{"canonical":"Gig","prior":0.3,"aliases":[]},{"canonical":"Bib","prior":0.3,"aliases":[]},{"canonical":"Ewe","prior":0.3,"aliases":[]},{"canonical":"Aha","prior":0.3,"aliases":[]},{"canonical":"Huh","prior":0.2,"aliases":[]},{"canonical":"Detartrated","prior":0.1,"aliases":[]},{"canonical":"Rotavator","prior":0.1,"aliases":[]},{"canonical":"Tattarrattat","prior":0.1,"aliases":[]},{"canonical":"Kinnikinnik","prior":0.1,"aliases":[]}]', NULL, 'Think of family members, a time of day, a language of India and what police use to catch speeders.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-word-three', 'Name an animal whose name has only three letters.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The emu, the gnu and the yak are all three-letter animals, and so is the kea, a mountain parrot from New Zealand famous for pulling the rubber seals off parked cars.', 'https://en.wikipedia.org/wiki/Kea', 'Wikipedia: Kea', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"Cat","prior":20,"aliases":[]},{"canonical":"Dog","prior":20,"aliases":[]},{"canonical":"Cow","prior":12,"aliases":[]},{"canonical":"Pig","prior":8,"aliases":[]},{"canonical":"Rat","prior":6,"aliases":[]},{"canonical":"Bat","prior":4,"aliases":[]},{"canonical":"Ant","prior":4,"aliases":[]},{"canonical":"Bee","prior":4,"aliases":[]},{"canonical":"Owl","prior":3,"aliases":[]},{"canonical":"Fox","prior":3,"aliases":[]},{"canonical":"Hen","prior":3,"aliases":[]},{"canonical":"Yak","prior":2,"aliases":[]},{"canonical":"Emu","prior":2,"aliases":[]},{"canonical":"Ape","prior":1,"aliases":[]},{"canonical":"Eel","prior":1,"aliases":[]},{"canonical":"Elk","prior":1,"aliases":[]},{"canonical":"Gnu","prior":1,"aliases":[]},{"canonical":"Ram","prior":1,"aliases":[]},{"canonical":"Ewe","prior":0.5,"aliases":[]},{"canonical":"Cod","prior":0.5,"aliases":[]},{"canonical":"Doe","prior":0.5,"aliases":[]},{"canonical":"Hog","prior":0.5,"aliases":[]},{"canonical":"Jay","prior":0.5,"aliases":[]},{"canonical":"Koi","prior":0.5,"aliases":[]},{"canonical":"Fly","prior":0.5,"aliases":[]},{"canonical":"Asp","prior":0.3,"aliases":[]},{"canonical":"Boa","prior":0.3,"aliases":[]},{"canonical":"Roo","prior":0.3,"aliases":[]},{"canonical":"Sow","prior":0.3,"aliases":[]},{"canonical":"Ray","prior":0.3,"aliases":[]},{"canonical":"Bug","prior":0.3,"aliases":[]},{"canonical":"Kea","prior":0.2,"aliases":[]},{"canonical":"Auk","prior":0.2,"aliases":[]},{"canonical":"Pug","prior":0.2,"aliases":[]},{"canonical":"Gar","prior":0.1,"aliases":[]},{"canonical":"Moa","prior":0.1,"aliases":[]},{"canonical":"Dzo","prior":0.1,"aliases":["Zho","Dzho"]},{"canonical":"Kob","prior":0.1,"aliases":[]},{"canonical":"Nit","prior":0.1,"aliases":[]}]', NULL, 'Think of the farmyard, the forest at night, Australia''s big bird and the shaggy cattle of the Himalaya.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-word-double', 'Name a fruit or vegetable with a double letter in its name.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Broccoli is the Italian plural of ''broccolo'', a little sprout, and the double C came with it. Cabbage, cauliflower, kale, kohlrabi and Brussels sprouts are all one species, Brassica oleracea.', 'https://en.wikipedia.org/wiki/Brassica_oleracea', 'Wikipedia: Brassica oleracea', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"Apple","prior":20,"aliases":["Apples"]},{"canonical":"Carrot","prior":12,"aliases":["Carrots"]},{"canonical":"Broccoli","prior":8,"aliases":[]},{"canonical":"Cabbage","prior":8,"aliases":["Red cabbage"]},{"canonical":"Strawberry","prior":6,"aliases":["Strawberries"]},{"canonical":"Pepper","prior":4,"aliases":["Peppers","Bell pepper","Green pepper"]},{"canonical":"Cherry","prior":4,"aliases":["Cherries"]},{"canonical":"Lychee","prior":3,"aliases":["Lychees"]},{"canonical":"Blueberry","prior":3,"aliases":["Blueberries"]},{"canonical":"Pineapple","prior":3,"aliases":["Pine apple"]},{"canonical":"Raspberry","prior":2,"aliases":["Raspberries"]},{"canonical":"Gooseberry","prior":2,"aliases":["Gooseberries"]},{"canonical":"Eggplant","prior":2,"aliases":["Egg plant"]},{"canonical":"Beetroot","prior":2,"aliases":["Beet","Beets"]},{"canonical":"Mushroom","prior":2,"aliases":["Mushrooms"]},{"canonical":"Blackberry","prior":1,"aliases":["Blackberries"]},{"canonical":"Mulberry","prior":1,"aliases":["Mulberries"]},{"canonical":"Cranberry","prior":1,"aliases":["Cranberries"]},{"canonical":"Zucchini","prior":1,"aliases":[]},{"canonical":"Leek","prior":1,"aliases":["Leeks"]},{"canonical":"Sweet potato","prior":1,"aliases":[]},{"canonical":"Passion fruit","prior":1,"aliases":["Passionfruit"]},{"canonical":"Brussels sprouts","prior":1,"aliases":["Brussels sprout","Brussel sprouts"]},{"canonical":"Bitter gourd","prior":1,"aliases":["Bitter melon"]},{"canonical":"Bottle gourd","prior":1,"aliases":[]},{"canonical":"Chilli","prior":1,"aliases":["Chillies","Chilli pepper"]},{"canonical":"Arrowroot","prior":0.5,"aliases":[]},{"canonical":"Persimmon","prior":0.5,"aliases":[]},{"canonical":"Butternut squash","prior":0.5,"aliases":["Butternut"]},{"canonical":"Shallot","prior":0.5,"aliases":["Shallots"]},{"canonical":"Collard greens","prior":0.3,"aliases":["Collards"]},{"canonical":"Mangosteen","prior":0.3,"aliases":[]},{"canonical":"Custard apple","prior":0.3,"aliases":[]},{"canonical":"Sweetcorn","prior":0.3,"aliases":["Sweet corn"]},{"canonical":"Green beans","prior":0.3,"aliases":["Green bean"]},{"canonical":"Cassava","prior":0.3,"aliases":[]},{"canonical":"Tamarillo","prior":0.2,"aliases":[]},{"canonical":"Elderberry","prior":0.2,"aliases":["Elderberries"]},{"canonical":"Watercress","prior":0.2,"aliases":[]},{"canonical":"Boysenberry","prior":0.1,"aliases":[]},{"canonical":"Loganberry","prior":0.1,"aliases":[]},{"canonical":"Cloudberry","prior":0.1,"aliases":[]},{"canonical":"Lingonberry","prior":0.1,"aliases":[]},{"canonical":"Huckleberry","prior":0.1,"aliases":[]},{"canonical":"Broccolini","prior":0.1,"aliases":[]},{"canonical":"Tomatillo","prior":0.1,"aliases":[]},{"canonical":"Mirabelle","prior":0.1,"aliases":[]},{"canonical":"Sorrel","prior":0.1,"aliases":[]},{"canonical":"Kiwiberry","prior":0.1,"aliases":[]}]', NULL, 'Think of the fruit bowl, the berry patch, and vegetables that are green, purple or orange.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-word-ball', 'Name a word or phrase that ends in "ball", like football.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Snowball fights are pictured in medieval prayer books, long before football had rules. And a ''ball'' you dance at comes from a different word entirely, the Latin ''ballare'', to dance.', 'https://en.wikipedia.org/wiki/Ball', 'Wikipedia: Ball', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"Basketball","prior":20,"aliases":["Basket ball"]},{"canonical":"Volleyball","prior":12,"aliases":["Volley ball"]},{"canonical":"Baseball","prior":8,"aliases":[]},{"canonical":"Snowball","prior":8,"aliases":["Snow ball"]},{"canonical":"Netball","prior":4,"aliases":[]},{"canonical":"Handball","prior":4,"aliases":[]},{"canonical":"Eyeball","prior":4,"aliases":[]},{"canonical":"Meatball","prior":4,"aliases":["Meatballs"]},{"canonical":"Fireball","prior":3,"aliases":[]},{"canonical":"Paintball","prior":2,"aliases":[]},{"canonical":"Softball","prior":2,"aliases":[]},{"canonical":"Dodgeball","prior":2,"aliases":[]},{"canonical":"Cannonball","prior":2,"aliases":["Cannon ball"]},{"canonical":"Golf ball","prior":2,"aliases":[]},{"canonical":"Gumball","prior":1,"aliases":[]},{"canonical":"Hairball","prior":1,"aliases":[]},{"canonical":"Mothball","prior":1,"aliases":["Moth ball","Mothballs"]},{"canonical":"Oddball","prior":1,"aliases":[]},{"canonical":"Screwball","prior":1,"aliases":[]},{"canonical":"Pinball","prior":1,"aliases":[]},{"canonical":"Tennis ball","prior":1,"aliases":[]},{"canonical":"Crystal ball","prior":1,"aliases":[]},{"canonical":"Disco ball","prior":1,"aliases":["Mirror ball"]},{"canonical":"Wrecking ball","prior":1,"aliases":[]},{"canonical":"Highball","prior":0.5,"aliases":[]},{"canonical":"Lowball","prior":0.5,"aliases":[]},{"canonical":"Cricket ball","prior":0.5,"aliases":[]},{"canonical":"Kickball","prior":0.5,"aliases":[]},{"canonical":"Throwball","prior":0.5,"aliases":[]},{"canonical":"Pickleball","prior":0.5,"aliases":[]},{"canonical":"Medicine ball","prior":0.5,"aliases":[]},{"canonical":"Beach ball","prior":0.5,"aliases":[]},{"canonical":"Bowling ball","prior":0.5,"aliases":[]},{"canonical":"Cotton ball","prior":0.5,"aliases":["Cotton wool ball"]},{"canonical":"Curveball","prior":0.5,"aliases":[]},{"canonical":"American football","prior":0.5,"aliases":[]},{"canonical":"Masked ball","prior":0.3,"aliases":["Masquerade ball"]},{"canonical":"Stickball","prior":0.3,"aliases":[]},{"canonical":"Racquetball","prior":0.3,"aliases":[]},{"canonical":"Furball","prior":0.3,"aliases":[]},{"canonical":"Goofball","prior":0.3,"aliases":[]},{"canonical":"Hardball","prior":0.3,"aliases":[]},{"canonical":"Eight ball","prior":0.3,"aliases":["8-ball","8 ball"]},{"canonical":"Cue ball","prior":0.3,"aliases":[]},{"canonical":"Soccer ball","prior":0.3,"aliases":[]},{"canonical":"Korfball","prior":0.2,"aliases":[]},{"canonical":"Paddleball","prior":0.2,"aliases":[]},{"canonical":"Spitball","prior":0.2,"aliases":[]},{"canonical":"Fastball","prior":0.2,"aliases":[]},{"canonical":"Blackball","prior":0.2,"aliases":[]},{"canonical":"Matzo ball","prior":0.2,"aliases":[]},{"canonical":"Ping-pong ball","prior":0.2,"aliases":["Ping pong ball"]},{"canonical":"Puffball","prior":0.1,"aliases":[]},{"canonical":"Gutterball","prior":0.1,"aliases":[]},{"canonical":"Rollerball","prior":0.1,"aliases":[]},{"canonical":"Slimeball","prior":0.1,"aliases":[]}]', NULL, 'Think of sports with hoops and nets, winter fights, Italian food and what a fortune-teller stares into.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-word-sun', 'Name a word that starts with "sun".', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Sunday is named after the Sun, as Monday is after the Moon. One story says the sundae got its odd spelling to dodge American laws against selling ice cream sodas on Sundays.', 'https://en.wikipedia.org/wiki/Sunday', 'Wikipedia: Sunday', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"Sunday","prior":16,"aliases":[]},{"canonical":"Sunflower","prior":14,"aliases":[]},{"canonical":"Sunglasses","prior":12,"aliases":["Sun glasses"]},{"canonical":"Sunset","prior":10,"aliases":[]},{"canonical":"Sunrise","prior":10,"aliases":[]},{"canonical":"Sunlight","prior":6,"aliases":[]},{"canonical":"Sunshine","prior":6,"aliases":[]},{"canonical":"Sunburn","prior":4,"aliases":[]},{"canonical":"Sunscreen","prior":4,"aliases":[]},{"canonical":"Sunny","prior":4,"aliases":[]},{"canonical":"Sundae","prior":2,"aliases":[]},{"canonical":"Sundial","prior":2,"aliases":[]},{"canonical":"Sunbathe","prior":2,"aliases":["Sunbathing"]},{"canonical":"Sunroof","prior":2,"aliases":[]},{"canonical":"Sunstroke","prior":2,"aliases":[]},{"canonical":"Sunspot","prior":1,"aliases":[]},{"canonical":"Sunbeam","prior":1,"aliases":[]},{"canonical":"Sundown","prior":1,"aliases":[]},{"canonical":"Sunblock","prior":1,"aliases":[]},{"canonical":"Sunken","prior":1,"aliases":[]},{"canonical":"Sung","prior":1,"aliases":[]},{"canonical":"Suntan","prior":1,"aliases":["Sun tan"]},{"canonical":"Sundry","prior":0.5,"aliases":["Sundries"]},{"canonical":"Sunder","prior":0.5,"aliases":[]},{"canonical":"Sunlit","prior":0.5,"aliases":[]},{"canonical":"Sunbird","prior":0.3,"aliases":[]},{"canonical":"Sunfish","prior":0.3,"aliases":[]},{"canonical":"Sunhat","prior":0.3,"aliases":["Sun hat"]},{"canonical":"Sunbed","prior":0.3,"aliases":[]},{"canonical":"Sunni","prior":0.3,"aliases":[]},{"canonical":"Sundarbans","prior":0.3,"aliases":[]},{"canonical":"Sun-kissed","prior":0.2,"aliases":["Sunkissed"]},{"canonical":"Sundress","prior":0.2,"aliases":[]},{"canonical":"Sunroom","prior":0.2,"aliases":[]},{"canonical":"Sunshade","prior":0.2,"aliases":[]},{"canonical":"Sunup","prior":0.1,"aliases":[]},{"canonical":"Sunnah","prior":0.1,"aliases":[]},{"canonical":"Sunstone","prior":0.1,"aliases":[]}]', NULL, 'Think of the days of the week, a yellow flower, what you wear at the beach and what happens at dawn and dusk.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-tech-battery', 'Name something that runs on batteries.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Alessandro Volta built the first true battery in 1800 from a stack of zinc and copper discs separated by brine-soaked cloth, which is why we still measure electricity in volts.', 'https://en.wikipedia.org/wiki/Electric_battery', 'Wikipedia: Electric battery', '2026-11-21', 'CC BY-SA 4.0', 'technology', 1, 0, '[{"canonical":"Remote control","prior":18,"aliases":["Remote","TV remote"]},{"canonical":"Phone","prior":10,"aliases":["Mobile phone","Mobile","Smartphone","Cell phone","Cellphone"]},{"canonical":"Watch","prior":8,"aliases":["Wristwatch"]},{"canonical":"Torch","prior":8,"aliases":["Flashlight"]},{"canonical":"Clock","prior":6,"aliases":["Wall clock","Alarm clock"]},{"canonical":"Laptop","prior":6,"aliases":[]},{"canonical":"Toys","prior":4,"aliases":["Toy","Toy car","RC car","Remote control car"]},{"canonical":"Electric car","prior":4,"aliases":["EV","Tesla","Electric vehicle"]},{"canonical":"Calculator","prior":4,"aliases":[]},{"canonical":"Camera","prior":2,"aliases":["Digital camera"]},{"canonical":"Headphones","prior":2,"aliases":["Earbuds","Earphones","AirPods","Wireless earphones"]},{"canonical":"Trimmer","prior":2,"aliases":["Shaver","Electric shaver","Razor","Electric razor","Beard trimmer"]},{"canonical":"Smoke detector","prior":1,"aliases":["Smoke alarm","Fire alarm"]},{"canonical":"Hearing aid","prior":1,"aliases":[]},{"canonical":"Pacemaker","prior":1,"aliases":[]},{"canonical":"Electric toothbrush","prior":1,"aliases":[]},{"canonical":"Weighing scale","prior":1,"aliases":["Digital scale","Bathroom scale","Scale"]},{"canonical":"Thermometer","prior":1,"aliases":["Digital thermometer"]},{"canonical":"Drone","prior":1,"aliases":[]},{"canonical":"Tablet","prior":1,"aliases":["iPad"]},{"canonical":"Game controller","prior":1,"aliases":["Controller","Joystick","Gamepad"]},{"canonical":"Wireless mouse","prior":1,"aliases":["Mouse","Computer mouse"]},{"canonical":"Radio","prior":1,"aliases":["Transistor"]},{"canonical":"Electric scooter","prior":1,"aliases":["E-scooter","Electric bike","E-bike"]},{"canonical":"Mosquito bat","prior":1,"aliases":["Mosquito racket","Electric racket","Mosquito swatter","Zapper"]},{"canonical":"Bluetooth speaker","prior":1,"aliases":["Speaker","Portable speaker"]},{"canonical":"Car","prior":1,"aliases":[]},{"canonical":"Doorbell","prior":0.5,"aliases":["Wireless doorbell"]},{"canonical":"Power bank","prior":0.5,"aliases":[]},{"canonical":"E-reader","prior":0.5,"aliases":["Kindle","Ebook reader"]},{"canonical":"Wireless keyboard","prior":0.5,"aliases":["Keyboard"]},{"canonical":"Glucometer","prior":0.5,"aliases":["Glucose meter","Blood sugar meter"]},{"canonical":"BP monitor","prior":0.5,"aliases":["Blood pressure monitor","BP machine"]},{"canonical":"Robot vacuum","prior":0.5,"aliases":["Roomba"]},{"canonical":"Cordless drill","prior":0.5,"aliases":["Drill"]},{"canonical":"Smartwatch","prior":0.5,"aliases":["Smart watch","Fitness tracker","Fitbit","Apple Watch"]},{"canonical":"Walkie-talkie","prior":0.5,"aliases":["Walkie talkie"]},{"canonical":"Inverter","prior":0.5,"aliases":["UPS"]},{"canonical":"Emergency light","prior":0.5,"aliases":["Rechargeable light","Emergency lamp"]},{"canonical":"Satellite","prior":0.3,"aliases":[]},{"canonical":"Mars rover","prior":0.3,"aliases":["Rover"]},{"canonical":"Cordless phone","prior":0.3,"aliases":[]},{"canonical":"Submarine","prior":0.2,"aliases":[]},{"canonical":"Golf cart","prior":0.2,"aliases":[]},{"canonical":"Forklift","prior":0.1,"aliases":[]},{"canonical":"Insulin pump","prior":0.1,"aliases":[]},{"canonical":"Musical greeting card","prior":0.1,"aliases":["Greeting card"]}]', NULL, 'Think of the sofa, the bathroom shelf, a power cut at night and the racket you swing in a monsoon evening.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-tech-social', 'Name a social media app, past or present.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Orkut, Google''s social network, was hugely popular in India and Brazil before it shut down in 2014. TikTok had about 200 million users in India when the country banned it in 2020.', 'https://en.wikipedia.org/wiki/Social_media', 'Wikipedia: Social media', '2026-11-21', 'CC BY-SA 4.0', 'technology', 1, 0, '[{"canonical":"Instagram","prior":22,"aliases":["Insta","IG"]},{"canonical":"Facebook","prior":18,"aliases":["FB"]},{"canonical":"WhatsApp","prior":14,"aliases":["Whatsapp"]},{"canonical":"Snapchat","prior":8,"aliases":["Snap"]},{"canonical":"X","prior":6,"aliases":["Twitter"]},{"canonical":"YouTube","prior":6,"aliases":[]},{"canonical":"LinkedIn","prior":4,"aliases":[]},{"canonical":"TikTok","prior":4,"aliases":["Tik Tok","Douyin"]},{"canonical":"Telegram","prior":3,"aliases":[]},{"canonical":"Reddit","prior":3,"aliases":[]},{"canonical":"Pinterest","prior":2,"aliases":[]},{"canonical":"Threads","prior":2,"aliases":[]},{"canonical":"Orkut","prior":2,"aliases":[]},{"canonical":"ShareChat","prior":1,"aliases":["Share Chat"]},{"canonical":"Moj","prior":1,"aliases":[]},{"canonical":"Koo","prior":1,"aliases":[]},{"canonical":"Discord","prior":1,"aliases":[]},{"canonical":"Tumblr","prior":1,"aliases":[]},{"canonical":"MySpace","prior":1,"aliases":[]},{"canonical":"Quora","prior":1,"aliases":[]},{"canonical":"Josh","prior":0.5,"aliases":[]},{"canonical":"Clubhouse","prior":0.5,"aliases":[]},{"canonical":"BeReal","prior":0.5,"aliases":[]},{"canonical":"Hike","prior":0.5,"aliases":["Hike Messenger"]},{"canonical":"Vine","prior":0.5,"aliases":[]},{"canonical":"Google+","prior":0.5,"aliases":["Google Plus"]},{"canonical":"WeChat","prior":0.5,"aliases":[]},{"canonical":"Bluesky","prior":0.5,"aliases":[]},{"canonical":"Signal","prior":0.5,"aliases":[]},{"canonical":"Messenger","prior":0.5,"aliases":["Facebook Messenger"]},{"canonical":"Mastodon","prior":0.3,"aliases":[]},{"canonical":"Twitch","prior":0.3,"aliases":[]},{"canonical":"Roposo","prior":0.3,"aliases":[]},{"canonical":"Tinder","prior":0.3,"aliases":[]},{"canonical":"Skype","prior":0.3,"aliases":[]},{"canonical":"Musical.ly","prior":0.3,"aliases":["Musically"]},{"canonical":"Chingari","prior":0.2,"aliases":[]},{"canonical":"Bumble","prior":0.2,"aliases":[]},{"canonical":"Weibo","prior":0.2,"aliases":[]},{"canonical":"LINE","prior":0.2,"aliases":["Line"]},{"canonical":"Friendster","prior":0.2,"aliases":[]},{"canonical":"Yahoo Messenger","prior":0.2,"aliases":[]},{"canonical":"MSN Messenger","prior":0.2,"aliases":["Windows Live Messenger","MSN"]},{"canonical":"Mitron","prior":0.1,"aliases":[]},{"canonical":"VK","prior":0.1,"aliases":[]},{"canonical":"Kik","prior":0.1,"aliases":[]},{"canonical":"Bebo","prior":0.1,"aliases":[]},{"canonical":"Hi5","prior":0.1,"aliases":[]},{"canonical":"Periscope","prior":0.1,"aliases":[]},{"canonical":"Truth Social","prior":0.1,"aliases":[]},{"canonical":"Lemon8","prior":0.1,"aliases":[]}]', NULL, 'Think of the Google network India loved in 2008, apps banned in 2020, and the ones you open first thing in the morning.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-tech-key', 'Name a key on a computer keyboard that isn''t a letter or a number.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Escape key was added to keyboards in 1960 by Bob Bemer, an IBM programmer who also helped put the backslash into computer character sets. The QWERTY layout itself dates from typewriters of the 1870s.', 'https://en.wikipedia.org/wiki/Computer_keyboard', 'Wikipedia: Computer keyboard', '2026-11-21', 'CC BY-SA 4.0', 'technology', 1, 0, '[{"canonical":"Enter","prior":18,"aliases":["Return","Enter key"]},{"canonical":"Space bar","prior":14,"aliases":["Space","Spacebar"]},{"canonical":"Shift","prior":12,"aliases":[]},{"canonical":"Backspace","prior":10,"aliases":["Back space"]},{"canonical":"Escape","prior":6,"aliases":["Esc"]},{"canonical":"Control","prior":6,"aliases":["Ctrl"]},{"canonical":"Alt","prior":6,"aliases":["Alt Gr","Option"]},{"canonical":"Tab","prior":6,"aliases":[]},{"canonical":"Caps Lock","prior":6,"aliases":["Capslock","Caps"]},{"canonical":"Delete","prior":4,"aliases":["Del"]},{"canonical":"Arrow keys","prior":3,"aliases":["Arrow","Arrows","Up arrow","Down arrow","Left arrow","Right arrow"]},{"canonical":"Windows key","prior":2,"aliases":["Windows","Win","Start","Super"]},{"canonical":"Function keys","prior":2,"aliases":["F1","F2","F5","F12","F keys"]},{"canonical":"Fn","prior":1,"aliases":["Function"]},{"canonical":"Home","prior":1,"aliases":[]},{"canonical":"End","prior":1,"aliases":[]},{"canonical":"Page Up","prior":1,"aliases":["PgUp"]},{"canonical":"Insert","prior":1,"aliases":["Ins"]},{"canonical":"Print Screen","prior":1,"aliases":["PrtSc","Prt Sc","PrintScreen"]},{"canonical":"Num Lock","prior":1,"aliases":["Numlock"]},{"canonical":"Command","prior":1,"aliases":["Cmd"]},{"canonical":"Page Down","prior":0.5,"aliases":["PgDn"]},{"canonical":"Scroll Lock","prior":0.5,"aliases":[]},{"canonical":"Pause","prior":0.5,"aliases":["Break","Pause Break"]},{"canonical":"Full stop","prior":0.5,"aliases":["Period","Dot"]},{"canonical":"Comma","prior":0.5,"aliases":[]},{"canonical":"Menu key","prior":0.3,"aliases":["Application key","Context menu key"]},{"canonical":"Semicolon","prior":0.3,"aliases":[]},{"canonical":"Slash","prior":0.3,"aliases":["Forward slash"]},{"canonical":"Backslash","prior":0.3,"aliases":[]},{"canonical":"Question mark","prior":0.3,"aliases":[]},{"canonical":"Plus","prior":0.3,"aliases":["Plus sign"]},{"canonical":"Minus","prior":0.3,"aliases":["Hyphen","Dash"]},{"canonical":"Equals","prior":0.2,"aliases":["Equals sign"]},{"canonical":"Tilde","prior":0.2,"aliases":[]},{"canonical":"Square bracket","prior":0.2,"aliases":["Bracket","Brackets"]},{"canonical":"Apostrophe","prior":0.2,"aliases":["Quote","Quotation mark"]},{"canonical":"At sign","prior":0.2,"aliases":["At"]},{"canonical":"Hash","prior":0.2,"aliases":["Pound","Hash key"]},{"canonical":"Power button","prior":0.2,"aliases":["Power"]},{"canonical":"Volume keys","prior":0.2,"aliases":["Volume","Mute"]},{"canonical":"Brightness","prior":0.1,"aliases":[]},{"canonical":"Eject","prior":0.1,"aliases":[]},{"canonical":"SysRq","prior":0.1,"aliases":["Sys Rq","System Request"]},{"canonical":"Copilot key","prior":0.1,"aliases":["Copilot"]}]', NULL, 'Think of the keys your little finger reaches, the ones along the top row, and the ones that move the cursor.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-tech-phone', 'Name a mobile phone brand, past or present.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Nokia 1100, a simple phone with a built-in torch, sold about 250 million units, more than any other phone model, many of them in India and other fast-growing markets.', 'https://en.wikipedia.org/wiki/Nokia_1100', 'Wikipedia: Nokia 1100', '2026-11-21', 'CC BY-SA 4.0', 'technology', 1, 0, '[{"canonical":"Samsung","prior":18,"aliases":[]},{"canonical":"Apple","prior":16,"aliases":["iPhone"]},{"canonical":"Nokia","prior":10,"aliases":[]},{"canonical":"Xiaomi","prior":6,"aliases":["Mi","Redmi","Poco"]},{"canonical":"OnePlus","prior":6,"aliases":["One Plus"]},{"canonical":"Vivo","prior":6,"aliases":[]},{"canonical":"Oppo","prior":6,"aliases":[]},{"canonical":"Realme","prior":4,"aliases":[]},{"canonical":"Motorola","prior":4,"aliases":["Moto"]},{"canonical":"Google Pixel","prior":2,"aliases":["Pixel","Google"]},{"canonical":"Micromax","prior":2,"aliases":[]},{"canonical":"Sony","prior":2,"aliases":["Sony Ericsson","Sony Xperia","Ericsson"]},{"canonical":"BlackBerry","prior":2,"aliases":[]},{"canonical":"Huawei","prior":1,"aliases":[]},{"canonical":"Honor","prior":1,"aliases":[]},{"canonical":"LG","prior":1,"aliases":[]},{"canonical":"HTC","prior":1,"aliases":[]},{"canonical":"Lava","prior":1,"aliases":[]},{"canonical":"Nothing","prior":1,"aliases":["Nothing Phone","CMF"]},{"canonical":"Karbonn","prior":0.5,"aliases":[]},{"canonical":"Intex","prior":0.5,"aliases":[]},{"canonical":"Asus","prior":0.5,"aliases":["Zenfone"]},{"canonical":"Lenovo","prior":0.5,"aliases":[]},{"canonical":"iQOO","prior":0.5,"aliases":["Iqoo"]},{"canonical":"Infinix","prior":0.5,"aliases":[]},{"canonical":"Tecno","prior":0.5,"aliases":[]},{"canonical":"itel","prior":0.3,"aliases":[]},{"canonical":"Spice","prior":0.3,"aliases":[]},{"canonical":"Gionee","prior":0.3,"aliases":[]},{"canonical":"Celkon","prior":0.2,"aliases":[]},{"canonical":"Panasonic","prior":0.2,"aliases":[]},{"canonical":"Alcatel","prior":0.2,"aliases":[]},{"canonical":"ZTE","prior":0.2,"aliases":[]},{"canonical":"Siemens","prior":0.2,"aliases":[]},{"canonical":"Jio","prior":0.2,"aliases":["JioPhone","Jio Phone","Lyf"]},{"canonical":"Microsoft Lumia","prior":0.2,"aliases":["Lumia","Windows Phone","Microsoft"]},{"canonical":"Palm","prior":0.1,"aliases":[]},{"canonical":"Fairphone","prior":0.1,"aliases":[]},{"canonical":"Meizu","prior":0.1,"aliases":[]},{"canonical":"Vertu","prior":0.1,"aliases":[]},{"canonical":"Philips","prior":0.1,"aliases":[]}]', NULL, 'Think of the Finnish giant of the 2000s, Indian brands of the 2010s, and the Chinese names on billboards today.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-tech-console', 'Name a video game console.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Sony built the PlayStation only after a deal to make a CD add-on for Nintendo fell apart in 1991. In 1990s India, many children''s first console was a ''TV game'' clone of the Nintendo Famicom.', 'https://en.wikipedia.org/wiki/Home_video_game_console', 'Wikipedia: Home video game console', '2026-11-21', 'CC BY-SA 4.0', 'technology', 1, 0, '[{"canonical":"PlayStation","prior":22,"aliases":["PS","PS1","PS2","PS3","PS4","PS5","PlayStation 5","Sony PlayStation"]},{"canonical":"Xbox","prior":16,"aliases":["Xbox 360","Xbox One","Xbox Series X"]},{"canonical":"Nintendo Switch","prior":10,"aliases":["Switch","Switch 2"]},{"canonical":"Wii","prior":4,"aliases":["Nintendo Wii","Wii U"]},{"canonical":"Game Boy","prior":3,"aliases":["Gameboy","Game Boy Advance","GBA"]},{"canonical":"Nintendo DS","prior":2,"aliases":["DS","3DS","Nintendo 3DS"]},{"canonical":"PSP","prior":2,"aliases":["PlayStation Portable"]},{"canonical":"Nintendo 64","prior":1,"aliases":["N64"]},{"canonical":"NES","prior":1,"aliases":["Nintendo Entertainment System","Famicom"]},{"canonical":"SNES","prior":1,"aliases":["Super Nintendo","Super NES"]},{"canonical":"GameCube","prior":1,"aliases":[]},{"canonical":"Sega Mega Drive","prior":1,"aliases":["Mega Drive","Sega Genesis","Genesis","Sega"]},{"canonical":"Atari 2600","prior":1,"aliases":["Atari"]},{"canonical":"Steam Deck","prior":1,"aliases":[]},{"canonical":"Brick Game","prior":1,"aliases":["Brick game","9999 in 1","Tetris machine"]},{"canonical":"Dreamcast","prior":0.5,"aliases":["Sega Dreamcast"]},{"canonical":"TV game","prior":0.5,"aliases":["Little Master","Subor","Famiclone"]},{"canonical":"PS Vita","prior":0.3,"aliases":["PlayStation Vita","Vita"]},{"canonical":"Meta Quest","prior":0.3,"aliases":["Oculus","Oculus Quest","Quest"]},{"canonical":"Sega Saturn","prior":0.2,"aliases":["Saturn"]},{"canonical":"Game Gear","prior":0.2,"aliases":["Sega Game Gear"]},{"canonical":"Neo Geo","prior":0.1,"aliases":[]},{"canonical":"TurboGrafx-16","prior":0.1,"aliases":["PC Engine"]},{"canonical":"Ouya","prior":0.1,"aliases":[]},{"canonical":"Virtual Boy","prior":0.1,"aliases":[]},{"canonical":"Magnavox Odyssey","prior":0.1,"aliases":["Odyssey"]},{"canonical":"Intellivision","prior":0.1,"aliases":[]},{"canonical":"ColecoVision","prior":0.1,"aliases":[]},{"canonical":"3DO","prior":0.1,"aliases":[]},{"canonical":"Atari Jaguar","prior":0.1,"aliases":["Jaguar"]},{"canonical":"Atari Lynx","prior":0.1,"aliases":["Lynx"]},{"canonical":"Game & Watch","prior":0.1,"aliases":["Game and Watch"]},{"canonical":"Sega Master System","prior":0.1,"aliases":["Master System"]}]', NULL, 'Think of the big three console makers across the decades, their 1990s rivals, and the handhelds in school bags.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-tech-file', 'Name a file extension, like .pdf.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'So many old extensions are exactly three letters because MS-DOS allowed file names of only eight characters plus a three-letter extension. India''s first phone videos were mostly .3gp files.', 'https://en.wikipedia.org/wiki/Filename_extension', 'Wikipedia: Filename extension', '2026-11-21', 'CC BY-SA 4.0', 'technology', 2, 0, '[{"canonical":"JPG","prior":16,"aliases":["JPEG",".jpg",".jpeg"]},{"canonical":"DOCX","prior":10,"aliases":["DOC",".docx",".doc"]},{"canonical":"MP3","prior":10,"aliases":[".mp3"]},{"canonical":"PNG","prior":8,"aliases":[".png"]},{"canonical":"MP4","prior":8,"aliases":[".mp4"]},{"canonical":"EXE","prior":6,"aliases":[".exe"]},{"canonical":"TXT","prior":6,"aliases":[".txt"]},{"canonical":"XLSX","prior":4,"aliases":["XLS",".xlsx",".xls"]},{"canonical":"PPTX","prior":4,"aliases":["PPT",".pptx",".ppt"]},{"canonical":"GIF","prior":4,"aliases":[".gif"]},{"canonical":"ZIP","prior":4,"aliases":[".zip"]},{"canonical":"HTML","prior":3,"aliases":["HTM",".html"]},{"canonical":"CSV","prior":2,"aliases":[".csv"]},{"canonical":"APK","prior":2,"aliases":[".apk"]},{"canonical":"MOV","prior":1,"aliases":[]},{"canonical":"AVI","prior":1,"aliases":[]},{"canonical":"MKV","prior":1,"aliases":[]},{"canonical":"WAV","prior":1,"aliases":[]},{"canonical":"RAR","prior":1,"aliases":[]},{"canonical":"PY","prior":1,"aliases":[]},{"canonical":"JS","prior":1,"aliases":[]},{"canonical":"CSS","prior":1,"aliases":[]},{"canonical":"JSON","prior":1,"aliases":[]},{"canonical":"SVG","prior":1,"aliases":[]},{"canonical":"PSD","prior":1,"aliases":[]},{"canonical":"ISO","prior":0.5,"aliases":[]},{"canonical":"DMG","prior":0.5,"aliases":[]},{"canonical":"BMP","prior":0.5,"alias