INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-tech-screen', 'Name something that has a screen.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Old cathode-ray TVs, the bulky boxes of the 1990s, fired a beam of electrons at the inside of the glass. India''s first TV broadcast went out from Delhi in 1959, and colour arrived for the 1982 Asian Games.', 'https://en.wikipedia.org/wiki/Display_device', 'Wikipedia: Display device', '2026-11-21', 'CC BY-SA 4.0', 'technology', 1, 0, '[{"canonical":"Television","prior":18,"aliases":["TV","Telly","Smart TV"]},{"canonical":"Phone","prior":16,"aliases":["Mobile","Smartphone","Mobile phone","Cell phone"]},{"canonical":"Laptop","prior":12,"aliases":["Notebook"]},{"canonical":"Computer","prior":10,"aliases":["PC","Desktop"]},{"canonical":"Tablet","prior":4,"aliases":["iPad"]},{"canonical":"Smartwatch","prior":3,"aliases":["Smart watch","Apple Watch","Digital watch","Watch"]},{"canonical":"Cinema","prior":3,"aliases":["Movie theatre","Movie theater","Theatre","Multiplex","Cinema hall"]},{"canonical":"Monitor","prior":2,"aliases":[]},{"canonical":"ATM","prior":2,"aliases":["Cash machine"]},{"canonical":"Calculator","prior":2,"aliases":[]},{"canonical":"Microwave","prior":1,"aliases":["Microwave oven"]},{"canonical":"Car dashboard","prior":1,"aliases":["Car","Dashboard","Car infotainment"]},{"canonical":"Camera","prior":1,"aliases":["Digital camera","DSLR"]},{"canonical":"Handheld console","prior":1,"aliases":["Nintendo Switch","Game Boy","PSP"]},{"canonical":"E-reader","prior":1,"aliases":["Kindle"]},{"canonical":"Projector","prior":0.5,"aliases":[]},{"canonical":"Washing machine","prior":0.5,"aliases":[]},{"canonical":"Window","prior":0.5,"aliases":["Window screen","Screen door","Fly screen","Mosquito mesh"]},{"canonical":"Refrigerator","prior":0.3,"aliases":["Smart fridge","Fridge"]},{"canonical":"Billboard","prior":0.3,"aliases":["Digital billboard","LED billboard"]},{"canonical":"Treadmill","prior":0.3,"aliases":[]},{"canonical":"Printer","prior":0.3,"aliases":[]},{"canonical":"Seatback screen","prior":0.3,"aliases":["Airplane seat","Flight","Aeroplane"]},{"canonical":"Card machine","prior":0.2,"aliases":["POS machine","Swipe machine","Card reader"]},{"canonical":"Patient monitor","prior":0.2,"aliases":["Heart monitor","ECG machine","ECG"]},{"canonical":"Scoreboard","prior":0.2,"aliases":["Jumbotron"]},{"canonical":"Arcade machine","prior":0.2,"aliases":["Arcade","Arcade game"]},{"canonical":"Fitness band","prior":0.2,"aliases":[]},{"canonical":"VR headset","prior":0.2,"aliases":["Oculus","Virtual reality headset"]},{"canonical":"Smart speaker","prior":0.2,"aliases":["Echo Show"]},{"canonical":"Ticket machine","prior":0.1,"aliases":["Kiosk","Self-checkout"]},{"canonical":"Thermostat","prior":0.1,"aliases":[]},{"canonical":"Oscilloscope","prior":0.1,"aliases":[]},{"canonical":"Ultrasound machine","prior":0.1,"aliases":[]},{"canonical":"Video doorbell","prior":0.1,"aliases":[]},{"canonical":"Radar","prior":0.1,"aliases":[]}]', NULL, 'Think of your pocket, your living room, a bank lobby, the front seat of a taxi and the netting that keeps mosquitoes out.');
