INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-trip-hill', 'Name a hill station in India.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Shimla was the summer capital of British India from 1864. Every year the whole government moved up into the hills to escape the heat of the plains.', 'https://en.wikipedia.org/wiki/Hill_stations_in_India', 'Wikipedia: Hill stations in India', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Shimla","prior":16,"aliases":["Simla"]},{"canonical":"Manali","prior":14,"aliases":[]},{"canonical":"Ooty","prior":10,"aliases":["Udhagamandalam","Ootacamund","Udagamandalam"]},{"canonical":"Darjeeling","prior":8,"aliases":[]},{"canonical":"Mussoorie","prior":8,"aliases":["Mussorie","Masuri"]},{"canonical":"Nainital","prior":6,"aliases":["Naini Tal"]},{"canonical":"Munnar","prior":6,"aliases":[]},{"canonical":"Kodaikanal","prior":4,"aliases":["Kodai"]},{"canonical":"Gangtok","prior":3,"aliases":[]},{"canonical":"Mount Abu","prior":3,"aliases":[]},{"canonical":"Lonavala","prior":3,"aliases":["Lonavla","Khandala"]},{"canonical":"Mahabaleshwar","prior":2,"aliases":[]},{"canonical":"Shillong","prior":2,"aliases":[]},{"canonical":"Coorg","prior":2,"aliases":["Kodagu","Madikeri","Mercara"]},{"canonical":"Dalhousie","prior":2,"aliases":[]},{"canonical":"Gulmarg","prior":2,"aliases":[]},{"canonical":"Kasauli","prior":1,"aliases":[]},{"canonical":"Dharamshala","prior":1,"aliases":["Dharamsala","McLeod Ganj","Mcleodganj"]},{"canonical":"Auli","prior":1,"aliases":[]},{"canonical":"Pahalgam","prior":1,"aliases":[]},{"canonical":"Matheran","prior":1,"aliases":[]},{"canonical":"Panchgani","prior":1,"aliases":[]},{"canonical":"Lansdowne","prior":1,"aliases":[]},{"canonical":"Kasol","prior":1,"aliases":[]},{"canonical":"Almora","prior":1,"aliases":[]},{"canonical":"Ranikhet","prior":1,"aliases":[]},{"canonical":"Coonoor","prior":0.5,"aliases":[]},{"canonical":"Yercaud","prior":0.5,"aliases":[]},{"canonical":"Wayanad","prior":0.5,"aliases":[]},{"canonical":"Chikmagalur","prior":0.5,"aliases":["Chikkamagaluru"]},{"canonical":"Kalimpong","prior":0.5,"aliases":[]},{"canonical":"Mirik","prior":0.3,"aliases":[]},{"canonical":"Tawang","prior":0.5,"aliases":[]},{"canonical":"Kufri","prior":0.5,"aliases":[]},{"canonical":"Chail","prior":0.3,"aliases":[]},{"canonical":"Dharamkot","prior":0.2,"aliases":[]},{"canonical":"Mukteshwar","prior":0.3,"aliases":[]},{"canonical":"Pachmarhi","prior":0.5,"aliases":[]},{"canonical":"Horsley Hills","prior":0.2,"aliases":[]},{"canonical":"Araku Valley","prior":0.3,"aliases":["Araku"]},{"canonical":"Saputara","prior":0.3,"aliases":[]},{"canonical":"Lavasa","prior":0.1,"aliases":[]},{"canonical":"Ponmudi","prior":0.2,"aliases":[]},{"canonical":"Vagamon","prior":0.2,"aliases":[]},{"canonical":"Kotagiri","prior":0.2,"aliases":[]},{"canonical":"Haflong","prior":0.1,"aliases":[]},{"canonical":"Cherrapunji","prior":0.3,"aliases":["Sohra"]},{"canonical":"Sonamarg","prior":0.3,"aliases":[]},{"canonical":"Patnitop","prior":0.2,"aliases":[]},{"canonical":"Kausani","prior":0.2,"aliases":[]},{"canonical":"Chakrata","prior":0.1,"aliases":[]},{"canonical":"Dhanaulti","prior":0.2,"aliases":[]},{"canonical":"Kalpa","prior":0.1,"aliases":[]},{"canonical":"Bir Billing","prior":0.2,"aliases":["Bir"]},{"canonical":"Pelling","prior":0.2,"aliases":[]},{"canonical":"Lachung","prior":0.1,"aliases":[]},{"canonical":"Amboli","prior":0.1,"aliases":[]},{"canonical":"Nandi Hills","prior":0.2,"aliases":[]},{"canonical":"Kemmangundi","prior":0.1,"aliases":[]},{"canonical":"Bomdila","prior":0.1,"aliases":[]},{"canonical":"Aizawl","prior":0.1,"aliases":[]}]', NULL, 'Think of the Nilgiris, the Western Ghats near Mumbai, tea country in Bengal and the old summer capital.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-trip-boat', 'Name a type of boat or ship.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Kerala''s snake boats, the chundan vallam, can be more than 30 metres long and carry around a hundred rowers in the Nehru Trophy race on Punnamada Lake.', 'https://en.wikipedia.org/wiki/List_of_boat_types', 'Wikipedia: List of boat types', '2026-11-21', 'CC BY-SA 4.0', 'travel', 1, 0, '[{"canonical":"Canoe","prior":10,"aliases":[]},{"canonical":"Yacht","prior":10,"aliases":[]},{"canonical":"Kayak","prior":8,"aliases":[]},{"canonical":"Submarine","prior":8,"aliases":[]},{"canonical":"Sailboat","prior":6,"aliases":["Sailing boat","Sailing ship","Sail boat"]},{"canonical":"Ferry","prior":6,"aliases":[]},{"canonical":"Speedboat","prior":6,"aliases":["Speed boat","Motorboat","Motor boat","Jet boat"]},{"canonical":"Cruise ship","prior":6,"aliases":["Cruise","Cruise liner","Ocean liner","Liner"]},{"canonical":"Raft","prior":4,"aliases":["Rubber raft","Life raft"]},{"canonical":"Houseboat","prior":4,"aliases":["House boat","Kettuvallam"]},{"canonical":"Gondola","prior":4,"aliases":[]},{"canonical":"Shikara","prior":3,"aliases":[]},{"canonical":"Rowing boat","prior":3,"aliases":["Rowboat","Row boat","Dinghy"]},{"canonical":"Catamaran","prior":2,"aliases":[]},{"canonical":"Steamboat","prior":2,"aliases":["Steamer","Steamship","Paddle steamer"]},{"canonical":"Battleship","prior":2,"aliases":[]},{"canonical":"Aircraft carrier","prior":2,"aliases":[]},{"canonical":"Pirate ship","prior":1,"aliases":["Galleon"]},{"canonical":"Fishing boat","prior":1,"aliases":["Trawler"]},{"canonical":"Tugboat","prior":1,"aliases":["Tug"]},{"canonical":"Cargo ship","prior":1,"aliases":["Container ship","Freighter"]},{"canonical":"Oil tanker","prior":1,"aliases":["Tanker"]},{"canonical":"Snake boat","prior":1,"aliases":["Chundan vallam","Vallam kali"]},{"canonical":"Lifeboat","prior":1,"aliases":["Life boat"]},{"canonical":"Pedal boat","prior":1,"aliases":["Paddle boat","Swan boat"]},{"canonical":"Destroyer","prior":0.5,"aliases":[]},{"canonical":"Frigate","prior":0.5,"aliases":[]},{"canonical":"Warship","prior":0.5,"aliases":[]},{"canonical":"Coracle","prior":0.5,"aliases":["Parisal","Teppa"]},{"canonical":"Dhow","prior":0.5,"aliases":[]},{"canonical":"Junk","prior":0.5,"aliases":["Chinese junk"]},{"canonical":"Sampan","prior":0.5,"aliases":[]},{"canonical":"Barge","prior":0.5,"aliases":[]},{"canonical":"Hovercraft","prior":0.5,"aliases":[]},{"canonical":"Jet ski","prior":0.5,"aliases":["Jetski","Personal watercraft"]},{"canonical":"Punt","prior":0.3,"aliases":[]},{"canonical":"Longboat","prior":0.3,"aliases":["Viking longship","Longship"]},{"canonical":"Trimaran","prior":0.3,"aliases":[]},{"canonical":"Pontoon boat","prior":0.3,"aliases":[]},{"canonical":"Icebreaker","prior":0.3,"aliases":[]},{"canonical":"Hydrofoil","prior":0.3,"aliases":[]},{"canonical":"Schooner","prior":0.3,"aliases":[]},{"canonical":"Clipper","prior":0.3,"aliases":[]},{"canonical":"Trireme","prior":0.2,"aliases":[]},{"canonical":"Narrowboat","prior":0.2,"aliases":["Canal boat"]},{"canonical":"Dragon boat","prior":0.2,"aliases":[]},{"canonical":"Ketch","prior":0.1,"aliases":[]},{"canonical":"Sloop","prior":0.1,"aliases":[]},{"canonical":"Brigantine","prior":0.1,"aliases":[]},{"canonical":"Caravel","prior":0.1,"aliases":[]},{"canonical":"Felucca","prior":0.1,"aliases":[]},{"canonical":"Outrigger","prior":0.1,"aliases":[]},{"canonical":"Umiak","prior":0.1,"aliases":[]},{"canonical":"Bajra","prior":0.1,"aliases":["Budgerow"]}]', NULL, 'Think of Dal Lake, the Kerala backwaters, Venice, the navy and the giants that carry containers across oceans.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-trip-rails', 'Name something that runs on rails.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'India''s first passenger train ran on 16 April 1853 between Bori Bunder in Bombay and Thane, about 34 kilometres, pulled by three engines named Sahib, Sultan and Sindh.', 'https://en.wikipedia.org/wiki/Rail_transport_in_India', 'Wikipedia: Rail transport in India', '2026-11-21', 'CC BY-SA 4.0', 'travel', 1, 0, '[{"canonical":"Train","prior":30,"aliases":["Trains","Railway","Railways","Rail"]},{"canonical":"Metro","prior":14,"aliases":["Metro train","Subway","Underground","Tube"]},{"canonical":"Tram","prior":8,"aliases":["Tramcar","Streetcar","Trolley"]},{"canonical":"Roller coaster","prior":8,"aliases":["Rollercoaster","Coaster"]},{"canonical":"Toy train","prior":4,"aliases":["Mountain railway","Heritage railway"]},{"canonical":"Monorail","prior":3,"aliases":[]},{"canonical":"Bullet train","prior":3,"aliases":["High-speed train","Shinkansen","High speed rail"]},{"canonical":"Local train","prior":2,"aliases":["Mumbai local","Suburban train","Local"]},{"canonical":"Sliding door","prior":2,"aliases":["Sliding doors","Sliding wardrobe"]},{"canonical":"Curtains","prior":2,"aliases":["Curtain","Curtain rail"]},{"canonical":"Drawer","prior":2,"aliases":["Drawers"]},{"canonical":"Funicular","prior":1,"aliases":["Cliff railway","Incline railway"]},{"canonical":"Mine cart","prior":1,"aliases":["Minecart","Mine train"]},{"canonical":"Gantry crane","prior":1,"aliases":["Crane","Overhead crane"]},{"canonical":"Camera dolly","prior":1,"aliases":["Dolly"]},{"canonical":"Locomotive","prior":1,"aliases":["Engine","Steam engine","Steam locomotive"]},{"canonical":"Goods train","prior":1,"aliases":["Freight train","Cargo train"]},{"canonical":"Maglev","prior":0.5,"aliases":[]},{"canonical":"Vande Bharat","prior":0.5,"aliases":["Vande Bharat Express"]},{"canonical":"Rajdhani Express","prior":0.5,"aliases":["Rajdhani"]},{"canonical":"Shatabdi Express","prior":0.5,"aliases":["Shatabdi"]},{"canonical":"Palace on Wheels","prior":0.5,"aliases":[]},{"canonical":"Ghost train","prior":0.5,"aliases":[]},{"canonical":"Cable car","prior":0.5,"aliases":[]},{"canonical":"Typewriter carriage","prior":0.3,"aliases":["Typewriter"]},{"canonical":"Shower curtain","prior":0.3,"aliases":[]},{"canonical":"Garage door","prior":0.3,"aliases":[]},{"canonical":"Bogie","prior":0.3,"aliases":["Coach","Railway carriage","Carriage"]},{"canonical":"Handcar","prior":0.2,"aliases":["Draisine","Pump trolley"]},{"canonical":"Rail bus","prior":0.2,"aliases":["Railbus"]},{"canonical":"Sliding window","prior":0.3,"aliases":[]},{"canonical":"Model railway","prior":0.3,"aliases":["Model train","Train set"]}]', NULL, 'Think of the daily commute, the funfair, the hills of Darjeeling and the furniture in your own bedroom.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-trip-spanish', 'Name a country where Spanish is an official language.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Mexico has more Spanish speakers than any other country, Spain included. Equatorial Guinea, a small country in Central Africa, is the only one in Africa with Spanish as an official language.', 'https://en.wikipedia.org/wiki/List_of_countries_where_Spanish_is_an_official_language', 'Wikipedia: List of countries where Spanish is an official language', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Spain","prior":26,"aliases":["España","Espana"]},{"canonical":"Mexico","prior":22,"aliases":["México"]},{"canonical":"Argentina","prior":12,"aliases":[]},{"canonical":"Colombia","prior":6,"aliases":[]},{"canonical":"Chile","prior":4,"aliases":[]},{"canonical":"Peru","prior":4,"aliases":["Perú"]},{"canonical":"Cuba","prior":4,"aliases":[]},{"canonical":"Venezuela","prior":3,"aliases":[]},{"canonical":"Bolivia","prior":2,"aliases":[]},{"canonical":"Ecuador","prior":2,"aliases":[]},{"canonical":"Uruguay","prior":2,"aliases":[]},{"canonical":"Paraguay","prior":2,"aliases":[]},{"canonical":"Costa Rica","prior":1,"aliases":[]},{"canonical":"Panama","prior":1,"aliases":["Panamá"]},{"canonical":"Guatemala","prior":1,"aliases":[]},{"canonical":"Dominican Republic","prior":1,"aliases":[]},{"canonical":"Honduras","prior":1,"aliases":[]},{"canonical":"El Salvador","prior":1,"aliases":["Salvador"]},{"canonical":"Nicaragua","prior":1,"aliases":[]},{"canonical":"Equatorial Guinea","prior":0.5,"aliases":[]}]', NULL, 'Think of Central America, the Caribbean, the Andes and one small country in Central Africa.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-trip-capitals-in', 'Name the capital of an Indian state.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Chandigarh, the shared capital of Punjab and Haryana, was planned in the 1950s by the Swiss-French architect Le Corbusier, who laid it out in numbered sectors.', 'https://en.wikipedia.org/wiki/List_of_state_and_union_territory_capitals_in_India', 'Wikipedia: List of state and union territory capitals in India', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Mumbai","prior":14,"aliases":["Bombay"]},{"canonical":"Kolkata","prior":10,"aliases":["Calcutta"]},{"canonical":"Chennai","prior":10,"aliases":["Madras"]},{"canonical":"Bengaluru","prior":8,"aliases":["Bangalore"]},{"canonical":"Hyderabad","prior":8,"aliases":[]},{"canonical":"Lucknow","prior":6,"aliases":[]},{"canonical":"Jaipur","prior":6,"aliases":[]},{"canonical":"Chandigarh","prior":6,"aliases":[]},{"canonical":"Patna","prior":4,"aliases":[]},{"canonical":"Bhopal","prior":4,"aliases":[]},{"canonical":"Thiruvananthapuram","prior":3,"aliases":["Trivandrum"]},{"canonical":"Gandhinagar","prior":3,"aliases":[]},{"canonical":"Bhubaneswar","prior":3,"aliases":["Bhubaneshwar"]},{"canonical":"Dehradun","prior":3,"aliases":["Dehra Dun"]},{"canonical":"Shimla","prior":2,"aliases":["Simla"]},{"canonical":"Ranchi","prior":2,"aliases":[]},{"canonical":"Raipur","prior":2,"aliases":["Nava Raipur","Naya Raipur"]},{"canonical":"Panaji","prior":2,"aliases":["Panjim"]},{"canonical":"Dispur","prior":2,"aliases":["Guwahati"]},{"canonical":"Gangtok","prior":1,"aliases":[]},{"canonical":"Shillong","prior":1,"aliases":[]},{"canonical":"Amaravati","prior":1,"aliases":["Amravati"]},{"canonical":"Imphal","prior":1,"aliases":[]},{"canonical":"Agartala","prior":1,"aliases":[]},{"canonical":"Aizawl","prior":1,"aliases":[]},{"canonical":"Kohima","prior":1,"aliases":[]},{"canonical":"Itanagar","prior":1,"aliases":[]},{"canonical":"Nagpur","prior":0.3,"aliases":[]},{"canonical":"Dharamshala","prior":0.3,"aliases":["Dharamsala"]},{"canonical":"Gairsain","prior":0.2,"aliases":["Bhararisain"]}]', NULL, 'Think of the seven sisters of the North-East, the planned city two states share, and the new capital of Andhra Pradesh.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-trip-bridge', 'Name a famous bridge anywhere in the world.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Kolkata''s Howrah Bridge, opened in 1943, was built without a single nut or bolt: its steel is held together by rivets. San Francisco''s Golden Gate Bridge is painted a colour called International Orange.', 'https://en.wikipedia.org/wiki/Howrah_Bridge', 'Wikipedia: Howrah Bridge', '2026-11-21', 'CC BY-SA 4.0', 'travel', 2, 0, '[{"canonical":"Golden Gate Bridge","prior":20,"aliases":["Golden Gate"]},{"canonical":"Howrah Bridge","prior":18,"aliases":["Howrah","Rabindra Setu"]},{"canonical":"Tower Bridge","prior":12,"aliases":[]},{"canonical":"London Bridge","prior":8,"aliases":[]},{"canonical":"Bandra-Worli Sea Link","prior":6,"aliases":["Bandra Worli Sea Link","Sea Link","Rajiv Gandhi Sea Link"]},{"canonical":"Brooklyn Bridge","prior":6,"aliases":["Brooklyn"]},{"canonical":"Sydney Harbour Bridge","prior":4,"aliases":["Harbour Bridge","Sydney Harbor Bridge"]},{"canonical":"Rialto Bridge","prior":2,"aliases":["Rialto","Ponte di Rialto"]},{"canonical":"Bridge of Sighs","prior":2,"aliases":["Ponte dei Sospiri"]},{"canonical":"Chenab Bridge","prior":2,"aliases":["Chenab Rail Bridge"]},{"canonical":"Atal Setu","prior":2,"aliases":["Mumbai Trans Harbour Link","MTHL","Trans Harbour Link"]},{"canonical":"Ponte Vecchio","prior":1,"aliases":[]},{"canonical":"Charles Bridge","prior":1,"aliases":["Karlův most"]},{"canonical":"Vidyasagar Setu","prior":1,"aliases":["Second Hooghly Bridge"]},{"canonical":"Pamban Bridge","prior":1,"aliases":["Pamban"]},{"canonical":"Ram Setu","prior":1,"aliases":["Adam''s Bridge","Rama Setu","Ram Sethu"]},{"canonical":"Laxman Jhula","prior":1,"aliases":["Lakshman Jhula","Ram Jhula"]},{"canonical":"Living root bridges","prior":1,"a