:0.3,"aliases":["Bhupen Hazarika Setu","Dhola Sadiya"]},{"canonical":"Anji Khad Bridge","prior":0.1,"aliases":[]},{"canonical":"Kintai Bridge","prior":0.1,"aliases":[]},{"canonical":"Tsing Ma Bridge","prior":0.1,"aliases":[]},{"canonical":"Széchenyi Bridge","prior":0.1,"aliases":[]},{"canonical":"Coronado Bridge","prior":0.1,"aliases":[]},{"canonical":"Gateshead Millennium Bridge","prior":0.1,"aliases":[]},{"canonical":"Clifton Suspension Bridge","prior":0.1,"aliases":[]},{"canonical":"Pont de Normandie","prior":0.1,"aliases":[]},{"canonical":"Erasmus Bridge","prior":0.1,"aliases":["Erasmusbrug"]},{"canonical":"Rainbow Bridge","prior":0.2,"aliases":[]}]', NULL, 'Think of Kolkata, Mumbai''s coastline, San Francisco, the Thames and the canals of Venice.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-music-hit', 'Name a musical instrument you play by hitting it.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'A tabla is a pair of drums: the small dayan, played with the right hand, and the bigger bayan. The black spot on each head, the syahi, is a paste of flour and iron filings that gives the drum its ringing tone.', 'https://en.wikipedia.org/wiki/Tabla', 'Wikipedia: Tabla', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Drum","prior":24,"aliases":["Drums","Drum kit","Drum set","Snare drum","Bass drum"]},{"canonical":"Tabla","prior":16,"aliases":[]},{"canonical":"Dhol","prior":10,"aliases":["Dhol tasha"]},{"canonical":"Xylophone","prior":6,"aliases":[]},{"canonical":"Dholak","prior":4,"aliases":["Dholki"]},{"canonical":"Cymbals","prior":4,"aliases":["Cymbal","Manjira","Manjeera","Jhanj","Taal"]},{"canonical":"Triangle","prior":3,"aliases":[]},{"canonical":"Piano","prior":3,"aliases":[]},{"canonical":"Tambourine","prior":3,"aliases":["Daf","Duff","Dafli"]},{"canonical":"Mridangam","prior":3,"aliases":["Mridanga"]},{"canonical":"Bongo","prior":2,"aliases":["Bongos"]},{"canonical":"Djembe","prior":2,"aliases":[]},{"canonical":"Gong","prior":2,"aliases":[]},{"canonical":"Conga","prior":1,"aliases":["Congas"]},{"canonical":"Glockenspiel","prior":1,"aliases":[]},{"canonical":"Marimba","prior":1,"aliases":[]},{"canonical":"Timpani","prior":1,"aliases":["Kettle drum","Kettledrum"]},{"canonical":"Ghatam","prior":1,"aliases":[]},{"canonical":"Kanjira","prior":1,"aliases":["Khanjira"]},{"canonical":"Chenda","prior":1,"aliases":[]},{"canonical":"Damaru","prior":1,"aliases":["Damru"]},{"canonical":"Nagara","prior":1,"aliases":["Nagada","Nagaada","Naqqara"]},{"canonical":"Pakhawaj","prior":1,"aliases":[]},{"canonical":"Bells","prior":1,"aliases":["Bell","Temple bell","Ghanta","Tubular bells"]},{"canonical":"Santoor","prior":1,"aliases":["Santur"]},{"canonical":"Cajón","prior":1,"aliases":["Cajon"]},{"canonical":"Steelpan","prior":0.5,"aliases":["Steel drum","Steel pan"]},{"canonical":"Thavil","prior":0.5,"aliases":[]},{"canonical":"Dhak","prior":0.5,"aliases":[]},{"canonical":"Khol","prior":0.5,"aliases":[]},{"canonical":"Duggi","prior":0.5,"aliases":[]},{"canonical":"Udukkai","prior":0.3,"aliases":["Udukku"]},{"canonical":"Ektara","prior":0.3,"aliases":[]},{"canonical":"Edakka","prior":0.3,"aliases":[]},{"canonical":"Tasha","prior":0.5,"aliases":["Tasa"]},{"canonical":"Tabor","prior":0.2,"aliases":[]},{"canonical":"Vibraphone","prior":0.5,"aliases":[]},{"canonical":"Cowbell","prior":0.5,"aliases":[]},{"canonical":"Woodblock","prior":0.3,"aliases":["Wood block"]},{"canonical":"Castanets","prior":0.5,"aliases":[]},{"canonical":"Hammered dulcimer","prior":0.3,"aliases":["Dulcimer"]},{"canonical":"Celesta","prior":0.2,"aliases":[]},{"canonical":"Taiko","prior":0.5,"aliases":[]},{"canonical":"Tom-tom","prior":0.3,"aliases":["Tom tom"]},{"canonical":"Hang drum","prior":0.2,"aliases":["Handpan"]},{"canonical":"Tabla tarang","prior":0.2,"aliases":[]},{"canonical":"Jal tarang","prior":0.3,"aliases":["Jaltarang"]},{"canonical":"Gamelan","prior":0.3,"aliases":[]},{"canonical":"Kalimba","prior":0.2,"aliases":["Mbira","Thumb piano"]},{"canonical":"Bodhrán","prior":0.2,"aliases":["Bodhran"]},{"canonical":"Chimes","prior":0.3,"aliases":["Wind chimes"]},{"canonical":"Anvil","prior":0.1,"aliases":[]},{"canonical":"Spoons","prior":0.1,"aliases":[]},{"canonical":"Washboard","prior":0.1,"aliases":[]},{"canonical":"Pung","prior":0.1,"aliases":["Pung cholom"]},{"canonical":"Parai","prior":0.2,"aliases":["Thappu"]},{"canonical":"Talking drum","prior":0.1,"aliases":[]},{"canonical":"Tabl","prior":0.1,"aliases":[]},{"canonical":"Darbuka","prior":0.2,"aliases":["Doumbek","Goblet drum"]}]', NULL, 'Think of a temple procession, a Carnatic concert, a school orchestra and a Ganpati visarjan.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-music-genre', 'Name a genre of music.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Hip hop began at block parties in the Bronx in New York in the 1970s. Goa gave its name to a whole style of electronic music, Goa trance, which grew out of beach parties there around 1990.', 'https://en.wikipedia.org/wiki/List_of_music_genres_and_styles', 'Wikipedia: List of music genres and styles', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Pop","prior":18,"aliases":["Pop music"]},{"canonical":"Rock","prior":16,"aliases":["Rock music","Rock and roll","Rock ''n'' roll"]},{"canonical":"Hip hop","prior":12,"aliases":["Hip-hop","Rap","Hiphop"]},{"canonical":"Jazz","prior":10,"aliases":[]},{"canonical":"Classical","prior":8,"aliases":["Classical music","Western classical"]},{"canonical":"Country","prior":4,"aliases":["Country music"]},{"canonical":"Electronic","prior":4,"aliases":["EDM","Electronic dance music","Electronica"]},{"canonical":"Metal","prior":4,"aliases":["Heavy metal","Death metal","Black metal","Thrash metal"]},{"canonical":"Blues","prior":3,"aliases":["Rhythm and blues"]},{"canonical":"R&B","prior":3,"aliases":["RnB","R and B"]},{"canonical":"Reggae","prior":3,"aliases":[]},{"canonical":"Bollywood","prior":3,"aliases":["Filmi","Film music","Bollywood music"]},{"canonical":"Sufi","prior":3,"aliases":["Sufi music"]},{"canonical":"Qawwali","prior":3,"aliases":[]},{"canonical":"Ghazal","prior":3,"aliases":[]},{"canonical":"Hindustani classical","prior":2,"aliases":["Hindustani"]},{"canonical":"Carnatic","prior":2,"aliases":["Carnatic music"]},{"canonical":"K-pop","prior":2,"aliases":["Kpop","Korean pop"]},{"canonical":"Folk","prior":2,"aliases":["Folk music"]},{"canonical":"Indie","prior":2,"aliases":["Indie pop","Indie rock"]},{"canonica