nical":"Rabindra Sangeet","prior":0.3,"aliases":["Rabindrasangeet"]},{"canonical":"Abhang","prior":0.2,"aliases":[]},{"canonical":"Dhrupad","prior":0.2,"aliases":[]},{"canonical":"Khayal","prior":0.2,"aliases":["Khyal"]},{"canonical":"Shoegaze","prior":0.1,"aliases":[]},{"canonical":"Zydeco","prior":0.1,"aliases":[]},{"canonical":"Calypso","prior":0.2,"aliases":[]},{"canonical":"Soca","prior":0.1,"aliases":[]},{"canonical":"Polka","prior":0.2,"aliases":[]},{"canonical":"Fado","prior":0.1,"aliases":[]},{"canonical":"J-pop","prior":0.2,"aliases":["Jpop"]},{"canonical":"Cumbia","prior":0.1,"aliases":[]},{"canonical":"Tango","prior":0.2,"aliases":[]},{"canonical":"Mariachi","prior":0.2,"aliases":[]},{"canonical":"Acid jazz","prior":0.1,"aliases":[]},{"canonical":"Bebop","prior":0.1,"aliases":[]},{"canonical":"Motown","prior":0.2,"aliases":[]},{"canonical":"Gamelan","prior":0.1,"aliases":[]},{"canonical":"Chillwave","prior":0.05,"aliases":[]}]', NULL, 'Think of what''s on the radio, what your grandparents loved, what plays at a dargah and what plays at 2 AM in a nightclub.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-music-singer', 'Name a playback singer from Hindi or other Indian films.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Asha Bhosle was named by Guinness World Records in 2011 as the most recorded artist in music history, with songs in more than a dozen languages.', 'https://en.wikipedia.org/wiki/Playback_singer', 'Wikipedia: Playback singer', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Lata Mangeshkar","prior":18,"aliases":["Lata","Lata ji","Lataji"]},{"canonical":"Arijit Singh","prior":16,"aliases":["Arijit"]},{"canonical":"Kishore Kumar","prior":14,"aliases":["Kishore","Kishore da"]},{"canonical":"Mohammed Rafi","prior":10,"aliases":["Mohammad Rafi","Rafi","Md Rafi"]},{"canonical":"Asha Bhosle","prior":8,"aliases":["Asha","Asha ji"]},{"canonical":"Sonu Nigam","prior":8,"aliases":[]},{"canonical":"Shreya Ghoshal","prior":8,"aliases":["Shreya"]},{"canonical":"Udit Narayan","prior":4,"aliases":[]},{"canonical":"Kumar Sanu","prior":4,"aliases":[]},{"canonical":"Alka Yagnik","prior":4,"aliases":["Alka Yagnik ji"]},{"canonical":"Mukesh","prior":3,"aliases":[]},{"canonical":"KK","prior":3,"aliases":["K. K.","Krishnakumar Kunnath"]},{"canonical":"Atif Aslam","prior":3,"aliases":["Atif"]},{"canonical":"Sunidhi Chauhan","prior":3,"aliases":["Sunidhi"]},{"canonical":"Neha Kakkar","prior":3,"aliases":[]},{"canonical":"Shaan","prior":2,"aliases":[]},{"canonical":"SP Balasubrahmanyam","prior":2,"aliases":["S. P. Balasubrahmanyam","SPB","SP Balu","Balu"]},{"canonical":"KJ Yesudas","prior":2,"aliases":["K. J. Yesudas","Yesudas"]},{"canonical":"Kavita Krishnamurthy","prior":2,"aliases":["Kavita Krishnamurti"]},{"canonical":"Shankar Mahadevan","prior":2,"aliases":[]},{"canonical":"AR Rahman","prior":2,"aliases":["A. R. Rahman","Rahman"]},{"canoni