INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-music-bts', 'Name a member of BTS.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'BTS stands for Bangtan Sonyeondan, roughly ''Bulletproof Boy Scouts''. In 2020 ''Dynamite'' became their first number one on the US Billboard Hot 100.', 'https://en.wikipedia.org/wiki/BTS', 'Wikipedia: BTS', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Jungkook","prior":22,"aliases":["Jeon Jungkook","Jeon Jung-kook","JK","Kookie"]},{"canonical":"V","prior":18,"aliases":["Kim Taehyung","Taehyung","Tae","TaeTae"]},{"canonical":"Jimin","prior":16,"aliases":["Park Jimin","Park Ji-min"]},{"canonical":"Jin","prior":12,"aliases":["Kim Seokjin","Seokjin","Worldwide Handsome"]},{"canonical":"Suga","prior":10,"aliases":["Min Yoongi","Yoongi","Agust D"]},{"canonical":"RM","prior":10,"aliases":["Kim Namjoon","Namjoon","Rap Monster"]},{"canonical":"J-Hope","prior":10,"aliases":["J Hope","Jhope","Jung Hoseok","Hoseok","Hobi"]}]', NULL, 'There are seven: the leader, the eldest, the youngest, a dancer from Gwangju, and the rest of the rap and vocal lines.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-music-composer', 'Name a composer of Western classical music.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Beethoven wrote some of his greatest music, including the Ninth Symphony, after he had gone almost completely deaf. Mozart was composing short pieces by the age of five.', 'https://en.wikipedia.org/wiki/List_of_classical_music_composers_by_era', 'Wikipedia: List of classical music composers by era', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Ludwig van Beethoven","prior":24,"aliases":["Beethoven"]},{"canonical":"Wolfgang Amadeus Mozart","prior":22,"aliases":["Mozart"]},{"canonical":"Johann Sebastian Bach","prior":14,"aliases":["Bach","J. S. Bach","JS Bach"]},{"canonical":"Pyotr Ilyich Tchaikovsky","prior":6,"aliases":["Tchaikovsky","Tchaikovski"]},{"canonical":"Frédéric Chopin","prior":6,"aliases":["Chopin","Frederic Chopin"]},{"canonical":"Antonio Vivaldi","prior":5,"aliases":["Vivaldi"]},{"canonical":"Franz Schubert","prior":2,"aliases":["Schubert"]},{"canonical":"Johannes Brahms","prior":2,"aliases":["Brahms"]},{"canonical":"George Frideric Handel","prior":2,"aliases":["Handel","Händel"]},{"canonical":"Joseph Haydn","prior":2,"aliases":["Haydn","Franz Joseph Haydn"]},{"canonical":"Claude Debussy","prior":2,"aliases":["Debussy"]},{"canonical":"Richard Wagner","prior":2,"aliases":["Wagner"]},{"canonical":"Franz Liszt","prior":1,"aliases":["Liszt"]},{"canonical":"Giuseppe Verdi","prior":1,"aliases":["Verdi"]},{"canonical":"Johann Strauss II","prior":1,"aliases":["Johann Strauss","Strauss"]},{"canonical":"Antonín Dvořák","prior":1,"aliases":["Dvorak","Dvořák","Antonin Dvorak"]},{"canonical":"Felix Mendelssohn","prior":1,"aliases":["Mendelssohn"]},{"canonical":"Robert Schumann","prior":1,"aliases":["Schumann"]},{"canonical":"Sergei Rachmaninoff","prior":1,"aliases":["Rachmaninoff","Rachmaninov"]},{"canonical":"Gustav Mahler","prior":1,"aliases":["Mahler"]},{"canonical":"Igor Stravinsky","prior":1,"aliases":["Stravinsky"]},{"canonical":"Giacomo Puccini","prior":1,"aliases":["Puccini"]},{"canonical":"Maurice Ravel","prior":1,"aliases":["Ravel"]},{"canonical":"Edvard Grieg","prior":0.5,"aliases":["Grieg"]},{"canonical":"Erik Satie","prior":0.5,"aliases":["Satie"]},{"canonical":"Camille Saint-Saëns","prior":0.5,"aliases":["Saint-Saens","Saint-Saëns"]},{"canonical":"Gioachino Rossini","prior":0.5,"aliases":["Rossini"]},{"canonical":"Georges Bizet","prior":0.5,"aliases":["Bizet"]},{"canonical":"Nikolai Rimsky-Korsakov","prior":0.5,"aliases":["Rimsky-Korsakov"]},{"canonical":"Sergei Prokofiev","prior":0.5,"aliases":["Prokofiev"]},{"canonical":"Dmitri Shostakovich","prior":0.5,"aliases":["Shostakovich"]},{"canonical":"Gustav Holst","prior":0.5,"aliases":["Holst"]},{"canonical":"Edward Elgar","prior":0.5,"aliases":["Elgar"]},{"canonical":"Johann Pachelbel","prior":0.5,"aliases":["Pachelbel"]},{"canonical":"Henry Purcell","prior":0.3,"aliases":["Purcell"]},{"canonical":"Claudio Monteverdi","prior":0.3,"aliases":["Monteverdi"]},{"canonical":"Hector Berlioz","prior":0.3,"aliases":["Berlioz"]},{"canonical":"Jean Sibelius","prior":0.3,"aliases":["Sibelius"]},{"canonical":"Aaron Copland","prior":0.3,"aliases":["Copland"]},{"canonical":"George Gershwin","prior":0.3,"aliases":["Gershwin"]},{"canonical":"Philip Glass","prior":0.3,"aliases":[]},{"canonical":"Arvo Pärt","prior":0.2,"aliases":["Arvo Part"]},{"canonical":"Modest Mussorgsky","prior":0.3,"aliases":["Mussorgsky"]},{"canonical":"Benjamin Britten","prior":0.2,"aliases":["Britten"]},{"canonical":"Ralph Vaughan Williams","prior":0.2,"aliases":["Vaughan Williams"]},{"canonical":"Samuel Barber","prior":0.2,"aliases":["Barber"]},{"canonical":"Gabriel Fauré","prior":0.2,"aliases":["Faure","Fauré"]},{"canonical":"Anton Bruckner","prior":0.2,"aliases":["