INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-music-dance', 'Name a dance style from outside India.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Tango was born in the working-class neighbourhoods of Buenos Aires and Montevideo in the late 1800s. Ballet steps have French names, like plié and pirouette, because the first ballet academy opened in Paris in 1661.', 'https://en.wikipedia.org/wiki/Dance', 'Wikipedia: Dance', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Salsa","prior":16,"aliases":[]},{"canonical":"Ballet","prior":16,"aliases":[]},{"canonical":"Hip hop","prior":10,"aliases":["Hip-hop","Hiphop","Hip hop dance"]},{"canonical":"Tango","prior":8,"aliases":["Argentine tango"]},{"canonical":"Breakdance","prior":6,"aliases":["Breaking","Break dance","Breakdancing","B-boying"]},{"canonical":"Waltz","prior":6,"aliases":["Viennese waltz"]},{"canonical":"Flamenco","prior":4,"aliases":[]},{"canonical":"Zumba","prior":4,"aliases":[]},{"canonical":"Samba","prior":4,"aliases":[]},{"canonical":"Hula","prior":3,"aliases":["Hula dance"]},{"canonical":"Belly dance","prior":3,"aliases":["Belly dancing","Raqs sharqi"]},{"canonical":"Jazz","prior":3,"aliases":["Jazz dance"]},{"canonical":"Contemporary","prior":3,"aliases":["Contemporary dance","Modern dance","Modern"]},{"canonical":"Tap","prior":2,"aliases":["Tap dance","Tap dancing"]},{"canonical":"Cha-cha-cha","prior":2,"aliases":["Cha cha","Cha-cha","Cha cha cha"]},{"canonical":"Rumba","prior":2,"aliases":[]},{"canonical":"Foxtrot","prior":2,"aliases":[]},{"canonical":"Bachata","prior":2,"aliases":[]},{"canonical":"Jive","prior":1,"aliases":[]},{"canonical":"Disco","prior":1,"aliases":[]},{"canonical":"Moonwalk","prior":1,"aliases":[]},{"canonical":"K-pop dance","prior":1,"aliases":["K-pop","Kpop"]},{"canonical":"Popping","prior":1,"al