INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-health-face', 'Name a part of the face.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The groove between your nose and upper lip is the philtrum, and the smooth patch between your eyebrows is the glabella. The face has about 40 muscles, more than enough to make thousands of expressions.', 'https://en.wikipedia.org/wiki/Face', 'Wikipedia: Face', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Nose","prior":22,"aliases":["Naak"]},{"canonical":"Eyes","prior":20,"aliases":["Eye","Aankh"]},{"canonical":"Mouth","prior":14,"aliases":["Muh"]},{"canonical":"Lips","prior":10,"aliases":["Lip","Hoth"]},{"canonical":"Cheeks","prior":8,"aliases":["Cheek","Gaal"]},{"canonical":"Eyebrows","prior":6,"aliases":["Eyebrow","Brow","Brows","Bhauhen"]},{"canonical":"Forehead","prior":6,"aliases":["Brow ridge","Maatha"]},{"canonical":"Chin","prior":6,"aliases":["Thodi"]},{"canonical":"Ears","prior":4,"aliases":["Ear","Kaan"]},{"canonical":"Eyelashes","prior":4,"aliases":["Eyelash","Lashes"]},{"canonical":"Teeth","prior":3,"aliases":["Tooth"]},{"canonical":"Jaw","prior":3,"aliases":["Jawline","Jaws","Mandible"]},{"canonical":"Eyelids","prior":2,"aliases":["Eyelid","Lid","Lids"]},{"canonical":"Nostrils","prior":2,"aliases":["Nostril"]},{"canonical":"Tongue","prior":2,"aliases":[]},{"canonical":"Temples","prior":2,"aliases":["Temple"]},{"canonical":"Dimples","prior":1,"aliases":["Dimple"]},{"canonical":"Philtrum","prior":1,"aliases":["Cupid''s bow"]},{"canonical":"Pupil","prior":1,"aliases":["Pupils"]},{"canonical":"Iris","prior":1,"aliases":["Irises"]},{"canonical":"Cheekbones","prior":1,"aliases":["Cheekbone","Zygomatic bone"]},{"canonical":"Gums","prior":1,"aliases":["Gum"]},{"canonical":"Beard","prior":1,"aliases":["Moustache","Mustache","Stubble"]},{"canonical":"Freckles","prior":0.5,"aliases":["Freckle"]},{"canonical":"Glabella","prior":0.5,"aliases":[]},{"canonical":"Bridge of the nose","prior":0.5,"aliases":["Nose bridge","Nasal bridge"]},{"canonical":"Septum","prior":0.5,"aliases":[]},{"canonical":"Earlobe","prior":0.5,"aliases":["Earlobes","Ear lobe"]},{"canonical":"Sclera","prior":0.3,"aliases":["White of the eye"]},{"canonical":"Cornea","prior":0.3,"aliases":[]},{"canonical":"Tear duct","prior":0.3,"aliases":["Tear ducts","Lacrimal gland"]},{"canonical":"Sinuses","prior":0.3,"aliases":["Sinus"]},{"canonical":"Crow''s feet","prior":0.2,"aliases":[]},{"canonical":"Laugh lines","prior":0.2,"aliases":["Smile lines","Nasolabial folds"]},{"canonical":"Double chin","prior":0.2,"aliases":[]},{"canonical":"Uvula","prior":0.1,"aliases":[]},{"canonical":"Palate","prior":0.1,"aliases":["Roof of the mouth"]},{"canonical":"Nasion","prior":0.1,"aliases":[]},{"canonical":"Columella","prior":0.1,"aliases":[]},{"canonical":"Canthus","prior":0.1,"aliases":[]},{"canonical":"Mentum","prior":0.05,"aliases":[]},{"canonical":"Tragus","prior":0.1,"aliases":[]}]', NULL, 'Think of what you see with, what you smell with, what you raise when surprised, and the little groove with a Greek name.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-health-firstaid', 'Name something you''d find in a first-aid kit.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Band-Aid was invented in 1920 by Earle Dickson, a cotton buyer at Johnson & Johnson, for his wife, who often cut and burned herself in the kitchen.', 'https://en.wikipedia.org/wiki/First_aid_kit', 'Wikipedia: First aid kit', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Band-Aid","prior":16,"aliases":["Bandaid","Plaster","Plasters","Adhesive bandage","Sticking plaster","Hansaplast"]},{"canonical":"Bandage","prior":16,"aliases":["Bandages","Crepe bandage","Roller bandage","Elastic bandage"]},{"canonical":"Antiseptic","prior":10,"aliases":["Dettol","Savlon","Antiseptic liquid","Antiseptic cream","Betadine","Povidone iodine","Iodine"]},{"canonical":"Cotton","prior":8,"aliases":["Cotton wool","Cotton balls","Cotton roll"]},{"canonical":"Scissors","prior":6,"aliases":[]},{"canonical":"Thermometer","prior":6,"aliases":[]},{"canonical":"Gauze","prior":5,"aliases":["Gauze pads","Gauze pad","Gauze roll","Dressing","Sterile dressing"]},{"canonical":"Painkillers","prior":5,"aliases":["Painkiller","Paracetamol","Crocin","Dolo","Ibuprofen","Aspirin","Disprin","Combiflam","Tablets","Pills"]},{"canonical":"Gloves","prior":3,"aliases":["Disposable gloves","Latex gloves"]},{"canonical":"Tweezers","prior":3,"aliases":[]},{"canonical":"Medical tape","prior":2,"aliases":["Surgical tape","Adhesive tape","Micropore","Tape"]},{"canonical":"Antiseptic wipes","prior":2,"aliases":["Wipes","Alcohol wipes","Alcohol swabs"]},{"canonical":"Ointment","prior":2,"aliases":["Burnol","Boroline","Antibiotic ointment","Neosporin","Soframycin","Cream"]},{"canonical":"ORS","prior":2,"aliases":["Oral rehydration salts","Electral","Electrolyte powder"]},{"canonical":"Safety pins","prior":1,"aliases":["Safety pin"]},{"canonical":"Triangular bandage","prior":1,"aliases":["Sling","Arm sling"]},{"canonical":"Cold pack","prior":1,"aliases":["Ice pack","Instant cold pack"]},{"canonical":"Antacid","prior":1,"aliases":["Eno","Digene","Gelusil"]},{"canonical":"Spirit","prior":1,"aliases":["Rubbing alcohol","Surgical spirit"]},{"canonical":"Hydrogen peroxide","prior":0.5,"aliases":[]},{"canonical":"Pain relief spray","prior":0.5,"aliases":["Volini","Moov","Iodex","Pain balm","Relispray","Balm","Zandu Balm","Vicks","Amrutanjan"]},{"canonical":"Antihistamine","prior":0.5,"aliases":["Allergy tablets","Cetirizine","Avil"]},{"canonical":"Burn gel","prior":0.5,"aliases":["Aloe vera gel"]},{"canonical":"Eye wash","prior":0.5,"aliases":["Eye drops","Saline"]},{"canonical":"Splint","prior":0.5,"aliases":[]},{"canonical":"Face mask","prior":0.5,"aliases":["Mask","Masks"]},{"canonical":"Torch","prior":0.3,"aliases":["Flashlight"]},{"canonical":"CPR mask","prior":0.3,"aliases":["Face shield","Resuscitation mask"]},{"canonical":"Emergency blanket","prior":0.3,"aliases":["Space blanket","Foil blanket","Thermal blanket"]},{"canonical":"Hand sanitiser","prior":0.3,"aliases":["Sanitizer","Hand sanitizer","Sanitiser"]},{"canonical":"Glucose","prior":0.3,"aliases":["Glucon-D","Glucose powder"]},{"canonical":"Calamine lotion","prior":0.3,"aliases":["Calamine","Caladryl"]},{"canonical":"Cotton buds","prior":0.3,"aliases":["Q-tips","Ear buds"]},{"canonical":"Instruction booklet","prior":0.2,"aliases":["First-aid manual","Instructions"]},{"canonical":"Tourniquet","prior":0.3,"aliases":[]},{"canonical":"Pulse oximeter","prior":0.3,"aliases":["Oximeter"]},{"canonical":"EpiPen","prior":0.2,"aliases":["Epinephrine","Adrenaline injection"]},{"canonical":"Blister plasters","prior":0.2,"aliases":["Blister pads","Compeed"]},{"canonical":"Whistle","prior":0.1,"aliases":[]},{"canonical":"Butterfly stitches","prior":0.1,"aliases":["Steri-Strips","Wound closure strips"]},{"canonical":"Syringe","prior":0.1,"aliases":[]},{"canonical":"Snake bite kit","prior":0.1,"aliases":[]}]', NULL, 'Think of what stops bleeding, what stings on a cut, what measures a fever and what you take for a headache.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-health-yoga', 'Name a yoga pose.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Hatha Yoga Pradipika, written in the 1400s, describes just 15 asanas. In 2014 the United Nations named 21 June the International Day of Yoga.', 'https://en.wikipedia.org/wiki/List_of_asanas', 'Wikipedia: List of asanas', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Surya Namaskar","prior":14,"aliases":["Sun salutation","Surya namaskara","Suryanamaskar"]},{"canonical":"Padmasana","prior":12,"aliases":["Lotus","Lotus pose","Lotus position"]},{"canonical":"Vrikshasana","prior":10,"aliases":["Tree pose","Tree","Vrksasana"]},{"canonical":"Downward dog","prior":10,"aliases":["Adho Mukha Svanasana","Downward-facing dog","Down dog","Downward facing dog"]},{"canonical":"Shavasana","prior":8,"aliases":["Savasana","Corpse pose","Corpse"]},{"canonical":"Bhujangasana","prior":8,"aliases":["Cobra pose","Cobra"]},{"canonical":"Tadasana","prior":6,"aliases":["Mountain pose","Palm tree pose"]},{"canonical":"Sukhasana","prior":4,"aliases":["Easy pose","Cross-legged"]},{"canonical":"Balasana","prior":4,"aliases":["Child''s pose","Childs pose","Child pose"]},{"canonical":"Virabhadrasana","prior":4,"aliases":["Warrior pose","Warrior","Warrior 1","Warrior 2","Warrior II"]},{"canonical":"Trikonasana","prior":3,"aliases":["Triangle pose","Triangle"]},{"canonical":"Vajrasana","prior":3,"aliases":["Thunderbolt pose","Diamond pose"]},{"canonical":"Sarvangasana","prior":3,"aliases":["Shoulder stand","Shoulderstand"]},{"canonical":"Shirshasana","prior":3,"aliases":["Sirsasana","Headstand","Head stand"]},{"canonical":"Dhanurasana","prior":2,"aliases":["Bow pose"]},{"canonical":"Naukasana","prior":2,"aliases":["Boat pose","Navasana"]},{"canonical":"Chakrasana","prior":2,"aliases":["Wheel pose","Urdhva Dhanurasana"]},{"canonical":"Setu Bandhasana","prior":2,"aliases":["Bridge pose"]},{"canonical":"Ustrasana","prior":2,"aliases":["Camel pose","Camel"]},{"canonical":"Marjaryasana","prior":2,"aliases":["Cat pose","Cat-cow","Cat cow","Bitilasana","Cow pose"]},{"canonical":"Halasana","prior":2,"aliases":["Plough pose","Plow pose"]},{"canonical":"Paschimottanasana","prior":2,"aliases":["Seated forward bend","Forward bend"]},{"canonical":"Matsyasana","prior":1,"aliases":["Fish pose"]},{"canonical":"Plank","prior":1,"aliases":["Plank pose","Phalakasana","Kumbhakasana"]},{"canonical":"Utkatasana","prior":1,"aliases":["Chair pose"]},{"canonical":"Garudasana","prior":1,"aliases":["Eagle pose"]},{"canonical":"Bakasana","prior":1,"aliases":["Crow pose","Crane pose"]},{"canonical":"Kapotasana","prior":1,"aliases":["Pigeon pose","Eka Pada Rajakapotasana","Pigeon"]},{"canonical":"Gomukhasana","prior":1,"aliases":["Cow face pose"]},{"canonical":"Siddhasana","prior":1,"aliases":["Accomplished pose"]},{"canonical":"Natarajasana","prior":1,"aliases":["Dancer''s pose","Lord of the Dance pose","Dancer pose"]},{"canonical":"Shalabhasana","prior":1,"aliases":["Locust pose","Salabhasana"]},{"canonical":"Ardha Matsyendrasana","prior":1,"aliases":["Half spinal twist","Spinal twist","Seated twist"]},{"canonical":"Pawanmuktasana","prior":1,"aliases":["Wind-relieving pose","Pavanamuktasana"]},{"canonical":"Malasana","prior":1,"aliases":["Garland pose","Yogi squat"]},{"canonical":"Baddha Konasana","prior":1,"aliases":["Butterfly pose","Bound angle pose","Titli asana","Butterfly"]},{"canonical":"Anjaneyasana","prior":0.5,"aliases":["Crescent lunge","Low lunge","Lunge"]},{"canonical":"Hanumanasana","prior":0.5,"aliases":["Splits","Monkey pose"]},{"canonical":"Mayurasana","prior":0.5,"aliases":["Peacock pose"]},{"canonical":"Simhasana","prior":0.5,"aliases":["Lion pose"]},{"canonical":"Makarasana","prior":0.5,"aliases":["Crocodile pose"]},{"canonical":"Mandukasana","prior":0.5,"aliases":["Frog pose"]},{"canonical":"Kurmasana","prior":0.5,"aliases":["Tortoise pose"]},{"canonical":"Vasisthasana","prior":0.5,"aliases":["Side plank"]},{"canonical":"Parsvakonasana","prior":0.3,"aliases":["Side angle pose","Extended side angle"]},{"canonical":"Ardha Chandrasana","prior":0.3,"aliases":["Half moon pose"]},{"canonical":"Uttanasana","prior":0.3,"aliases":["Standing forward bend"]},{"canonical":"Viparita Karani","prior":0.3,"aliases":["Legs up the wall"]},{"canonical":"Pincha Mayurasana","prior":0.2,"aliases":["Forearm stand"]},{"canonical":"Astavakrasana","prior":0.1,"aliases":["Eight-angle pose"]},{"canonical":"Tittibhasana","prior":0.1,"aliases":["Firefly pose"]},{"canonical":"Ananda Balasana","prior":0.3,"aliases":["Happy baby pose","Happy baby"]},{"canonical":"Sphinx pose","prior":0.3,"aliases":["Salamba Bhujangasana","Sphinx"]},{"canonical":"Gorakshasana","prior":0.1,"aliases":[]},{"canonical":"Padahastasana","prior":0.5,"aliases":["Hand to foot pose"]},{"canonical":"Ardha Chakrasana","prior":0.3,"aliases":["Half wheel pose"]},{"canonical":"Janu Sirsasana","prior":0.2,"aliases":["Head-to-knee pose"]},{"canonical":"Supta Baddha Konasana","prior":0.1,"aliases":["Reclining bound angle pose"]}]', NULL, 'Think of animals, plants, a mountain, a hero of myth and the pose you do lying flat at the very end.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-health-phobia', 'Name a phobia (a fear with a "-phobia" name).', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Hippopotomonstrosesquippedaliophobia is a joke name for the fear of long words. Arachibutyrophobia, another joke, is the fear of peanut butter sticking to the roof of your mouth.', 'https://en.wikipedia.org/wiki/List_of_phobias', 'Wikipedia: List of phobias', '2026-11-21', 'CC BY-SA 4.0', 'words', 2, 0, '[{"canonical":"Claustrophobia","prior":22,"aliases":[]},{"canonical":"Arachnophobia","prior":16,"aliases":[]},{"canonical":"Acrophobia","prior":10,"aliases":["Altophobia"]},{"canonical":"Hydrophobia","prior":6,"aliases":["Aquaphobia"]},{"canonical":"Agoraphobia","prior":6,"aliases":[]},{"canonical":"Coulrophobia","prior":4,"aliases":[]},{"canonical":"Triskaidekaphobia","prior":3,"aliases":[]},{"canonical":"Nyctophobia","prior":3,"aliases":["Achluophobia","Scotophobia"]},{"canonical":"Trypophobia","prior":3,"aliases":[]},{"canonical":"Xenophobia","prior":3,"aliases":[]},{"canonical":"Homophobia","prior":2,"aliases":[]},{"canonical":"Ophidiophobia","prior":2,"aliases":["Ophiophobia"]},{"canonical":"Hemophobia","prior":2,"aliases":["Haemophobia","Hematophobia"]},{"canonical":"Glossophobia","prior":2,"aliases":[]},{"canonical":"Aerophobia","prior":2,"aliases":["Aviophobia","Aviatophobia"]},{"canonical":"Cynophobia","prior":1,"aliases":[]},{"canonical":"Thanatophobia","prior":1,"aliases":[]},{"canonical":"Trypanophobia","prior":1,"aliases":["Aichmophobia","Belonephobia"]},{"canonical":"Astraphobia","prior":1,"aliases":["Brontophobia","Keraunophobia","Tonitrophobia"]},{"canonical":"Hippopotomonstrosesquippedaliophobia","prior":1,"aliases":["Sesquipedalophobia"]},{"canonical":"Nomophobia","prior":1,"aliases":[]},{"canonical":"Mysophobia","prior":1,"aliases":["Germophobia","Verminophobia"]},{"canonical":"Emetophobia","prior":1,"aliases":[]},{"canonical":"Social phobia","prior":1,"aliases":["Sociophobia","Anthropophobia"]},{"canonical":"Ailurophobia","prior":0.5,"aliases":["Felinophobia","Gatophobia"]},{"canonical":"Entomophobia","prior":0.5,"aliases":["Insectophobia"]},{"canonical":"Thalassophobia","prior":0.5,"aliases":[]},{"canonical":"Dentophobia","prior":0.5,"aliases":["Odontophobia"]},{"canonical":"Iatrophobia","prior":0.5,"aliases":[]},{"canonical":"Musophobia","prior":0.5,"aliases":["Murophobia"]},{"canonical":"Ornithophobia","prior":0.5,"aliases":[]},{"canonical":"Pyrophobia","prior":0.5,"aliases":[]},{"canonical":"Phasmophobia","prior":0.5,"aliases":[]},{"canonical":"Necrophobia","prior":0.5,"aliases":[]},{"canonical":"Gerascophobia","prior":0.3,"aliases":[]},{"canonical":"Philophobia","prior":0.5,"aliases":[]},{"canonical":"Gamophobia","prior":0.3,"aliases":[]},{"canonical":"Atychiphobia","prior":0.3,"aliases":["Kakorrhaphiophobia"]},{"canonical":"Autophobia","prior":0.3,"aliases":["Monophobia","Isolophobia"]},{"canonical":"Chronophobia","prior":0.2,"aliases":[]},{"canonical":"Arachibutyrophobia","prior":0.3,"aliases":[]},{"canonical":"Pogonophobia","prior":0.2,"aliases":[]},{"canonical":"Ombrophobia","prior":0.2,"aliases":[]},{"canonical":"Selenophobia","prior":0.1,"aliases":[]},{"canonical":"Heliophobia","prior":0.2,"aliases":[]},{"canonical":"Somniphobia","prior":0.2,"aliases":["Hypnophobia"]},{"canonical":"Chiroptophobia","prior":0.1,"aliases":[]},{"canonical":"Lepidopterophobia","prior":0.1,"aliases":[]},{"canonical":"Apiphobia","prior":0.2,"aliases":["Melissophobia"]},{"canonical":"Ichthyophobia","prior":0.1,"aliases":[]},{"canonical":"Batrachophobia","prior":0.1,"aliases":["Ranidaphobia"]},{"canonical":"Equinophobia","prior":0.1,"aliases":["Hippophobia"]},{"canonical":"Bacteriophobia","prior":0.1,"aliases":[]},{"canonical":"Cibophobia","prior":0.1,"aliases":["Sitophobia"]},{"canonical":"Lachanophobia","prior":0.1,"aliases":[]},{"canonical":"Pediophobia","prior":0.2,"aliases":[]},{"canonical":"Automatonophobia","prior":0.1,"aliases":[]},{"canonical":"Technophobia","prior":0.3,"aliases":[]},{"canonical":"Cyberphobia","prior":0.1,"aliases":[]},{"canonical":"Gephyrophobia","prior":0.1,"aliases":[]},{"canonical":"Hodophobia","prior":0.1,"aliases":[]},{"canonical":"Amaxophobia","prior":0.1,"aliases":[]},{"canonical":"Siderodromophobia","prior":0.05,"aliases":[]},{"canonical":"Bathophobia","prior":0.1,"aliases":[]},{"canonical":"Basophobia","prior":0.05,"aliases":[]},{"canonical":"Chionophobia","prior":0.05,"aliases":[]},{"canonical":"Anemophobia","prior":0.05,"aliases":[]},{"canonical":"Cryophobia","prior":0.05,"aliases":[]},{"canonical":"Thermophobia","prior":0.05,"aliases":[]},{"canonical":"Phonophobia","prior":0.1,"aliases":["Ligyrophobia"]},{"canonical":"Photophobia","prior":0.2,"aliases":[]},{"canonical":"Ergophobia","prior":0.1,"aliases":[]},{"canonical":"Scolionophobia","prior":0.1,"aliases":["Didaskaleinophobia"]},{"canonical":"Logophobia","prior":0.05,"aliases":[]},{"canonical":"Bibliophobia","prior":0.05,"aliases":[]},{"canonical":"Hexakosioihexekontahexaphobia","prior":0.2,"aliases":[]},{"canonical":"Tetraphobia","prior":0.1,"aliases":[]},{"canonical":"Paraskevidekatriaphobia","prior":0.1,"aliases":["Friggatriskaidekaphobia"]},{"canonical":"Omphalophobia","prior":0.05,"aliases":[]},{"canonical":"Xanthophobia","prior":0.05,"aliases":[]},{"canonical":"Chromophobia","prior":0.05,"aliases":[]},{"canonical":"Nosophobia","prior":0.1,"aliases":["Pathophobia"]},{"canonical":"Cardiophobia","prior":0.05,"aliases":[]},{"canonical":"Hylophobia","prior":0.05,"aliases":[]},{"canonical":"Megalophobia","prior":0.2,"aliases":[]},{"canonical":"Microphobia","prior":0.05,"aliases":[]},{"canonical":"Kinemortophobia","prior":0.05,"aliases":[]},{"canonical":"Allodoxaphobia","prior":0.05,"aliases":[]},{"canonical":"Ablutophobia","prior":0.1,"aliases":[]},{"canonical":"Koumpounophobia","prior":0.1,"aliases":[]},{"canonical":"Anatidaephobia","prior":0.1,"aliases":[]},{"canonical":"Turophobia","prior":0.05,"aliases":[]},{"canonical":"Alektorophobia","prior":0.05,"aliases":[]},{"canonical":"Samhainophobia","prior":0.05,"aliases":[]},{"canonical":"Spectrophobia","prior":0.05,"aliases":["Catoptrophobia","Eisoptrophobia"]},{"canonical":"Pteronophobia","prior":0.05,"aliases":[]},{"canonical":"Venustraphobia","prior":0.05,"aliases":["Caligynephobia"]},{"canonical":"Gymnophobia","prior":0.05,"aliases":[]}]', NULL, 'Think of heights, small rooms, spiders, water, crowds, clowns and the number after twelve.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-health-emotion', 'Name an emotion.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Natya Shastra, India''s ancient book on drama, names eight rasas, or moods, among them love, laughter, anger and fear. Later writers added a ninth, shanta, peace, which gave the famous nine rasas.', 'https://en.wikipedia.org/wiki/Emotion', 'Wikipedia: Emotion', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Happiness","prior":20,"aliases":["Happy","Joy","Joyful","Hasya"]},{"canonical":"Sadness","prior":18,"aliases":["Sad","Sorrow","Grief","Karuna","Unhappiness"]},{"canonical":"Anger","prior":18,"aliases":["Angry","Rage","Fury","Raudra","Krodh","Gussa"]},{"canonical":"Fear","prior":10,"aliases":["Scared","Afraid","Bhayanaka","Bhaya","Terror"]},{"canonical":"Love","prior":10,"aliases":["Shringara","Pyaar","Prem","Affection"]},{"canonical":"Excitement","prior":4,"aliases":["Excited","Thrill"]},{"canonical":"Disgust","prior":4,"aliases":["Disgusted","Bibhatsa","Revulsion"]},{"canonical":"Surprise","prior":4,"aliases":["Surprised","Wonder","Adbhuta","Astonishment","Amazement"]},{"canonical":"Jealousy","prior":4,"aliases":["Jealous"]},{"canonical":"Anxiety","prior":4,"aliases":["Anxious","Nervousness","Nervous","Worry"]},{"canonical":"Envy","prior":2,"aliases":["Envious"]},{"canonical":"Embarrassment","prior":2,"aliases":["Embarrassed"]},{"canonical":"Shame","prior":2,"aliases":["Ashamed"]},{"canonical":"Guilt","prior":2,"aliases":["Guilty"]},{"canonical":"Pride","prior":2,"aliases":["Proud"]},{"canonical":"Boredom","prior":2,"aliases":["Bored","Ennui"]},{"canonical":"Loneliness","prior":2,"aliases":["Lonely"]},{"canonical":"Hope","prior":2,"aliases":["Hopeful"]},{"canonical":"Peace","prior":2,"aliases":["Calm","Calmness","Shanta","Serenity","Tranquillity","Contentment","Content"]},{"canonical":"Courage","prior":1,"aliases":["Bravery","Veera","Vira","Heroism"]},{"canonical":"Frustration","prior":1,"aliases":["Frustrated"]},{"canonical":"Confusion","prior":1,"aliases":["Confused"]},{"canonical":"Gratitude","prior":1,"aliases":["Grateful","Thankfulness"]},{"canonical":"Nostalgia","prior":1,"aliases":["Nostalgic"]},{"canonical":"Curiosity","prior":1,"aliases":["Curious"]},{"canonical":"Relief","prior":1,"aliases":["Relieved"]},{"canonical":"Awe","prior":1,"aliases":[]},{"canonical":"Amusement","prior":1,"aliases":["Amused","Laughter","Mirth"]},{"canonical":"Hatred","prior":1,"aliases":["Hate"]},{"canonical":"Despair","prior":1,"aliases":["Hopelessness"]},{"canonical":"Regret","prior":1,"aliases":["Remorse"]},{"canonical":"Sympathy","prior":0.5,"aliases":["Compassion","Empathy","Pity"]},{"canonical":"Trust","prior":0.5,"aliases":[]},{"canonical":"Anticipation","prior":0.5,"aliases":[]},{"canonical":"Longing","prior":0.5,"aliases":["Yearning"]},{"canonical":"Irritation","prior":0.5,"aliases":["Annoyance","Annoyed","Irritated"]},{"canonical":"Panic","prior":0.5,"aliases":[]},{"canonical":"Ecstasy","prior":0.5,"aliases":["Euphoria","Bliss","Elation"]},{"canonical":"Melancholy","prior":0.5,"aliases":[]},{"canonical":"Resentment","prior":0.5,"aliases":[]},{"canonical":"Contempt","prior":0.5,"aliases":["Scorn"]},{"canonical":"Admiration","prior":0.5,"aliases":[]},{"canonical":"Desire","prior":0.5,"aliases":["Lust"]},{"canonical":"Shyness","prior":0.5,"aliases":["Shy"]},{"canonical":"Insecurity","prior":0.3,"aliases":["Insecure"]},{"canonical":"Disappointment","prior":0.5,"aliases":["Disappointed"]},{"canonical":"Satisfaction","prior":0.3,"aliases":["Satisfied"]},{"canonical":"Dread","prior":0.3,"aliases":[]},{"canonical":"Homesickness","prior":0.3,"aliases":["Homesick"]},{"canonical":"Schadenfreude","prior":0.3,"aliases":[]},{"canonical":"FOMO","prior":0.2,"aliases":["Fear of missing out"]},{"canonical":"Saudade","prior":0.1,"aliases":[]},{"canonical":"Hygge","prior":0.1,"aliases":[]},{"canonical":"Wanderlust","prior":0.1,"aliases":[]},{"canonical":"Apathy","prior":0.2,"aliases":[]},{"canonical":"Optimism","prior":0.2,"aliases":[]},{"canonical":"Indignation","prior":0.1,"aliases":[]},{"canonical":"Tenderness","prior":0.1,"aliases":[]},{"canonical":"Wistfulness","prior":0.05,"aliases":[]}]', NULL, 'Think of the faces in a cartoon about feelings, the mood after a long wait and the nine rasas of Indian dance.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-health-virus', 'Name an illness caused by a virus.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Smallpox, caused by the variola virus, is the only human disease ever wiped out. The World Health Assembly declared it eradicated in 1980.', 'https://en.wikipedia.org/wiki/Viral_disease', 'Wikipedia: Viral disease', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"COVID-19","prior":22,"aliases":["Covid","Covid 19","Coronavirus","Corona","SARS-CoV-2"]},{"canonical":"Common cold","prior":14,"aliases":["Cold","Colds","Flu-like cold","Rhinovirus"]},{"canonical":"Flu","prior":14,"aliases":["Influenza","Bird flu","Swine flu","H1N1","Avian flu"]},{"canonical":"Dengue","prior":10,"aliases":["Dengue fever"]},{"canonical":"Chickenpox","prior":8,"aliases":["Chicken pox","Varicella","Chhoti mata"]},{"canonical":"Measles","prior":6,"aliases":["Khasra","Rubeola"]},{"canonical":"HIV","prior":4,"aliases":["AIDS","HIV/AIDS"]},{"canonical":"Chikungunya","prior":4,"aliases":[]},{"canonical":"Polio","prior":4,"aliases":["Poliomyelitis"]},{"canonical":"Rabies","prior":3,"aliases":[]},{"canonical":"Hepatitis","prior":3,"aliases":["Hepatitis A","Hepatitis B","Hepatitis C","Hepatitis E"]},{"canonical":"Smallpox","prior":2,"aliases":["Small pox","Variola","Badi mata"]},{"canonical":"Mumps","prior":2,"aliases":[]},{"canonical":"Ebola","prior":2,"aliases":[]},{"canonical":"Zika","prior":2,"aliases":["Zika fever"]},{"canonical":"Herpes","prior":1,"aliases":["Cold sores","Cold sore","Genital herpes"]},{"canonical":"Shingles","prior":1,"aliases":["Herpes zoster"]},{"canonical":"Rubella","prior":1,"aliases":["German measles"]},{"canonical":"Mpox","prior":1,"aliases":["Monkeypox","Monkey pox"]},{"canonical":"Nipah","prior":1,"aliases":["Nipah virus"]},{"canonical":"Japanese encephalitis","prior":1,"aliases":["Encephalitis","Brain fever"]},{"canonical":"Yellow fever","prior":1,"aliases":[]},{"canonical":"SARS","prior":1,"aliases":[]},{"canonical":"MERS","prior":0.5,"aliases":[]},{"canonical":"Warts","prior":0.5,"aliases":["Wart","HPV","Human papillomavirus"]},{"canonical":"Viral fever","prior":0.5,"aliases":[]},{"canonical":"Conjunctivitis","prior":0.5,"aliases":["Pink eye","Eye flu","Madras eye"]},{"canonical":"Hand, foot and mouth disease","prior":0.5,"aliases":["Hand foot and mouth","HFMD","Tomato flu"]},{"canonical":"Norovirus","prior":0.5,"aliases":["Stomach flu","Winter vomiting bug"]},{"canonical":"Rotavirus","prior":0.5,"aliases":[]},{"canonical":"Glandular fever","prior":0.3,"aliases":["Mononucleosis","Mono","Kissing disease"]},{"canonical":"West Nile fever","prior":0.3,"aliases":["West Nile virus","West Nile"]},{"canonical":"Lassa fever","prior":0.2,"aliases":[]},{"canonical":"Marburg","prior":0.2,"aliases":["Marburg virus"]},{"canonical":"Kyasanur Forest disease","prior":0.1,"aliases":["Monkey fever","KFD"]},{"canonical":"Hantavirus","prior":0.2,"aliases":[]},{"canonical":"Croup","prior":0.2,"aliases":[]},{"canonical":"Bronchiolitis","prior":0.1,"aliases":["RSV","Respiratory syncytial virus"]},{"canonical":"Crimean-Congo haemorrhagic fever","prior":0.1,"aliases":["CCHF"]},{"canonical":"Chandipura","prior":0.1,"aliases":["Chandipura virus"]},{"canonical":"Rift Valley fever","prior":0.05,"aliases":[]},{"canonical":"Fifth disease","prior":0.1,"aliases":["Slapped cheek"]},{"canonical":"Roseola","prior":0.1,"aliases":[]},{"canonical":"Molluscum contagiosum","prior":0.05,"aliases":[]},{"canonical":"Viral gastroenteritis","prior":0.2,"aliases":["Gastroenteritis","Gastro"]},{"canonical":"Viral pneumonia","prior":0.1,"aliases":[]},{"canonical":"Viral meningitis","prior":0.1,"aliases":[]},{"canonical":"Tick-borne encephalitis","prior":0.05,"aliases":[]},{"canonical":"Hendra","prior":0.05,"aliases":[]},{"canonical":"Oropouche","prior":0.05,"aliases":[]}]', NULL, 'Think of what mosquitoes spread in the monsoon, what spots children''s skin, and what shut the world in 2020.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-health-joint', 'Name a joint in the human body.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'A baby''s skull is several plates joined by flexible sutures that fuse as it grows. The base of your thumb is a saddle joint, which lets your thumb cross over your palm.', 'https://en.wikipedia.org/wiki/Joint', 'Wikipedia: Joint', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Knee","prior":24,"aliases":["Knees","Knee joint"]},{"canonical":"Elbow","prior":20,"aliases":["Elbows","Elbow joint"]},{"canonical":"Shoulder","prior":14,"aliases":["Shoulders","Shoulder joint"]},{"canonical":"Hip","prior":10,"aliases":["Hips","Hip joint"]},{"canonical":"Ankle","prior":8,"aliases":["Ankles","Ankle joint"]},{"canonical":"Wrist","prior":8,"aliases":["Wrists","Wrist joint"]},{"canonical":"Knuckle","prior":4,"aliases":["Knuckles","Finger joint","Finger joints"]},{"canonical":"Neck","prior":2,"aliases":["Neck joint","Cervical spine"]},{"canonical":"Jaw","prior":2,"aliases":["Jaw joint","Temporomandibular joint","TMJ"]},{"canonical":"Ball and socket joint","prior":2,"aliases":["Ball and socket","Ball-and-socket"]},{"canonical":"Hinge joint","prior":2,"aliases":["Hinge"]},{"canonical":"Toe joint","prior":1,"aliases":["Toes","Toe joints","Big toe joint"]},{"canonical":"Spine","prior":1,"aliases":["Vertebrae","Spinal joints","Backbone","Intervertebral joint","Facet joint"]},{"canonical":"Pivot joint","prior":1,"aliases":["Pivot"]},{"canonical":"Saddle joint","prior":1,"aliases":["Saddle"]},{"canonical":"Gliding joint","prior":1,"aliases":["Plane joint","Gliding"]},{"canonical":"Condyloid joint","prior":0.5,"aliases":["Ellipsoid joint","Condyloid"]},{"canonical":"Thumb joint","prior":0.5,"aliases":["Thumb","Carpometacarpal joint"]},{"canonical":"Sacroiliac joint","prior":0.5,"aliases":["Sacroiliac","SI joint"]},{"canonical":"Skull sutures","prior":0.5,"aliases":["Sutures","Suture","Cranial sutures"]},{"canonical":"Atlas and axis","prior":0.3,"aliases":["Atlanto-axial joint","Atlantoaxial","Atlas","Axis"]},{"canonical":"Collarbone joint","prior":0.3,"aliases":["Sternoclavicular joint","Acromioclavicular joint","AC joint"]},{"canonical":"Rib joints","prior":0.3,"aliases":["Ribs","Costovertebral joint"]},{"canonical":"Pubic symphysis","prior":0.2,"aliases":[]},{"canonical":"Fixed joint","prior":0.5,"aliases":["Fibrous joint","Immovable joint"]},{"canonical":"Cartilaginous joint","prior":0.2,"aliases":[]},{"canonical":"Synovial joint","prior":0.3,"aliases":[]},{"canonical":"Metacarpophalangeal joint","prior":0.1,"aliases":["MCP joint"]},{"canonical":"Interphalangeal joint","prior":0.1,"aliases":[]},{"canonical":"Heel","prior":0.1,"aliases":["Subtalar joint"]},{"canonical":"Gomphosis","prior":0.05,"aliases":["Tooth socket"]}]', NULL, 'Think of where your arms and legs bend, the small bones of your fingers, and the kinds of joint in a biology textbook.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-school-geometry', 'Name something you''d find in a geometry box.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Euclid''s geometry was built with only two tools, an unmarked straightedge and a compass. The protractor''s 180 degrees go back to Babylonian astronomers, who counted in sixties.', 'https://en.wikipedia.org/wiki/Compass_(drawing_tool)', 'Wikipedia: Compass (drawing tool)', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"Compass","prior":22,"aliases":["Compasses","Pair of compasses"]},{"canonical":"Protractor","prior":18,"aliases":[]},{"canonical":"Ruler","prior":16,"aliases":["Scale","Foot ruler","Steel scale"]},{"canonical":"Divider","prior":10,"aliases":["Dividers"]},{"canonical":"Set square","prior":8,"aliases":["Set squares","Triangle scale","Triangles"]},{"canonical":"Pencil","prior":8,"aliases":[]},{"canonical":"Eraser","prior":8,"aliases":["Rubber"]},{"canonical":"Sharpener","prior":6,"aliases":["Pencil sharpener"]},{"canonical":"Pencil lead","prior":2,"aliases":["Lead","Leads","Refill"]},{"canonical":"Pen","prior":1,"aliases":["Ballpoint","Ball pen"]},{"canonical":"Stencil","prior":1,"aliases":["Stencils","Map stencil"]},{"canonical":"Tables card","prior":0.5,"aliases":["Timetable card","Multiplication table","Tables chart","Times tables"]},{"canonical":"Mechanical pencil","prior":0.5,"aliases":["Pacer","Clutch pencil"]},{"canonical":"Glue stick","prior":0.3,"aliases":["Glue"]}]', NULL, 'Think of what draws circles, what measures angles, what has two sharp points and what fixes your mistakes.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-school-subject', 'Name a school subject.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'SUPW, ''socially useful productive work'', came into Indian schools after a 1977 review committee led by Ishwarbhai Patel. Plenty of students remember it as the period nobody quite understood.', 'https://en.wikipedia.org/wiki/Curriculum', 'Wikipedia: Curriculum', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"Mathematics","prior":22,"aliases":["Maths","Math","Ganit"]},{"canonical":"Science","prior":14,"aliases":["General science","Vigyan"]},{"canonical":"English","prior":12,"aliases":[]},{"canonical":"History","prior":8,"aliases":["Itihas"]},{"canonical":"Geography","prior":6,"aliases":["Bhugol"]},{"canonical":"Hindi","prior":6,"aliases":[]},{"canonical":"Physics","prior":4,"aliases":[]},{"canonical":"Chemistry","prior":4,"aliases":[]},{"canonical":"Biology","prior":4,"aliases":["Bio"]},{"canonical":"Social studies","prior":4,"aliases":["Social science","SST","Social"]},{"canonical":"Computer science","prior":3,"aliases":["Computers","Computer","Computer studies","IT","Information technology","ICT"]},{"canonical":"Physical education","prior":3,"aliases":["PE","PT","Games","Sports","Gym","PE class"]},{"canonical":"Art","prior":3,"aliases":["Drawing","Arts","Art and craft","Painting"]},{"canonical":"Music","prior":2,"aliases":[]},{"canonical":"Sanskrit","prior":2,"aliases":[]},{"canonical":"Economics","prior":2,"aliases":["Eco"]},{"canonical":"EVS","prior":2,"aliases":["Environmental studies","Environmental science","Environmental education"]},{"canonical":"Moral science","prior":1,"aliases":["Value education","Moral education","Ethics"]},{"canonical":"Civics","prior":1,"aliases":["Political science","Politics","Polity"]},{"canonical":"SUPW","prior":1,"aliases":["Socially useful productive work","Work experience"]},{"canonical":"Accountancy","prior":1,"aliases":["Accounts","Accounting"]},{"canonical":"Business studies","prior":1,"aliases":["Business","Commerce"]},{"canonical":"French","prior":1,"aliases":[]},{"canonical":"German","prior":0.5,"aliases":[]},{"canonical":"Spanish","prior":0.5,"aliases":[]},{"canonical":"Tamil","prior":0.5,"aliases":[]},{"canonical":"Marathi","prior":0.5,"aliases":[]},{"canonical":"Bengali","prior":0.5,"aliases":["Bangla"]},{"canonical":"Telugu","prior":0.5,"aliases":[]},{"canonical":"Kannada","prior":0.5,"aliases":[]},{"canonical":"Malayalam","prior":0.5,"aliases":[]},{"canonical":"Gujarati","prior":0.5,"aliases":[]},{"canonical":"Punjabi","prior":0.5,"aliases":[]},{"canonical":"Urdu","prior":0.5,"aliases":[]},{"canonical":"Odia","prior":0.3,"aliases":["Oriya"]},{"canonical":"Assamese","prior":0.2,"aliases":[]},{"canonical":"Craft","prior":0.5,"aliases":["Handicraft","SUPW craft"]},{"canonical":"Dance","prior":0.5,"aliases":[]},{"canonical":"Library","prior":0.5,"aliases":["Library period"]},{"canonical":"General knowledge","prior":0.5,"aliases":["GK"]},{"canonical":"Psychology","prior":0.5,"aliases":[]},{"canonical":"Sociology","prior":0.3,"aliases":[]},{"canonical":"Home science","prior":0.5,"aliases":[]},{"canonical":"Drama","prior":0.3,"aliases":["Theatre"]},{"canonical":"Statistics","prior":0.3,"aliases":[]},{"canonical":"Philosophy","prior":0.2,"aliases":[]},{"canonical":"Agriculture","prior":0.2,"aliases":[]},{"canonical":"Yoga","prior":0.3,"aliases":[]},{"canonical":"Latin","prior":0.2,"aliases":[]},{"canonical":"Japanese","prior":0.1,"aliases":[]},{"canonical":"Mandarin","prior":0.1,"aliases":["Chinese"]},{"canonical":"Robotics","prior":0.2,"aliases":["Coding","Programming"]},{"canonical":"Entrepreneurship","prior":0.1,"aliases":[]},{"canonical":"Legal studies","prior":0.1,"aliases":[]},{"canonical":"Fine arts","prior":0.2,"aliases":[]},{"canonical":"Woodwork","prior":0.1,"aliases":["Carpentry"]},{"canonical":"Needlework","prior":0.1,"aliases":["Stitching","Sewing"]},{"canonical":"Cooking","prior":0.1,"aliases":["Food technology","Home economics"]},{"canonical":"Life skills","prior":0.1,"aliases":[]},{"canonical":"Media studies","prior":0.1,"aliases":[]},{"canonical":"Astronomy","prior":0.1,"aliases":[]},{"canonical":"Algebra","prior":0.2,"aliases":[]},{"canonical":"Geometry","prior":0.2,"aliases":[]},{"canonical":"Calculus","prior":0.1,"aliases":[]},{"canonical":"Grammar","prior":0.2,"aliases":[]},{"canonical":"Literature","prior":0.2,"aliases":[]},{"canonical":"Botany","prior":0.2,"aliases":[]},{"canonical":"Zoology","prior":0.2,"aliases":[]},{"canonical":"Typing","prior":0.05,"aliases":[]}]', NULL, 'Think of the weekly timetable: the labs, the languages, the free periods outside and the class nobody took seriously.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-school-shape', 'Name a flat shape.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'A trapezium in British and Indian English is a trapezoid in American English. Britain''s 50p coin is a seven-sided shape with curved edges that is the same width in every direction, so it rolls smoothly through slot machines.', 'https://en.wikipedia.org/wiki/List_of_two-dimensional_geometric_shapes', 'Wikipedia: List of two-dimensional geometric shapes', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"Circle","prior":20,"aliases":[]},{"canonical":"Square","prior":20,"aliases":[]},{"canonical":"Triangle","prior":18,"aliases":[]},{"canonical":"Rectangle","prior":14,"aliases":[]},{"canonical":"Pentagon","prior":6,"aliases":[]},{"canonical":"Hexagon","prior":6,"aliases":[]},{"canonical":"Octagon","prior":4,"aliases":[]},{"canonical":"Oval","prior":4,"aliases":[]},{"canonical":"Rhombus","prior":3,"aliases":["Diamond","Lozenge"]},{"canonical":"Star","prior":3,"aliases":["Pentagram"]},{"canonical":"Heart","prior":3,"aliases":[]},{"canonical":"Parallelogram","prior":2,"aliases":[]},{"canonical":"Trapezium","prior":2,"aliases":["Trapezoid"]},{"canonical":"Semicircle","prior":1,"aliases":["Semi-circle","Half circle"]},{"canonical":"Ellipse","prior":1,"aliases":[]},{"canonical":"Crescent","prior":1,"aliases":["Crescent moon","Moon"]},{"canonical":"Kite","prior":1,"aliases":[]},{"canonical":"Heptagon","prior":1,"aliases":["Septagon"]},{"canonical":"Nonagon","prior":0.5,"aliases":["Enneagon"]},{"canonical":"Decagon","prior":0.5,"aliases":[]},{"canonical":"Quadrilateral","prior":0.5,"aliases":[]},{"canonical":"Polygon","prior":0.5,"aliases":[]},{"canonical":"Dodecagon","prior":0.3,"aliases":[]},{"canonical":"Sector","prior":0.3,"aliases":[]},{"canonical":"Arrow","prior":0.3,"aliases":["Arrowhead"]},{"canonical":"Cross","prior":0.3,"aliases":["Plus"]},{"canonical":"Ring","prior":0.3,"aliases":["Annulus"]},{"canonical":"Spade","prior":0.2,"aliases":[]},{"canonical":"Club","prior":0.1,"aliases":["Trefoil"]},{"canonical":"Hendecagon","prior":0.1,"aliases":["Undecagon"]},{"canonical":"Icosagon","prior":0.05,"aliases":[]},{"canonical":"Reuleaux triangle","prior":0.1,"aliases":[]},{"canonical":"Lune","prior":0.05,"aliases":[]},{"canonical":"Segment","prior":0.1,"aliases":[]},{"canonical":"Scalene triangle","prior":0.2,"aliases":[]},{"canonical":"Isosceles triangle","prior":0.2,"aliases":[]},{"canonical":"Equilateral triangle","prior":0.2,"aliases":[]},{"canonical":"Right-angled triangle","prior":0.2,"aliases":["Right triangle"]},{"canonical":"Hexagram","prior":0.1,"aliases":["Star of David"]},{"canonical":"Spiral","prior":0.1,"aliases":[]},{"canonical":"Deltoid","prior":0.05,"aliases":[]},{"canonical":"Squircle","prior":0.05,"aliases":[]},{"canonical":"Vesica piscis","prior":0.05,"aliases":[]},{"canonical":"Chevron","prior":0.1,"aliases":[]},{"canonical":"Teardrop","prior":0.1,"aliases":[]},{"canonical":"Arbelos","prior":0.02,"aliases":[]}]', NULL, 'Think of road signs, honeycombs, playing-card suits, the night sky and the slices of a pizza.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-school-punct', 'Name a punctuation mark.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Hindi and other Indian scripts end a sentence with a single upright stroke, the purna viram or danda. The interrobang, a question mark and exclamation mark in one, was dreamt up by an American advertising man in 1962.', 'https://en.wikipedia.org/wiki/Punctuation', 'Wikipedia: Punctuation', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"Full stop","prior":20,"aliases":["Period","Dot","Point"]},{"canonical":"Comma","prior":18,"aliases":[]},{"canonical":"Question mark","prior":14,"aliases":[]},{"canonical":"Exclamation mark","prior":10,"aliases":["Exclamation point","Exclamation"]},{"canonical":"Apostrophe","prior":6,"aliases":[]},{"canonical":"Colon","prior":6,"aliases":[]},{"canonical":"Semicolon","prior":6,"aliases":["Semi-colon"]},{"canonical":"Quotation marks","prior":6,"aliases":["Quotes","Inverted commas","Speech marks","Quotation mark","Double quotes"]},{"canonical":"Hyphen","prior":4,"aliases":[]},{"canonical":"Brackets","prior":4,"aliases":["Parentheses","Bracket","Parenthesis","Round brackets","Square brackets","Curly brackets","Braces"]},{"canonical":"Dash","prior":2,"aliases":["Em dash","En dash"]},{"canonical":"Ellipsis","prior":2,"aliases":["Dot dot dot","Three dots"]},{"canonical":"Slash","prior":1,"aliases":["Forward slash","Oblique","Stroke"]},{"canonical":"Purna viram","prior":1,"aliases":["Danda","Poorna viram","Viram"]},{"canonical":"Interrobang","prior":0.5,"aliases":[]},{"canonical":"Backslash","prior":0.3,"aliases":[]},{"canonical":"Asterisk","prior":0.3,"aliases":[]},{"canonical":"Ampersand","prior":0.3,"aliases":["And sign"]},{"canonical":"Bullet point","prior":0.2,"aliases":["Bullet"]},{"canonical":"Guillemets","prior":0.1,"aliases":["Angle quotes"]},{"canonical":"Pilcrow","prior":0.05,"aliases":["Paragraph mark"]},{"canonical":"Tilde","prior":0.1,"aliases":[]},{"canonical":"Pipe","prior":0.05,"aliases":["Vertical bar"]},{"canonical":"Inverted question mark","prior":0.1,"aliases":[]},{"canonical":"Prime","prior":0.02,"aliases":[]},{"canonical":"Caret","prior":0.05,"aliases":[]},{"canonical":"Underscore","prior":0.1,"aliases":[]},{"canonical":"Hash","prior":0.1,"aliases":["Hashtag","Pound sign"]},{"canonical":"Double danda","prior":0.05,"aliases":[]}]', NULL, 'Think of how a sentence ends, how speech is shown, what joins two words and how Hindi stops a sentence.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-school-roman', 'Name a letter used in Roman numerals.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Roman numerals have no zero. Clock faces often show four as IIII rather than IV, a habit that goes back centuries and nobody fully agrees on.', 'https://en.wikipedia.org/wiki/Roman_numerals', 'Wikipedia: Roman numerals', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"I","prior":22,"aliases":[]},{"canonical":"X","prior":20,"aliases":[]},{"canonical":"V","prior":18,"aliases":[]},{"canonical":"C","prior":12,"aliases":[]},{"canonical":"M","prior":10,"aliases":[]},{"canonical":"L","prior":10,"aliases":[]},{"canonical":"D","prior":8,"aliases":[]}]', NULL, 'There are only seven, and they stand for 1, 5, 10, 50, 100, 500 and 1,000.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-school-grammar', 'Name a part of speech in English grammar.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Greek grammarian Dionysius Thrax listed eight parts of speech over two thousand years ago. Centuries before him, Panini wrote a grammar of Sanskrit in nearly 4,000 short rules.', 'https://en.wikipedia.org/wiki/Part_of_speech', 'Wikipedia: Part of speech', '2026-11-21', 'CC BY-SA 4.0', 'words', 1, 0, '[{"canonical":"Noun","prior":26,"aliases":["Nouns","Proper noun","Common noun"]},{"canonical":"Verb","prior":22,"aliases":["Verbs"]},{"canonical":"Adjective","prior":16,"aliases":["Adjectives"]},{"canonical":"Adverb","prior":10,"aliases":["Adverbs"]},{"canonical":"Pronoun","prior":10,"aliases":["Pronouns"]},{"canonical":"Preposition","prior":6,"aliases":["Prepositions"]},{"canonical":"Conjunction","prior":6,"aliases":["Conjunctions","Connective"]},{"canonical":"Interjection","prior":4,"aliases":["Interjections","Exclamation"]},{"canonical":"Article","prior":2,"aliases":["Articles","Determiner","Determiners"]},{"canonical":"Participle","prior":0.5,"aliases":[]},{"canonical":"Gerund","prior":0.3,"aliases":[]},{"canonical":"Auxiliary verb","prior":0.3,"aliases":["Helping verb","Modal verb","Modal"]},{"canonical":"Infinitive","prior":0.2,"aliases":[]},{"canonical":"Numeral","prior":0.2,"aliases":["Number"]},{"canonical":"Particle","prior":0.1,"aliases":[]},{"canonical":"Postposition","prior":0.05,"aliases":[]},{"canonical":"Classifier","prior":0.02,"aliases":[]}]', NULL, 'Think of naming words, doing words, describing words and the little words that join or exclaim.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-school-scientist', 'Name a famous Indian scientist or mathematician.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'C. V. Raman won the 1930 Nobel Prize in Physics for the Raman effect, which he announced on 28 February 1928; India marks that date as National Science Day. Ramanujan, mostly self-taught, left notebooks with nearly 3,900 results.', 'https://en.wikipedia.org/wiki/List_of_Indian_scientists', 'Wikipedia: List of Indian scientists', '2026-11-21', 'CC BY-SA 4.0', 'science', 2, 0, '[{"canonical":"APJ Abdul Kalam","prior":22,"aliases":["Abdul Kalam","A. P. J. Abdul Kalam","Kalam","Dr Kalam"]},{"canonical":"CV Raman","prior":18,"aliases":["C. V. Raman","Raman","Chandrasekhara Venkata Raman"]},{"canonical":"Srinivasa Ramanujan","prior":16,"aliases":["Ramanujan"]},{"canonical":"Aryabhata","prior":10,"aliases":["Aryabhatta","Aryabhat"]},{"canonical":"Homi Bhabha","prior":8,"aliases":["Homi J. Bhabha","Bhabha","Homi Jehangir Bhabha"]},{"canonical":"Vikram Sarabhai","prior":8,"aliases":["Sarabhai"]},{"canonical":"Jagadish Chandra Bose","prior":6,"aliases":["J. C. Bose","JC Bose","Jagdish Chandra Bose"]},{"canonical":"Satyendra Nath Bose","prior":4,"aliases":["S. N. Bose","SN Bose","Satyendranath Bose"]},{"canonical":"Subrahmanyan Chandrasekhar","prior":3,"aliases":["Chandrasekhar","S. Chandrasekhar"]},{"canonical":"Bhaskara","prior":3,"aliases":["Bhaskaracharya","Bhaskara II","Bhaskara I"]},{"canonical":"Brahmagupta","prior":2,"aliases":[]},{"canonical":"Har Gobind Khorana","prior":2,"aliases":["Khorana","Hargobind Khorana"]},{"canonical":"Venkatraman Ramakrishnan","prior":1,"aliases":["Venki Ramakrishnan","Venki"]},{"canonical":"M. Visvesvaraya","prior":1,"aliases":["Visvesvaraya","Sir M. V.","Mokshagundam Visvesvaraya"]},{"canonical":"Satish Dhawan","prior":1,"aliases":[]},{"canonical":"Meghnad Saha","prior":1,"aliases":["Saha"]},{"canonical":"Shakuntala Devi","prior":2,"aliases":[]},{"canonical":"Salim Ali","prior":1,"aliases":[]},{"canonical":"MS Swaminathan","prior":1,"aliases":["M. S. Swaminathan","Swaminathan"]},{"canonical":"Verghese Kurien","prior":1,"aliases":["Kurien"]},{"canonical":"Prafulla Chandra Ray","prior":1,"aliases":["P. C. Ray","Acharya P. C. Ray"]},{"canonical":"Kalpana Chawla","prior":2,"aliases":[]},{"canonical":"Sushruta","prior":1,"aliases":["Susruta"]},{"canonical":"Charaka","prior":1,"aliases":[]},{"canonical":"Varahamihira","prior":0.5,"aliases":[]},{"canonical":"Panini","prior":0.5,"aliases":[]},{"canonical":"Kanada","prior":0.5,"aliases":[]},{"canonical":"Baudhayana","prior":0.5,"aliases":[]},{"canonical":"Madhava of Sangamagrama","prior":0.3,"aliases":["Madhava"]},{"canonical":"Pingala","prior":0.3,"aliases":[]},{"canonical":"Birbal Sahni","prior":0.5,"aliases":[]},{"canonical":"Janaki Ammal","prior":0.3,"aliases":["E. K. Janaki Ammal"]},{"canonical":"Asima Chatterjee","prior":0.3,"aliases":[]},{"canonical":"Anna Mani","prior":0.3,"aliases":[]},{"canonical":"Tessy Thomas","prior":0.5,"aliases":[]},{"canonical":"Manjul Bhargava","prior":0.3,"aliases":[]},{"canonical":"Harish-Chandra","prior":0.2,"aliases":["Harish Chandra"]},{"canonical":"PC Mahalanobis","prior":0.3,"aliases":["P. C. Mahalanobis","Mahalanobis"]},{"canonical":"CR Rao","prior":0.3,"aliases":["C. R. Rao","Calyampudi Radhakrishna Rao"]},{"canonical":"CNR Rao","prior":0.5,"aliases":["C. N. R. Rao"]},{"canonical":"Jayant Narlikar","prior":0.5,"aliases":["Narlikar"]},{"canonical":"Raja Ramanna","prior":0.3,"aliases":[]},{"canonical":"K. Sivan","prior":0.3,"aliases":["Sivan"]},{"canonical":"S. Somanath","prior":0.3,"aliases":["Somanath"]},{"canonical":"Yellapragada Subbarow","prior":0.2,"aliases":["Subbarow"]},{"canonical":"D. R. Kaprekar","prior":0.2,"aliases":["Kaprekar"]},{"canonical":"G. N. Ramachandran","prior":0.2,"aliases":["Ramachandran"]},{"canonical":"Narinder Singh Kapany","prior":0.2,"aliases":["Kapany"]},{"canonical":"Kamala Sohonie","prior":0.1,"aliases":[]},{"canonical":"Gagandeep Kang","prior":0.1,"aliases":[]},{"canonical":"Ashoke Sen","prior":0.1,"aliases":[]},{"canonical":"Raj Reddy","prior":0.1,"aliases":[]},{"canonical":"Abhay Ashtekar","prior":0.05,"aliases":[]},{"canonical":"Bimla Buti","prior":0.02,"aliases":[]},{"canonical":"Ritu Karidhal","prior":0.3,"aliases":[]},{"canonical":"Mylswamy Annadurai","prior":0.2,"aliases":["Annadurai"]},{"canonical":"Shanti Swarup Bhatnagar","prior":0.3,"aliases":["Bhatnagar"]},{"canonical":"Vainu Bappu","prior":0.1,"aliases":[]},{"canonical":"Anil Kakodkar","prior":0.2,"aliases":[]},{"canonical":"Udupi Ramachandra Rao","prior":0.2,"aliases":["U. R. Rao","UR Rao"]},{"canonical":"Sam Pitroda","prior":0.2,"aliases":[]},{"canonical":"Kiran Mazumdar-Shaw","prior":0.1,"aliases":[]}]', NULL, 'Think of the Missile Man, the man who knew infinity, the founders of India''s space and nuclear programmes, and ancient astronomers.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-myth-creature', 'Name a mythical creature.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Temple gates across South India are guarded by the yali, a lion-like beast often given an elephant''s trunk, and the river goddess Ganga rides the makara, part crocodile and part fish.', 'https://en.wikipedia.org/wiki/List_of_legendary_creatures_by_type', 'Wikipedia: List of legendary creatures by type', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Dragon","prior":20,"aliases":["Dragons"]},{"canonical":"Unicorn","prior":18,"aliases":["Unicorns"]},{"canonical":"Mermaid","prior":10,"aliases":["Merman","Mermaids","Jalpari"]},{"canonical":"Phoenix","prior":8,"aliases":[]},{"canonical":"Centaur","prior":4,"aliases":[]},{"canonical":"Griffin","prior":4,"aliases":["Gryphon","Griffon"]},{"canonical":"Pegasus","prior":4,"aliases":["Winged horse"]},{"canonical":"Yeti","prior":4,"aliases":["Abominable Snowman","Migoi"]},{"canonical":"Vampire","prior":3,"aliases":["Dracula"]},{"canonical":"Werewolf","prior":3,"aliases":[]},{"canonical":"Bigfoot","prior":2,"aliases":["Sasquatch"]},{"canonical":"Kraken","prior":2,"aliases":[]},{"canonical":"Minotaur","prior":2,"aliases":[]},{"canonical":"Medusa","prior":2,"aliases":["Gorgon"]},{"canonical":"Cyclops","prior":2,"aliases":[]},{"canonical":"Hydra","prior":2,"aliases":[]},{"canonical":"Sphinx","prior":2,"aliases":[]},{"canonical":"Fairy","prior":2,"aliases":["Fairies","Pari"]},{"canonical":"Elf","prior":1,"aliases":["Elves"]},{"canonical":"Troll","prior":1,"aliases":[]},{"canonical":"Goblin","prior":1,"aliases":[]},{"canonical":"Ogre","prior":1,"aliases":[]},{"canonical":"Giant","prior":1,"aliases":[]},{"canonical":"Garuda","prior":1,"aliases":[]},{"canonical":"Naga","prior":1,"aliases":["Nagin","Naagin","Serpent king","Sheshnag","Shesha"]},{"canonical":"Genie","prior":1,"aliases":["Djinn","Jinn","Jinni"]},{"canonical":"Loch Ness Monster","prior":1,"aliases":["Nessie"]},{"canonical":"Basilisk","prior":1,"aliases":[]},{"canonical":"Rakshasa","prior":1,"aliases":["Rakshas","Rakshasi"]},{"canonical":"Vetala","prior":1,"aliases":["Betaal","Vetal","Baital"]},{"canonical":"Kamadhenu","prior":0.5,"aliases":["Wish-fulfilling cow"]},{"canonical":"Airavata","prior":0.5,"aliases":["Airavat"]},{"canonical":"Yali","prior":0.5,"aliases":["Vyala"]},{"canonical":"Makara","prior":0.5,"aliases":[]},{"canonical":"Chimera","prior":0.5,"aliases":[]},{"canonical":"Banshee","prior":0.5,"aliases":[]},{"canonical":"Leprechaun","prior":0.5,"aliases":[]},{"canonical":"Chupacabra","prior":0.5,"aliases":[]},{"canonical":"Kitsune","prior":0.3,"aliases":[]},{"canonical":"Kappa","prior":0.3,"aliases":[]},{"canonical":"Hippogriff","prior":0.5,"aliases":[]},{"canonical":"Harpy","prior":0.5,"aliases":[]},{"canonical":"Siren","prior":0.5,"aliases":[]},{"canonical":"Satyr","prior":0.3,"aliases":["Faun"]},{"canonical":"Kelpie","prior":0.3,"aliases":[]},{"canonical":"Wendigo","prior":0.3,"aliases":[]},{"canonical":"Golem","prior":0.3,"aliases":[]},{"canonical":"Thunderbird","prior":0.2,"aliases":[]},{"canonical":"Manticore","prior":0.3,"aliases":[]},{"canonical":"Cerberus","prior":0.5,"aliases":[]},{"canonical":"Selkie","prior":0.2,"aliases":[]},{"canonical":"Dwarf","prior":0.3,"aliases":["Dwarves"]},{"canonical":"Gnome","prior":0.3,"aliases":[]},{"canonical":"Zombie","prior":0.5,"aliases":[]},{"canonical":"Ghost","prior":0.5,"aliases":["Bhoot","Spirit"]},{"canonical":"Chudail","prior":0.5,"aliases":["Churel","Daayan","Dayan"]},{"canonical":"Pishacha","prior":0.2,"aliases":["Pishach"]},{"canonical":"Gandharva","prior":0.2,"aliases":[]},{"canonical":"Apsara","prior":0.2,"aliases":["Apsaras"]},{"canonical":"Kinnara","prior":0.1,"aliases":[]},{"canonical":"Sharabha","prior":0.1,"aliases":[]},{"canonical":"Navagunjara","prior":0.1,"aliases":[]},{"canonical":"Jatayu","prior":0.3,"aliases":[]},{"canonical":"Uchchaihshravas","prior":0.1,"aliases":["Seven-headed horse"]},{"canonical":"Sea serpent","prior":0.3,"aliases":[]},{"canonical":"Leviathan","prior":0.2,"aliases":[]},{"canonical":"Behemoth","prior":0.1,"aliases":[]},{"canonical":"Roc","prior":0.2,"aliases":[]},{"canonical":"Simurgh","prior":0.1,"aliases":[]},{"canonical":"Qilin","prior":0.1,"aliases":["Kirin"]},{"canonical":"Bunyip","prior":0.1,"aliases":[]},{"canonical":"Tengu","prior":0.1,"aliases":[]},{"canonical":"Wyvern","prior":0.2,"aliases":[]},{"canonical":"Cockatrice","prior":0.1,"aliases":[]},{"canonical":"Pixie","prior":0.2,"aliases":["Pixies"]},{"canonical":"Nymph","prior":0.2,"aliases":[]},{"canonical":"Fenrir","prior":0.1,"aliases":[]},{"canonical":"Sleipnir","prior":0.1,"aliases":[]},{"canonical":"Jörmungandr","prior":0.1,"aliases":["Jormungandr","Midgard Serpent"]},{"canonical":"Ammit","prior":0.05,"aliases":[]},{"canonical":"Bakunawa","prior":0.05,"aliases":[]},{"canonical":"Baku","prior":0.05,"aliases":[]},{"canonical":"Mothman","prior":0.1,"aliases":[]},{"canonical":"Jackalope","prior":0.1,"aliases":[]},{"canonical":"Hobgoblin","prior":0.1,"aliases":[]},{"canonical":"Imp","prior":0.1,"aliases":[]},{"canonical":"Pontianak","prior":0.05,"aliases":[]},{"canonical":"Nue","prior":0.02,"aliases":[]}]', NULL, 'Think of storybook castles, the deep sea, Greek legends, the Himalaya and the beasts carved on Indian temple gates.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-myth-egypt', 'Name a god or goddess of ancient Egypt.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Anubis has a jackal''s head because jackals prowled cemeteries, and Egyptians made him guardian of the dead. The pharaoh Akhenaten tried to replace all the gods with one, the sun disc Aten.', 'https://en.wikipedia.org/wiki/List_of_Egyptian_deities', 'Wikipedia: List of Egyptian deities', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0, '[{"canonical":"Ra","prior":22,"aliases":["Re","Amun-Ra","Amun Ra","Amon-Ra"]},{"canonical":"Anubis","prior":18,"aliases":["Anpu"]},{"canonical":"Osiris","prior":12,"aliases":[]},{"canonical":"Isis","prior":10,"aliases":["Aset"]},{"canonical":"Horus","prior":10,"aliases":[]},{"canonical":"Set","prior":5,"aliases":["Seth","Sutekh"]},{"canonical":"Bastet","prior":4,"aliases":["Bast"]},{"canonical":"Thoth","prior":4,"aliases":["Djehuty"]},{"canonical":"Sekhmet","prior":2,"aliases":[]},{"canonical":"Hathor","prior":2,"aliases":[]},{"canonical":"Amun","prior":2,"aliases":["Amon","Amen"]},{"canonical":"Sobek","prior":2,"aliases":[]},{"canonical":"Ptah","prior":1,"aliases":[]},{"canonical":"Nut","prior":1,"aliases":[]},{"canonical":"Geb","prior":1,"aliases":[]},{"canonical":"Aten","prior":1,"aliases":["Aton"]},{"canonical":"Atum","prior":1,"aliases":[]},{"canonical":"Ma''at","prior":1,"aliases":["Maat"]},{"canonical":"Nephthys","prior":1,"aliases":[]},{"canonical":"Khnum","prior":0.5,"aliases":[]},{"canonical":"Shu","prior":0.5,"aliases":[]},{"canonical":"Tefnut","prior":0.5,"aliases":[]},{"canonical":"Bes","prior":0.5,"aliases":[]},{"canonical":"Taweret","prior":0.5,"aliases":[]},{"canonical":"Khepri","prior":0.5,"aliases":[]},{"canonical":"Apophis","prior":0.5,"aliases":["Apep"]},{"canonical":"Mut","prior":0.3,"aliases":[]},{"canonical":"Khonsu","prior":0.3,"aliases":[]},{"canonical":"Neith","prior":0.3,"aliases":[]},{"canonical":"Hapi","prior":0.3,"aliases":[]},{"canonical":"Wadjet","prior":0.3,"aliases":[]},{"canonical":"Nekhbet","prior":0.2,"aliases":[]},{"canonical":"Serket","prior":0.2,"aliases":["Selket"]},{"canonical":"Min","prior":0.2,"aliases":[]},{"canonical":"Montu","prior":0.2,"aliases":[]},{"canonical":"Heqet","prior":0.1,"aliases":[]},{"canonical":"Anuket","prior":0.1,"aliases":[]},{"canonical":"Seshat","prior":0.1,"aliases":[]},{"canonical":"Meretseger","prior":0.05,"aliases":[]},{"canonical":"Sopdet","prior":0.1,"aliases":[]},{"canonical":"Imhotep","prior":0.3,"aliases":[]},{"canonical":"Ammit","prior":0.2,"aliases":[]},{"canonical":"Aker","prior":0.05,"aliases":[]},{"canonical":"Hu","prior":0.02,"aliases":[]},{"canonical":"Wepwawet","prior":0.05,"aliases":[]},{"canonical":"Renenutet","prior":0.02,"aliases":[]}]', NULL, 'Think of animal heads: a jackal, a falcon, a cat, a crocodile and an ibis, and the sun itself.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-myth-ramayana', 'Name a character from the Ramayana.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Valmiki''s Ramayana runs to about 24,000 verses in seven books. Thailand''s national epic, the Ramakien, tells the same story, and the Ramayana is retold across Southeast Asia from Cambodia to Indonesia.', 'https://en.wikipedia.org/wiki/Ramayana', 'Wikipedia: Ramayana', '2026-11-21', 'CC BY-SA 4.0', 'books', 1, 0, '[{"canonical":"Rama","prior":24,"aliases":["Ram","Shri Ram","Sri Rama","Raghav","Ramachandra"]},{"canonical":"Sita","prior":20,"aliases":["Seeta","Janaki","Vaidehi","Maithili"]},{"canonical":"Hanuman","prior":18,"aliases":["Bajrangbali","Maruti","Anjaneya","Pavanputra","Hanuman ji"]},{"canonical":"Ravana","prior":16,"aliases":["Raavan","Ravan","Dashanan","Lankesh"]},{"canonical":"Lakshmana","prior":14,"aliases":["Laxman","Lakshman","Lakhan"]},{"canonical":"Bharata","prior":4,"aliases":["Bharat"]},{"canonical":"Dasharatha","prior":4,"aliases":["Dashrath","Dasharath","Dasaratha"]},{"canonical":"Kaikeyi","prior":4,"aliases":[]},{"canonical":"Shatrughna","prior":3,"aliases":["Shatrughan"]},{"canonical":"Kumbhakarna","prior":3,"aliases":["Kumbhakaran"]},{"canonical":"Vibhishana","prior":3,"aliases":["Vibhishan","Bibhishan"]},{"canonical":"Sugriva","prior":3,"aliases":["Sugreev","Sugriv"]},{"canonical":"Kausalya","prior":2,"aliases":["Kaushalya"]},{"canonical":"Sumitra","prior":2,"aliases":[]},{"canonical":"Shurpanakha","prior":2,"aliases":["Surpanakha","Soorpanakha"]},{"canonical":"Meghnad","prior":2,"aliases":["Indrajit","Meghanada","Indrajeet"]},{"canonical":"Vali","prior":2,"aliases":["Bali","Baali"]},{"canonical":"Jatayu","prior":2,"aliases":[]},{"canonical":"Mandodari","prior":2,"aliases":[]},{"canonical":"Manthara","prior":2,"aliases":[]},{"canonical":"Angada","prior":1,"aliases":["Angad"]},{"canonical":"Jambavan","prior":1,"aliases":["Jambavant","Jamvant"]},{"canonical":"Valmiki","prior":1,"aliases":["Maharishi Valmiki"]},{"canonical":"Urmila","prior":1,"aliases":[]},{"canonical":"Shabari","prior":1,"aliases":["Sabari"]},{"canonical":"Luv","prior":1,"aliases":["Lava","Lav"]},{"canonical":"Kush","prior":1,"aliases":["Kusha"]},{"canonical":"Janaka","prior":1,"aliases":["Janak","Raja Janak"]},{"canonical":"Vishwamitra","prior":1,"aliases":["Vishvamitra"]},{"canonical":"Vashishtha","prior":1,"aliases":["Vasishtha","Vashisht","Vasistha"]},{"canonical":"Ahalya","prior":0.5,"aliases":["Ahilya"]},{"canonical":"Maricha","prior":0.5,"aliases":["Marich","Golden deer"]},{"canonical":"Tataka","prior":0.5,"aliases":["Tadaka","Taraka"]},{"canonical":"Sampati","prior":0.5,"aliases":[]},{"canonical":"Nala","prior":0.5,"aliases":["Nal"]},{"canonical":"Nila","prior":0.5,"aliases":["Neel"]},{"canonical":"Tara","prior":0.5,"aliases":[]},{"canonical":"Guha","prior":0.5,"aliases":["Nishadraj"]},{"canonical":"Kevat","prior":0.3,"aliases":["Kewat"]},{"canonical":"Mandavi","prior":0.3,"aliases":[]},{"canonical":"Shrutakirti","prior":0.3,"aliases":[]},{"canonical":"Agastya","prior":0.3,"aliases":[]},{"canonical":"Trijata","prior":0.3,"aliases":[]},{"canonical":"Kabandha","prior":0.2,"aliases":[]},{"canonical":"Sumantra","prior":0.2,"aliases":[]},{"canonical":"Akshayakumara","prior":0.2,"aliases":["Aksha","Akshaya Kumara"]},{"canonical":"Ahiravana","prior":0.2,"aliases":["Ahiravan","Mahiravana"]},{"canonical":"Khara","prior":0.2,"aliases":[]},{"canonical":"Dushana","prior":0.1,"aliases":[]},{"canonical":"Parashurama","prior":0.3,"aliases":["Parshuram","Parasurama"]},{"canonical":"Sunayana","prior":0.1,"aliases":[]},{"canonical":"Shanta","prior":0.1,"aliases":[]},{"canonical":"Rishyasringa","prior":0.05,"aliases":["Rishyashringa"]},{"canonical":"Ruma","prior":0.1,"aliases":[]},{"canonical":"Anjana","prior":0.2,"aliases":[]},{"canonical":"Kesari","prior":0.1,"aliases":[]},{"canonical":"Sulochana","prior":0.1,"aliases":[]},{"canonical":"Atikaya","prior":0.05,"aliases":[]},{"canonical":"Prahasta","prior":0.05,"aliases":[]},{"canonical":"Viradha","prior":0.05,"aliases":[]},{"canonical":"Sushena","prior":0.1,"aliases":[]},{"canonical":"Makardhwaja","prior":0.05,"aliases":[]},{"canonical":"Kubera","prior":0.05,"aliases":["Kuber"]}]', NULL, 'Think of the royal family of Ayodhya, the kingdom of monkeys, the court of Lanka and the sages in the forest.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-myth-dragon', 'Name a dragon from a book, film, game or show.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Smaug in ''The Hobbit'' owes a lot to the dragon in the Old English poem ''Beowulf'', which Tolkien studied and taught for years. Toothless in ''How to Train Your Dragon'' was partly modelled on a black panther.', 'https://en.wikipedia.org/wiki/List_of_dragons_in_popular_culture', 'Wikipedia: List of dragons in popular culture', '2026-11-21', 'CC BY-SA 4.0', 'books', 2, 0, '[{"canonical":"Toothless","prior":20,"aliases":["Night Fury"]},{"canonical":"Smaug","prior":16,"aliases":[]},{"canonical":"Drogon","prior":12,"aliases":[]},{"canonical":"Mushu","prior":10,"aliases":[]},{"canonical":"Charizard","prior":6,"aliases":[]},{"canonical":"Viserion","prior":3,"aliases":[]},{"canonical":"Rhaegal","prior":3,"aliases":[]},{"canonical":"Norbert","prior":2,"aliases":["Norberta"]},{"canonical":"Hungarian Horntail","prior":2,"aliases":["Horntail"]},{"canonical":"Puff the Magic Dragon","prior":2,"aliases":["Puff"]},{"canonical":"Falkor","prior":2,"aliases":["Falcor"]},{"canonical":"Spyro","prior":2,"aliases":[]},{"canonical":"Saphira","prior":2,"aliases":[]},{"canonical":"Shenron","prior":2,"aliases":["Shenlong","Shen Long"]},{"canonical":"Haku","prior":2,"aliases":[]},{"canonical":"Dragonite","prior":1,"aliases":[]},{"canonical":"Rayquaza","prior":1,"aliases":[]},{"canonical":"Elliott","prior":1,"aliases":["Pete''s Dragon"]},{"canonical":"Maleficent","prior":1,"aliases":[]},{"canonical":"Shrek''s Dragon","prior":1,"aliases":["Dragon from Shrek"]},{"canonical":"Sisu","prior":1,"aliases":[]},{"canonical":"Balerion","prior":1,"aliases":["Balerion the Black Dread"]},{"canonical":"Vhagar","prior":1,"aliases":[]},{"canonical":"Caraxes","prior":1,"aliases":[]},{"canonical":"Syrax","prior":0.5,"aliases":[]},{"canonical":"Sunfyre","prior":0.5,"aliases":[]},{"canonical":"Meleys","prior":0.3,"aliases":[]},{"canonical":"Glaurung","prior":0.3,"aliases":[]},{"canonical":"Ancalagon","prior":0.2,"aliases":["Ancalagon the Black"]},{"canonical":"Fafnir","prior":0.5,"aliases":["Fáfnir"]},{"canonical":"Alduin","prior":0.5,"aliases":[]},{"canonical":"Paarthurnax","prior":0.3,"aliases":[]},{"canonical":"Draco","prior":0.5,"aliases":[]},{"canonical":"Vermithrax","prior":0.2,"aliases":["Vermithrax Pejorative"]},{"canonical":"Kilgharrah","prior":0.3,"aliases":["Great Dragon"]},{"canonical":"Temeraire","prior":0.2,"aliases":[]},{"canonical":"Stormfly","prior":0.5,"aliases":[]},{"canonical":"Hookfang","prior":0.3,"aliases":[]},{"canonical":"Meatlug","prior":0.3,"aliases":[]},{"canonical":"Light Fury","prior":0.3,"aliases":[]},{"canonical":"Cloudjumper","prior":0.2,"aliases":[]},{"canonical":"Deathwing","prior":0.3,"aliases":[]},{"canonical":"Sindragosa","prior":0.1,"aliases":[]},{"canonical":"Ridley","prior":0.1,"aliases":[]},{"canonical":"Gyarados","prior":0.3,"aliases":[]},{"canonical":"Salamence","prior":0.2,"aliases":[]},{"canonical":"Garchomp","prior":0.2,"aliases":[]},{"canonical":"Dialga","prior":0.1,"aliases":[]},{"canonical":"Reshiram","prior":0.1,"aliases":[]},{"canonical":"Zekrom","prior":0.1,"aliases":[]},{"canonical":"Bahamut","prior":0.3,"aliases":[]},{"canonical":"Tiamat","prior":0.2,"aliases":[]},{"canonical":"Jabberwock","prior":0.2,"aliases":["Jabberwocky"]},{"canonical":"Eustace","prior":0.1,"aliases":["Eustace Scrubb"]},{"canonical":"Ladon","prior":0.05,"aliases":[]},{"canonical":"Kalessin","prior":0.05,"aliases":[]},{"canonical":"Orm Embar","prior":0.02,"aliases":[]},{"canonical":"Mnementh","prior":0.02,"aliases":[]},{"canonical":"Glaedr","prior":0.1,"aliases":[]},{"canonical":"Thorn","prior":0.05,"aliases":[]},{"canonical":"Shruikan","prior":0.05,"aliases":[]},{"canonical":"Firnen","prior":0.02,"aliases":[]},{"canonical":"Spike","prior":0.3,"aliases":[]},{"canonical":"Igneel","prior":0.2,"aliases":[]},{"canonical":"Tohru","prior":0.1,"aliases":[]},{"canonical":"Ghidorah","prior":0.1,"aliases":["King Ghidorah"]},{"canonical":"Grisu","prior":0.05,"aliases":[]},{"canonical":"Boris","prior":0.02,"aliases":["Elmer''s dragon"]},{"canonical":"Zog","prior":0.1,"aliases":[]}]', NULL, 'Think of Middle-earth, Westeros, a Disney film set in China, the island of Berk and a fiery Pokémon.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-myth-greekhero', 'Name a hero from Greek myth.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Achilles'' mother dipped him in the River Styx to make him invulnerable, but the heel she held stayed dry. Heracles is the Greek name; the Romans called him Hercules.', 'https://en.wikipedia.org/wiki/Greek_mythology', 'Wikipedia: Greek mythology', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Hercules","prior":24,"aliases":["Heracles","Herakles"]},{"canonical":"Achilles","prior":18,"aliases":[]},{"canonical":"Perseus","prior":12,"aliases":[]},{"canonical":"Odysseus","prior":10,"aliases":["Ulysses"]},{"canonical":"Theseus","prior":8,"aliases":[]},{"canonical":"Jason","prior":6,"aliases":[]},{"canonical":"Hector","prior":3,"aliases":[]},{"canonical":"Ajax","prior":2,"aliases":["Aias"]},{"canonical":"Orpheus","prior":2,"aliases":[]},{"canonical":"Bellerophon","prior":2,"aliases":[]},{"canonical":"Atalanta","prior":1,"aliases":[]},{"canonical":"Patroclus","prior":1,"aliases":[]},{"canonical":"Aeneas","prior":1,"aliases":[]},{"canonical":"Agamemnon","prior":1,"aliases":[]},{"canonical":"Paris","prior":1,"aliases":[]},{"canonical":"Menelaus","prior":0.5,"aliases":[]},{"canonical":"Diomedes","prior":0.5,"aliases":[]},{"canonical":"Castor","prior":0.5,"aliases":[]},{"canonical":"Pollux","prior":0.5,"aliases":["Polydeuces"]},{"canonical":"Meleager","prior":0.3,"aliases":[]},{"canonical":"Oedipus","prior":0.5,"aliases":[]},{"canonical":"Cadmus","prior":0.3,"aliases":[]},{"canonical":"Peleus","prior":0.3,"aliases":[]},{"canonical":"Telemachus","prior":0.3,"aliases":[]},{"canonical":"Nestor","prior":0.3,"aliases":[]},{"canonical":"Philoctetes","prior":0.3,"aliases":[]},{"canonical":"Hippolyta","prior":0.3,"aliases":[]},{"canonical":"Penthesilea","prior":0.1,"aliases":[]},{"canonical":"Iolaus","prior":0.1,"aliases":[]},{"canonical":"Icarus","prior":0.5,"aliases":[]},{"canonical":"Daedalus","prior":0.3,"aliases":[]},{"canonical":"Ariadne","prior":0.3,"aliases":[]},{"canonical":"Penelope","prior":0.3,"aliases":[]},{"canonical":"Helen","prior":0.2,"aliases":["Helen of Troy"]},{"canonical":"Asclepius","prior":0.1,"aliases":[]},{"canonical":"Pelops","prior":0.1,"aliases":[]},{"canonical":"Laertes","prior":0.05,"aliases":[]},{"canonical":"Neoptolemus","prior":0.05,"aliases":["Pyrrhus"]},{"canonical":"Amphiaraus","prior":0.02,"aliases":[]},{"canonical":"Tydeus","prior":0.02,"aliases":[]},{"canonical":"Calais","prior":0.02,"aliases":[]},{"canonical":"Zetes","prior":0.02,"aliases":[]},{"canonical":"Medea","prior":0.2,"aliases":[]},{"canonical":"Antigone","prior":0.1,"aliases":[]},{"canonical":"Electra","prior":0.05,"aliases":[]},{"canonical":"Orestes","prior":0.05,"aliases":[]}]', NULL, 'Think of the Trojan War, the twelve labours, the Golden Fleece, the Minotaur''s maze and the slayer of Medusa.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-myth-fairy', 'Name a fairy tale.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Brothers Grimm published their first collection of fairy tales in 1812, and their versions are far darker than the films. Hans Christian Andersen wrote ''The Little Mermaid'' and ''The Ugly Duckling''.', 'https://en.wikipedia.org/wiki/Fairy_tale', 'Wikipedia: Fairy tale', '2026-11-21', 'CC BY-SA 4.0', 'books', 1, 0, '[{"canonical":"Cinderella","prior":22,"aliases":[]},{"canonical":"Snow White","prior":16,"aliases":["Snow White and the Seven Dwarfs"]},{"canonical":"Little Red Riding Hood","prior":12,"aliases":["Red Riding Hood"]},{"canonical":"Sleeping Beauty","prior":10,"aliases":["Briar Rose"]},{"canonical":"Hansel and Gretel","prior":8,"aliases":["Hansel & Gretel"]},{"canonical":"Rapunzel","prior":8,"aliases":[]},{"canonical":"Jack and the Beanstalk","prior":6,"aliases":[]},{"canonical":"Beauty and the Beast","prior":6,"aliases":[]},{"canonical":"The Little Mermaid","prior":4,"aliases":["Little Mermaid"]},{"canonical":"Goldilocks and the Three Bears","prior":4,"aliases":["Goldilocks"]},{"canonical":"The Three Little Pigs","prior":4,"aliases":["Three Little Pigs"]},{"canonical":"Rumpelstiltskin","prior":3,"aliases":[]},{"canonical":"The Frog Prince","prior":3,"aliases":["Frog Prince"]},{"canonical":"Puss in Boots","prior":2,"aliases":[]},{"canonical":"The Ugly Duckling","prior":2,"aliases":["Ugly Duckling"]},{"canonical":"Aladdin","prior":2,"aliases":["Aladdin and the Magic Lamp"]},{"canonical":"Pinocchio","prior":2,"aliases":[]},{"canonical":"The Emperor''s New Clothes","prior":1,"aliases":["Emperor''s New Clothes"]},{"canonical":"Thumbelina","prior":1,"aliases":[]},{"canonical":"The Princess and the Pea","prior":1,"aliases":["Princess and the Pea"]},{"canonical":"The Snow Queen","prior":1,"aliases":["Snow Queen"]},{"canonical":"Ali Baba and the Forty Thieves","prior":1,"aliases":["Ali Baba","Alibaba"]},{"canonical":"Sinbad the Sailor","prior":1,"aliases":["Sinbad"]},{"canonical":"The Gingerbread Man","prior":1,"aliases":["Gingerbread Man"]},{"canonical":"Tom Thumb","prior":0.5,"aliases":[]},{"canonical":"The Elves and the Shoemaker","prior":0.5,"aliases":["Elves and the Shoemaker"]},{"canonical":"The Pied Piper of Hamelin","prior":0.5,"aliases":["Pied Piper"]},{"canonical":"Bluebeard","prior":0.3,"aliases":[]},{"canonical":"The Little Match Girl","prior":0.5,"aliases":["Little Match Girl"]},{"canonical":"The Steadfast Tin Soldier","prior":0.3,"aliases":["Tin Soldier"]},{"canonical":"The Golden Goose","prior":0.3,"aliases":["Golden Goose"]},{"canonical":"The Goose That Laid the Golden Eggs","prior":0.3,"aliases":["Golden eggs"]},{"canonical":"The Boy Who Cried Wolf","prior":0.3,"aliases":[]},{"canonical":"The Twelve Dancing Princesses","prior":0.2,"aliases":["Twelve Dancing Princesses"]},{"canonical":"The Bremen Town Musicians","prior":0.2,"aliases":["Bremen Town Musicians"]},{"canonical":"Snow-White and Rose-Red","prior":0.1,"aliases":["Snow White and Rose Red"]},{"canonical":"The Wild Swans","prior":0.1,"aliases":[]},{"canonical":"The Nightingale","prior":0.2,"aliases":[]},{"canonical":"The Red Shoes","prior":0.1,"aliases":[]},{"canonical":"The Brave Little Tailor","prior":0.2,"aliases":["Brave Little Tailor"]},{"canonical":"The Fisherman and His Wife","prior":0.1,"aliases":[]},{"canonical":"The Six Swans","prior":0.05,"aliases":[]},{"canonical":"East of the Sun and West of the Moon","prior":0.05,"aliases":[]},{"canonical":"Vasilisa the Beautiful","prior":0.05,"aliases":[]},{"canonical":"Baba Yaga","prior":0.1,"aliases":[]},{"canonical":"The Firebird","prior":0.1,"aliases":["Firebird"]},{"canonical":"The Tortoise and the Hare","prior":0.5,"aliases":["Hare and the Tortoise"]},{"canonical":"The Thirsty Crow","prior":0.5,"aliases":["Thirsty Crow"]},{"canonical":"The Fox and the Grapes","prior":0.3,"aliases":["Sour grapes"]},{"canonical":"Vikram and Betaal","prior":0.5,"aliases":["Vikram Betaal","Vikram aur Betaal","Baital Pachisi"]},{"canonical":"Panchatantra","prior":0.5,"aliases":["The Monkey and the Crocodile","Monkey and the Crocodile"]},{"canonical":"Akbar and Birbal","prior":0.5,"aliases":["Akbar Birbal","Birbal"]},{"canonical":"Tenali Raman","prior":0.3,"aliases":["Tenali Rama"]},{"canonical":"Jataka tales","prior":0.2,"aliases":["Jataka"]},{"canonical":"Thakurmar Jhuli","prior":0.1,"aliases":[]},{"canonical":"Lalkamal Neelkamal","prior":0.02,"aliases":[]},{"canonical":"Hitopadesha","prior":0.1,"aliases":[]},{"canonical":"The Lion and the Mouse","prior":0.3,"aliases":["Lion and the Mouse"]},{"canonical":"The Magic Porridge Pot","prior":0.05,"aliases":[]},{"canonical":"The Enormous Turnip","prior":0.05,"aliases":[]},{"canonical":"Chicken Licken","prior":0.05,"aliases":["Henny Penny","Chicken Little"]},{"canonical":"The Little Red Hen","prior":0.1,"aliases":[]},{"canonical":"Billy Goats Gruff","prior":0.1,"aliases":["Three Billy Goats Gruff"]},{"canonical":"Momotaro","prior":0.05,"aliases":[]},{"canonical":"Urashima Taro","prior":0.02,"aliases":[]},{"canonical":"Kaguya-hime","prior":0.02,"aliases":["The Tale of the Bamboo Cutter"]}]', NULL, 'Think of the Brothers Grimm, Hans Christian Andersen, a thousand and one nights and the stories told at bedtime.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-myth-weapon', 'Name a weapon from Indian mythology.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'In the epics the Brahmastra, a weapon of Brahma, can stop any ordinary weapon. Vishnu''s Sudarshana Chakra is usually shown as a spinning disc with serrated edges.', 'https://en.wikipedia.org/wiki/Astra_(weapon)', 'Wikipedia: Astra (weapon)', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0, '[{"canonical":"Trishul","prior":20,"aliases":["Trishula","Trident"]},{"canonical":"Sudarshana Chakra","prior":18,"aliases":["Sudarshan Chakra","Chakra","Sudarshan","Discus"]},{"canonical":"Brahmastra","prior":12,"aliases":["Brahmaastra","Brahma astra"]},{"canonical":"Gada","prior":10,"aliases":["Mace","Hanuman''s gada","Kaumodaki"]},{"canonical":"Vajra","prior":6,"aliases":["Thunderbolt","Vajrayudha"]},{"canonical":"Gandiva","prior":6,"aliases":["Gandiv","Gandeev"]},{"canonical":"Pashupatastra","prior":3,"aliases":["Pashupat astra","Pashupata"]},{"canonical":"Bow and arrow","prior":3,"aliases":["Dhanush","Bow","Arrow","Dhanush baan"]},{"canonical":"Pinaka","prior":2,"aliases":["Pinak","Shiva''s bow"]},{"canonical":"Narayanastra","prior":2,"aliases":["Narayan astra"]},{"canonical":"Agneyastra","prior":2,"aliases":["Agneya astra","Fire weapon"]},{"canonical":"Varunastra","prior":1,"aliases":["Varuna astra"]},{"canonical":"Vasavi Shakti","prior":1,"aliases":["Shakti","Vasavi"]},{"canonical":"Parashu","prior":1,"aliases":["Axe","Parashurama''s axe","Pharsa"]},{"canonical":"Sharanga","prior":1,"aliases":["Sarnga","Shaarnga"]},{"canonical":"Kodanda","prior":1,"aliases":["Kodandam","Rama''s bow"]},{"canonical":"Vel","prior":1,"aliases":["Spear","Murugan''s spear"]},{"canonical":"Nandaka","prior":0.5,"aliases":["Nandaki","Vishnu''s sword"]},{"canonical":"Chandrahas","prior":0.5,"aliases":["Chandrahasa","Ravana''s sword"]},{"canonical":"Vijaya","prior":0.5,"aliases":["Vijaya bow","Karna''s bow"]},{"canonical":"Pasha","prior":0.5,"aliases":["Noose","Paash"]},{"canonical":"Ankusha","prior":0.3,"aliases":["Ankush","Goad","Elephant goad"]},{"canonical":"Nagastra","prior":0.5,"aliases":["Naga astra","Nagpash","Naga pasha"]},{"canonical":"Vayavastra","prior":0.3,"aliases":["Vayu astra"]},{"canonical":"Sammohana astra","prior":0.1,"aliases":["Sammohanastra"]},{"canonical":"Brahmashirsha astra","prior":0.3,"aliases":["Brahmashira","Brahmashirsha"]},{"canonical":"Indrastra","prior":0.2,"aliases":["Indra astra"]},{"canonical":"Danda","prior":0.2,"aliases":["Yama''s staff","Kaladanda"]},{"canonical":"Khatvanga","prior":0.1,"aliases":[]},{"canonical":"Suryastra","prior":0.1,"aliases":[]},{"canonical":"Garudastra","prior":0.1,"aliases":[]},{"canonical":"Parvatastra","prior":0.05,"aliases":[]}]', NULL, 'Think of what Shiva, Vishnu and Indra carry, Arjuna''s favourite weapon and the astras of the Kurukshetra war.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-wear-clothing', 'Name an item of clothing.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The saree is one of the oldest garments still worn: a single unstitched length of five to nine yards. Blue jeans were patented in 1873 by Levi Strauss and Jacob Davis, who added copper rivets to work trousers.', 'https://en.wikipedia.org/wiki/Clothing', 'Wikipedia: Clothing', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Shirt","prior":18,"aliases":["Shirts","Formal shirt"]},{"canonical":"T-shirt","prior":16,"aliases":["Tshirt","Tee","T shirt","Tee shirt"]},{"canonical":"Jeans","prior":14,"aliases":["Denims"]},{"canonical":"Trousers","prior":8,"aliases":["Pants","Pant","Slacks","Chinos"]},{"canonical":"Saree","prior":8,"aliases":["Sari"]},{"canonical":"Kurta","prior":6,"aliases":["Kurtas"]},{"canonical":"Dress","prior":6,"aliases":["Frock"]},{"canonical":"Skirt","prior":4,"aliases":[]},{"canonical":"Jacket","prior":4,"aliases":["Bomber jacket","Leather jacket","Denim jacket"]},{"canonical":"Sweater","prior":4,"aliases":["Jumper","Pullover","Sweatshirt"]},{"canonical":"Socks","prior":4,"aliases":["Sock"]},{"canonical":"Shorts","prior":3,"aliases":["Half pants","Half pant","Bermudas","Bermuda shorts"]},{"canonical":"Hoodie","prior":3,"aliases":["Hoody"]},{"canonical":"Coat","prior":2,"aliases":["Overcoat","Trench coat"]},{"canonical":"Salwar kameez","prior":2,"aliases":["Salwar","Salwar suit","Suit","Churidar","Kameez"]},{"canonical":"Lehenga","prior":2,"aliases":["Lehnga","Ghagra","Ghagra choli","Chaniya choli"]},{"canonical":"Dupatta","prior":2,"aliases":["Chunni","Odhni","Stole"]},{"canonical":"Blouse","prior":2,"aliases":[]},{"canonical":"Vest","prior":2,"aliases":["Baniyan","Banian","Undershirt","Tank top","Singlet"]},{"canonical":"Underwear","prior":2,"aliases":["Briefs","Boxers","Knickers","Panties","Underpants","Innerwear"]},{"canonical":"Pyjamas","prior":2,"aliases":["Pajamas","PJs","Nightsuit","Night suit","Pyjama","Pajama"]},{"canonical":"Nightie","prior":1,"aliases":["Nightgown","Nightdress","Night dress","Gown"]},{"canonical":"Sherwani","prior":1,"aliases":[]},{"canonical":"Dhoti","prior":1,"aliases":["Panche","Veshti","Mundu","Lungi"]},{"canonical":"Scarf","prior":1,"aliases":["Muffler","Stole scarf"]},{"canonical":"Tie","prior":1,"aliases":["Necktie","Bow tie","Bowtie"]},{"canonical":"Blazer","prior":1,"aliases":[]},{"canonical":"Suit and tie","prior":1,"aliases":["Three-piece suit","Business suit","Tuxedo"]},{"canonical":"Leggings","prior":1,"aliases":["Jeggings","Tights"]},{"canonical":"Cardigan","prior":1,"aliases":[]},{"canonical":"Top","prior":1,"aliases":["Crop top","Tops"]},{"canonical":"Kurti","prior":1,"aliases":[]},{"canonical":"Tracksuit","prior":1,"aliases":["Track pants","Joggers","Tracks","Sweatpants","Lower"]},{"canonical":"Raincoat","prior":1,"aliases":["Rain jacket","Windcheater"]},{"canonical":"Swimsuit","prior":1,"aliases":["Swimming costume","Bikini","Swimwear","Trunks","Swimming trunks"]},{"canonical":"Bra","prior":1,"aliases":["Brassiere","Sports bra"]},{"canonical":"Gloves","prior":0.5,"aliases":["Glove","Mittens"]},{"canonical":"Cap","prior":0.5,"aliases":["Hat","Beanie"]},{"canonical":"Dungarees","prior":0.5,"aliases":["Overalls"]},{"canonical":"Jumpsuit","prior":0.5,"aliases":["Playsuit","Romper","Onesie"]},{"canonical":"Waistcoat","prior":0.5,"aliases":["Nehru jacket","Modi jacket","Bandi"]},{"canonical":"Polo shirt","prior":0.5,"aliases":["Polo","Collar T-shirt"]},{"canonical":"Shawl","prior":0.5,"aliases":["Pashmina","Shawls"]},{"canonical":"Petticoat","prior":0.5,"aliases":["Underskirt"]},{"canonical":"Kimono","prior":0.3,"aliases":[]},{"canonical":"Cape","prior":0.3,"aliases":["Cloak","Poncho"]},{"canonical":"Palazzo","prior":0.3,"aliases":["Palazzos","Palazzo pa