INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-wear-shoe', 'Name a kind of shoe.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Kolhapuri chappals, handmade leather sandals from Maharashtra and Karnataka, got a geographical indication tag in 2019. In Indian English, ballet flats often go by ''bellies''.', 'https://en.wikipedia.org/wiki/List_of_shoe_styles', 'Wikipedia: List of shoe styles', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Sneakers","prior":18,"aliases":["Sneaker","Trainers","Sports shoes","Running shoes","Canvas shoes","Keds","Tennis shoes"]},{"canonical":"Sandals","prior":14,"aliases":["Sandal","Floaters"]},{"canonical":"Slippers","prior":12,"aliases":["Slipper","Chappals","Chappal","Hawai chappal","Bathroom slippers","House slippers"]},{"canonical":"Boots","prior":10,"aliases":["Boot"]},{"canonical":"Heels","prior":8,"aliases":["High heels","Stilettos","Stiletto","Pumps","Kitten heels"]},{"canonical":"Flip-flops","prior":6,"aliases":["Flip flops","Thongs","Hawaii chappals"]},{"canonical":"Loafers","prior":4,"aliases":["Loafer","Slip-ons","Slip ons","Moccasins","Mocassins"]},{"canonical":"Ballet flats","prior":3,"aliases":["Bellies","Flats","Ballerinas","Ballerina flats"]},{"canonical":"Crocs","prior":3,"aliases":["Clogs","Croc"]},{"canonical":"Kolhapuri chappals","prior":3,"aliases":["Kolhapuri","Kolhapuris","Kolhapuri chappal"]},{"canonical":"Juttis","prior":3,"aliases":["Jutti","Mojari","Mojaris","Nagra","Khussa"]},{"canonical":"Oxfords","prior":2,"aliases":["Oxford","Oxford shoes"]},{"canonical":"Brogues","prior":2,"aliases":["Brogue","Wingtips"]},{"canonical":"Formal shoes","prior":2,"aliases":["Leather shoes","Office shoes","Dress shoes"]},{"canonical":"Gumboots","prior":2,"aliases":["Rain boots","Wellingtons","Wellies","Rubber boots"]},{"canonical":"Wedges",