INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-wear-indian', 'Name a traditional Indian outfit.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Assam''s mekhela chador is often woven from muga, a golden silk produced almost nowhere but Assam. A Kanchipuram silk saree can take weeks to weave by hand.', 'https://en.wikipedia.org/wiki/Clothing_in_India', 'Wikipedia: Clothing in India', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Saree","prior":24,"aliases":["Sari","Saris","Sarees"]},{"canonical":"Salwar kameez","prior":14,"aliases":["Salwar suit","Punjabi suit","Suit","Salwar","Shalwar kameez","Patiala suit","Patiala salwar"]},{"canonical":"Kurta pyjama","prior":12,"aliases":["Kurta","Kurta pajama","Kurta-pyjama"]},{"canonical":"Lehenga choli","prior":10,"aliases":["Lehenga","Ghagra choli","Chaniya choli","Lehnga","Ghagra"]},{"canonical":"Sherwani","prior":8,"aliases":[]},{"canonical":"Dhoti","prior":6,"aliases":["Dhoti kurta","Panche","Pancha","Dhuti"]},{"canonical":"Lungi","prior":4,"aliases":["Mundu","Veshti","Vesti","Kaili"]},{"canonical":"Churidar","prior":3,"aliases":["Churidar kurta","Churidaar"]},{"canonical":"Anarkali","prior":3,"aliases":["Anarkali suit"]},{"canonical":"Kurti","prior":2,"aliases":[]},{"canonical":"Nehru jacket","prior":2,"aliases":["Modi jacket","Bandi","Bundi"]},{"canonical":"Bandhgala","prior":2,"aliases":["Jodhpuri suit","Jodhpuri","Bandhgala suit"]},{"canonical":"Achkan","prior":1,"aliases":[]},{"canonical":"Mekhela chador","prior":2,"aliases":["Mekhela sador","Mekhela"]},{"canonical":"Pheran","prior":2,"aliases":["Phiran","Feran"]},{"canonical":"Mundum neriyathum","prior":1,"aliases":["Set mundu","Kerala saree","Kasavu saree","Kasavu"]},{"canonical":"Pattu pavadai","prior":1,"aliases":["Langa voni","Half saree","Pavadai","Langa davani","Pattu langa"]},{"canonical":"Nauvari","prior":1,"aliases":["Nauvari saree","Kashta saree","Navvari"]},{"canonical":"Angrakha","prior":0.5,"aliases":[]},{"canonical":"Pathani suit","prior":0.5,"aliases":["Pathani","Pathani kurta"]},{"canonical":"Dupatta","prior":0.5,"aliases":["Chunri","Chunni","Odhni"]},{"canonical":"Pagdi","prior":0.5,"aliases":["Turban","Safa","Pagri"]},{"canonical":"Phanek","prior":0.5,"aliases":["Phanek and innaphi"]},{"canonical":"Puan","prior":0.2,"aliases":["Puanchei"]},{"canonical":"Rignai","prior":0.1,"aliases":[]},{"canonical":"Gamosa","prior":0.3,"aliases":["Gamusa","Gamcha"]},{"canonical":"Jama","prior":0.2,"aliases":[]},{"canonical":"Bandhani","prior":0.3,"aliases":["Bandhej"]},{"canonical":"Ghoonghat","prior":0.1,"aliases":[]},{"canonical":"Kediyu","prior":0.2,"aliases":["Kedia"]},{"canonical":"Shawl","prior":0.3,"aliases":["Pashmina","Kullu shawl"]},{"canonical":"Choga","prior":0.1,"aliases":[]},{"canonical":"Sadri","prior":0.1,"aliases":[]},{"canonical":"Kanchipuram saree","prior":0.5,"aliases":["Kanjeevaram","Kanjivaram","Kanchipuram"]},{"canonical":"Banarasi saree","prior":0.5,"aliases":["Banarasi"]},{"canonical":"Paithani","prior":0.3,"aliases":["Paithani saree"]},{"canonical":"Patola","prior":0.2,"aliases":["Patola saree"]},{"canonical":"Chikankari kurta","prior":0.2,"aliases":["Chikankari","Lucknowi"]},{"canonical":"Sharara","prior":0.5,"aliases":["Gharara"]}]', NULL, 'Think of a wedding in Punjab, a temple in Kerala, a Bihu dance in Assam and a winter in Kashmir.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-wear-fabric', 'Name a fabric.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Several English fabric words came from India: calico from Calicut (Kozhikode), chintz from the Hindi ''chheent'', and dungaree from Dongri in Mumbai. Khadi, hand-spun and hand-woven, became a symbol of the freedom movement.', 'https://en.wikipedia.org/wiki/List_of_fabrics', 'Wikipedia: List of fabrics', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Cotton","prior":24,"aliases":["Kapas","Sooti","Suti"]},{"canonical":"Silk","prior":18,"aliases":["Resham","Pure silk"]},{"canonical":"Wool","prior":10,"aliases":["Woollen","Woolen","Ooni"]},{"canonical":"Denim","prior":8,"aliases":[]},{"canonical":"Polyester","prior":6,"aliases":["Poly"]},{"canonical":"Linen","prior":6,"aliases":[]},{"canonical":"Khadi","prior":6,"aliases":["Khaddar"]},{"canonical":"Nylon","prior":4,"aliases":[]},{"canonical":"Velvet","prior":4,"aliases":["Makhmal"]},{"canonical":"Satin","prior":3,"aliases":[]},{"canonical":"Chiffon","prior":3,"aliases":[]},{"canonical":"Georgette","prior":3,"aliases":[]},{"canonical":"Rayon","prior":2,"aliases":["Viscose"]},{"canonical":"Leather","prior":2,"aliases":[]},{"canonical":"Lycra","prior":2,"aliases":["Spandex","Elastane"]},{"canonical":"Fleece","prior":2,"aliases":["Polar fleece"]},{"canonical":"Jute","prior":1,"aliases":[]},{"canonical":"Muslin","prior":1,"aliases":["Malmal","Mulmul"]},{"canonical":"Cashmere","prior":1,"aliases":["Pashmina"]},{"canonical":"Corduroy","prior":1,"aliases":["Cord"]},{"canonical":"Tweed","prior":1,"aliases":[]},{"canonical":"Lace","prior":1,"aliases":[]},{"canonical":"Net","prior":1,"aliases":["Netting","Mesh"]},{"canonical":"Organza","prior":1,"aliases":[]},{"canonical":"Crepe","prior":1,"aliases":[]},{"canonical":"Chanderi","prior":1,"aliases":[]},{"canonical":"Tussar","prior":1,"aliases":["Tussar silk","Tussore","Kosa"]},{"canonical":"Muga","prior":0.5,"aliases":["Muga silk"]},{"canonical":"Flannel","prior":0.5,"aliases":[]},{"canonical":"Calico","prior":0.5,"aliases":[]},{"canonical":"Chintz","prior":0.5,"aliases":[]},{"canonical":"Gingham","prior":0.5,"aliases":[]},{"canonical":"Poplin","prior":0.5,"aliases":[]},{"canonical":"Twill","prior":0.5,"aliases":[]},{"canonical":"Canvas","prior":0.5,"aliases":[]},{"canonical":"Suede","prior":0.5,"aliases":[]},{"canonical":"Tulle","prior":0.5,"aliases":[]},{"canonical":"Jersey","prior":0.5,"aliases":[]},{"canonical":"Felt","prior":0.5,"aliases":[]},{"canonical":"Terry cloth","prior":0.3,"aliases":["Towelling","Terrycloth","Terry"]},{"canonical":"Brocade","prior":0.5,"aliases":["Kinkhab","Zari brocade"]},{"canonical":"Taffeta","prior":0.3,"aliases":[]},{"canonical":"Hemp","prior":0.3,"aliases":[]},{"canonical":"Bamboo fabric","prior":0.2,"aliases":["Bamboo"]},{"canonical":"Modal","prior":0.2,"aliases":[]},{"canonical":"Microfibre","prior":0.2,"aliases":["Microfiber"]},{"canonical":"Chambray","prior":0.2,"aliases":[]},{"canonical":"Seersucker","prior":0.2,"aliases":[]},{"canonical":"Damask","prior":0.2,"aliases":[]},{"canonical":"Voile","prior":0.2,"aliases":[]},{"canonical":"Ikat","prior":0.3,"aliases":["Pochampally","Pochampally ikat"]},{"canonical":"Eri silk","prior":0.2,"aliases":["Eri","Ahimsa silk","Peace silk"]},{"canonical":"Merino","prior":0.2,"aliases":["Merino wool"]},{"canonical":"Mohair","prior":0.2,"aliases":[]},{"canonical":"Angora","prior":0.2,"aliases":[]},{"canonical":"Alpaca","prior":0.1,"aliases":[]},{"canonical":"Acrylic","prior":0.3,"aliases":[]},{"canonical":"Khes","prior":0.05,"aliases":[]},{"canonical":"Cambric","prior":0.1,"aliases":[]},{"canonical":"Lawn","prior":0.2,"aliases":["Lawn cotton"]},{"canonical":"Oxford cloth","prior":0.1,"aliases":[]},{"canonical":"Gabardine","prior":0.2,"aliases":[]},{"canonical":"Worsted","prior":0.1,"aliases":[]},{"canonical":"Faux fur","prior":0.1,"aliases":["Fur"]},{"canonical":"Sateen","prior":0.1,"aliases":[]},{"canonical":"Batiste","prior":0.05,"aliases":[]},{"canonical":"Charmeuse","prior":0.05,"aliases":[]},{"canonical":"Dupion","prior":0.1,"aliases":["Dupioni","Raw silk"]},{"canonical":"Chenille","prior":0.1,"aliases":[]},{"canonical":"Gauze","prior":0.1,"aliases":[]},{"canonical":"Oilcloth","prior":0.05,"aliases":[]},{"canonical":"Gore-Tex","prior":0.1,"aliases":[]},{"canonical":"Neoprene","prior":0.1,"aliases":[]},{"canonical":"Kevlar","prior":0.05,"aliases":[]},{"canonical":"Tencel","prior":0.05,"aliases":["Lyocell"]},{"canonical":"Madras","prior":0.2,"aliases":["Madras check"]},{"canonical":"Dhakai","prior":0.1,"aliases":["Jamdani"]},{"canonical":"Kanchipuram silk","prior":0.3,"aliases":["Kanjeevaram silk","Kanjivaram"]},{"canonical":"Banarasi silk","prior":0.3,"aliases":["Banarasi"]},{"canonical":"Mysore silk","prior":0.2,"aliases":[]},{"canonical":"Kota doria","prior":0.1,"aliases":["Kota"]},{"canonical":"Matka silk","prior":0.05,"aliases":[]}]', NULL, 'Think of what Gandhi spun, what a wedding saree is woven from, what your denims are made of and what''s warm in winter.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-wear-jewel', 'Name a piece of jewellery.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'A traditional Indian bride may wear jewellery from head to toe: maang tikka, nath, mangalsutra, bangles, kamarbandh, payal and toe rings. India and China are the world''s two biggest buyers of gold jewellery.', 'https://en.wikipedia.org/wiki/Jewellery', 'Wikipedia: Jewellery', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Ring","prior":20,"aliases":["Rings","Angoothi","Finger ring","Engagement ring","Wedding ring"]},{"canonical":"Necklace","prior":18,"aliases":["Haar","Neckpiece","Rani haar"]},{"canonical":"Earrings","prior":14,"aliases":["Earring","Jhumka","Jhumkas","Studs","Hoops","Bali","Tops"]},{"canonical":"Bracelet","prior":10,"aliases":["Bracelets","Charm bracelet"]},{"canonical":"Bangles","prior":10,"aliases":["Bangle","Choodi","Chudi","Chudiyan","Kangan","Kada","Kara","Chooda"]},{"canonical":"Chain","prior":6,"aliases":["Gold chain","Neck chain"]},{"canonical":"Anklet","prior":6,"aliases":["Anklets","Payal","Pajeb","Paayal","Ankle chain","Kolusu"]},{"canonical":"Nose ring","prior":6,"aliases":["Nath","Nose pin","Nose stud","Nathni","Laung","Mookuthi"]},{"canonical":"Maang tikka","prior":4,"aliases":["Tikka","Mang tikka","Maangtikka","Borla","Matha patti","Mathapatti"]},{"canonical":"Mangalsutra","prior":4,"aliases":["Thali","Taali","Mangal sutra"]},{"canonical":"Pendant","prior":4,"aliases":["Locket"]},{"canonical":"Toe ring","prior":3,"aliases":["Toe rings","Bichiya","Bichhiya","Metti","Mettelu"]},{"canonical":"Brooch","prior":2,"aliases":["Broach","Pin"]},{"canonical":"Kamarbandh","prior":2,"aliases":["Waist chain","Kamarband","Oddiyanam","Vaddanam","Waistband","Belly chain","Kardhani"]},{"canonical":"Choker","prior":2,"aliases":["Choker necklace"]},{"canonical":"Armlet","prior":1,"aliases":["Bajuband","Baju band","Vanki","Arm band"]},{"canonical":"Haath phool","prior":1,"aliases":["Hathphool","Hand harness","Haathphool"]},{"canonical":"Cufflinks","prior":1,"aliases":["Cufflink"]},{"canonical":"Tiara","prior":1,"aliases":["Diadem"]},{"canonical":"Crown","prior":1,"aliases":["Mukut"]},{"canonical":"Watch","prior":1,"aliases":["Wristwatch"]},{"canonical":"Ear cuff","prior":0.5,"aliases":["Ear chain","Kaan chain","Sahara"]},{"canonical":"Passa","prior":0.3,"aliases":["Jhoomar"]},{"canonical":"Kaleere","prior":0.5,"aliases":["Kalire","Kaleera"]},{"canonical":"Navel ring","prior":0.3,"aliases":["Belly button ring","Belly ring"]},{"canonical":"Tie pin","prior":0.3,"aliases":["Tie clip","Tie bar"]},{"canonical":"Hair pin","prior":0.3,"aliases":["Hairpin","Hair clip","Juda pin","Hair accessory"]},{"canonical":"Circlet","prior":0.1,"aliases":[]},{"canonical":"Kundan","prior":0.3,"aliases":["Kundan set","Polki"]},{"canonical":"Temple jewellery","prior":0.2,"aliases":["Temple jewelry"]},{"canonical":"Rosary","prior":0.1,"aliases":["Mala","Rudraksha","Rudraksha mala"]},{"canonical":"Amulet","prior":0.2,"aliases":["Taveez","Taweez","Talisman"]},{"canonical":"Charm","prior":0.2,"aliases":[]},{"canonical":"Signet ring","prior":0.1,"aliases":[]},{"canonical":"Nose chain","prior":0.1,"aliases":[]},{"canonical":"Lip ring","prior":0.05,"aliases":[]},{"canonical":"Eyebrow ring","prior":0.05,"aliases":[]},{"canonical":"Body chain","prior":0.05,"aliases":[]},{"canonical":"Grills","prior":0.02,"aliases":["Grillz"]},{"canonical":"Kanthi","prior":0.1,"aliases":[]},{"canonical":"Hasli","prior":0.2,"aliases":["Hansuli"]},{"canonical":"Guttapusalu","prior":0.05,"aliases":[]},{"canonical":"Kasu mala","prior":0.1,"aliases":["Kasumala","Lakshmi haaram"]},{"canonical":"Jadanagam","prior":0.05,"aliases":[]}]', NULL, 'Think of a bride from head to toe: forehead, nose, neck, wrist, waist, ankle and toes.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-wear-head', 'Name something you wear on your head.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Sikh turban, the dastar, is a single long cloth wrapped fresh each time it''s tied. Assam''s japi, a wide conical hat of bamboo and palm leaves, is often given to honour a guest.', 'https://en.wikipedia.org/wiki/List_of_hat_styles', 'Wikipedia: List of hat styles', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Cap","prior":20,"aliases":["Caps","Baseball cap","Topi"]},{"canonical":"Hat","prior":18,"aliases":["Hats"]},{"canonical":"Helmet","prior":14,"aliases":["Helmets","Bike helmet","Cricket helmet"]},{"canonical":"Turban","prior":10,"aliases":["Pagdi","Pagri","Safa","Dastar","Pag","Pheta","Patka"]},{"canonical":"Crown","prior":6,"aliases":["Mukut"]},{"canonical":"Scarf","prior":4,"aliases":["Headscarf","Head scarf","Bandana","Bandanna"]},{"canonical":"Hijab","prior":3,"aliases":["Headscarf hijab","Niqab","Dupatta","Chunni"]},{"canonical":"Beanie","prior":3,"aliases":["Monkey cap","Woollen cap","Woolen cap","Toque","Bobble hat"]},{"canonical":"Headband","prior":2,"aliases":["Hairband","Hair band","Sweatband"]},{"canonical":"Tiara","prior":2,"aliases":["Diadem"]},{"canonical":"Cowboy hat","prior":1,"aliases":["Stetson"]},{"canonical":"Beret","prior":1,"aliases":[]},{"canonical":"Sun hat","prior":1,"aliases":["Sunhat","Bucket hat","Floppy hat","Straw hat"]},{"canonical":"Fedora","prior":1,"aliases":["Trilby"]},{"canonical":"Top hat","prior":1,"aliases":[]},{"canonical":"Bowler hat","prior":0.5,"aliases":["Bowler","Derby hat"]},{"canonical":"Gandhi cap","prior":1,"aliases":["Gandhi topi"]},{"canonical":"Himachali topi","prior":1,"aliases":["Himachali cap","Kullu cap","Kinnauri cap"]},{"canonical":"Fez","prior":0.5,"aliases":[]},{"canonical":"Skullcap","prior":0.5,"aliases":["Kippah","Yarmulke","Taqiyah","Kufi","Namaz cap","Prayer cap"]},{"canonical":"Balaclava","prior":0.5,"aliases":["Ski mask"]},{"canonical":"Hood","prior":0.5,"aliases":["Hoodie hood"]},{"canonical":"Headphones","prior":0.5,"aliases":["Headset"]},{"canonical":"Sunglasses","prior":0.3,"aliases":["Shades"]},{"canonical":"Veil","prior":0.5,"aliases":["Ghoonghat","Bridal veil","Ghunghat"]},{"canonical":"Sehra","prior":0.5,"aliases":["Sehra veil"]},{"canonical":"Sola topi","prior":0.5,"aliases":["Pith helmet","Solar topee"]},{"canonical":"Hard hat","prior":0.5,"aliases":["Safety helmet","Construction helmet"]},{"canonical":"Chef''s hat","prior":0.5,"aliases":["Chef hat","Toque blanche"]},{"canonical":"Graduation cap","prior":0.5,"aliases":["Mortarboard","Convocation cap"]},{"canonical":"Party hat","prior":0.5,"aliases":["Birthday cap","Birthday hat"]},{"canonical":"Swimming cap","prior":0.5,"aliases":["Swim cap","Shower cap"]},{"canonical":"Wig","prior":0.5,"aliases":[]},{"canonical":"Earmuffs","prior":0.3,"aliases":["Ear muffs"]},{"canonical":"Visor","prior":0.3,"aliases":["Sun visor"]},{"canonical":"Panama hat","prior":0.2,"aliases":["Panama"]},{"canonical":"Japi","prior":0.3,"aliases":["Jaapi"]},{"canonical":"Flower crown","prior":0.2,"aliases":["Gajra","Veni","Flower garland","Mogra gajra"]},{"canonical":"Maang tikka","prior":0.3,"aliases":["Tikka"]},{"canonical":"Sombrero","prior":0.3,"aliases":[]},{"canonical":"Tam o'' shanter","prior":0.05,"aliases":["Tam"]},{"canonical":"Deerstalker","prior":0.1,"aliases":[]},{"canonical":"Pirate hat","prior":0.1,"aliases":["Tricorne","Tricorn"]},{"canonical":"Witch''s hat","prior":0.1,"aliases":["Witch hat"]},{"canonical":"Halo","prior":0.05,"aliases":[]},{"canonical":"Bearskin","prior":0.05,"aliases":[]},{"canonical":"Hairnet","prior":0.1,"aliases":["Hair net"]},{"canonical":"Head torch","prior":0.1,"aliases":["Headlamp"]},{"canonical":"VR headset","prior":0.1,"aliases":[]},{"canonical":"Bon