INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-wear-blue', 'Name a shade of blue.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Indigo, the dye in blue jeans, takes its name from India, for centuries its main source. YInMn blue, the first new blue pigment in two hundred years, was found by accident in an Oregon lab in 2009.', 'https://en.wikipedia.org/wiki/Shades_of_blue', 'Wikipedia: Shades of blue', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0, '[{"canonical":"Navy blue","prior":20,"aliases":["Navy","Dark blue"]},{"canonical":"Sky blue","prior":18,"aliases":["Light blue","Baby blue","Aasmani"]},{"canonical":"Royal blue","prior":12,"aliases":[]},{"canonical":"Turquoise","prior":8,"aliases":["Firozi","Ferozi","Feroza"]},{"canonical":"Teal","prior":6,"aliases":[]},{"canonical":"Cyan","prior":4,"aliases":[]},{"canonical":"Aqua","prior":4,"aliases":["Aqua blue"]},{"canonical":"Indigo","prior":4,"aliases":["Neel"]},{"canonical":"Cobalt blue","prior":3,"aliases":["Cobalt"]},{"canonical":"Azure","prior":2,"aliases":[]},{"canonical":"Cerulean","prior":2,"aliases":[]},{"canonical":"Sapphire blue","prior":2,"aliases":["Sapphire"]},{"canonical":"Peacock blue","prior":2,"aliases":["Morpankhi","Peacock"]},{"canonical":"Powder blue","prior":1,"aliases":[]},{"canonical":"Ink blue","prior":1,"aliases":["Ink"]},{"canonical":"Electric blue","prior":1,"aliases":[]},{"canonical":"Midnight blue","prior":1,"aliases":[]},{"canonical":"Prussian blue","prior":1,"aliases":[]},{"canonical":"Ultramarine","prior":1,"aliases":[]},{"canonical":"Denim blue","prior":1,"aliases":["Denim"]},{"canonical":"Steel blue","prior":0.5,"aliases":[]},{"canonical":"Periwinkle","prior":0.5,"aliases":[]},{"canonical":"Cornflower blue","prior":0.5,"aliases":["Cornflower"]},{"canonical":"Ice blue","prior":0.5,"aliases":[]},{"canonical":"Lapi