ases":[]},{"canonical":"Imperial blue","prior":0.1,"aliases":[]}]', NULL, 'Think of a school uniform, the sea at Goa, a peacock''s neck, a gemstone and the dye in your denims.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-out-tree', 'Name a tree.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Great Banyan in Kolkata''s botanical garden spreads over about 1.9 hectares and looks like a whole forest, though it is a single tree. Bamboo, for all its height, is a grass, not a tree.', 'https://en.wikipedia.org/wiki/Tree', 'Wikipedia: Tree', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, '[{"canonical":"Banyan","prior":16,"aliases":["Bargad","Vat","Vata","Banyan tree","Banian"]},{"canonical":"Neem","prior":14,"aliases":["Neem tree","Margosa"]},{"canonical":"Mango","prior":14,"aliases":["Mango tree","Aam"]},{"canonical":"Peepal","prior":12,"aliases":["Pipal","Peepul","Sacred fig","Bodhi tree","Bodhi","Ashvattha"]},{"canonical":"Coconut","prior":10,"aliases":["Coconut tree","Coconut palm","Nariyal"]},{"canonical":"Oak","prior":8,"aliases":["Oak tree"]},{"canonical":"Pine","prior":8,"aliases":["Pine tree","Chir pine"]},{"canonical":"Palm","prior":4,"aliases":["Palm tree"]},{"canonical":"Apple","prior":4,"aliases":["Apple tree"]},{"canonical":"Maple","prior":3,"aliases":["Maple tree"]},{"canonical":"Chinar","prior":3,"aliases":["Chinar tree","Plane tree","Oriental plane"]},{"canonical":"Teak","prior":3,"aliases":["Sagwan"]},{"canonical":"Sandalwood","prior":3,"aliases":["Chandan"]},{"canonical":"Ashoka","prior":3,"aliases":["Ashok","Ashoka tree"]},{"canonical":"Gulmohar","prior":3,"aliases":["Gulmohur","Flame tree","Royal poinciana"]},{"canonical":"Eucalyptus","prior":2,"aliases":["Nilgiri","Safeda","Gum tree"]},{"canonical":"Deodar","prior":2,"aliases":["Cedar","Himalayan cedar","Devdar"]},{"canonical":"Christmas tree","prior":2,"aliases":["Fir","Fir tree"]},{"canonical":"Sal","prior":2,"aliases":["Shorea"]},{"canonical":"Shisham","prior":2,"aliases":["Rosewood","Sheesham","I