INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-out-flower', 'Name a flower.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Neelakurinji, the shrub that turns Kerala''s Munnar hills blue, blooms only once every 12 years. Lotus seeds can stay alive for centuries: one found in a dry lakebed in China sprouted after about 1,300 years.', 'https://en.wikipedia.org/wiki/Neelakurinji', 'Wikipedia: Neelakurinji', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, '[{"canonical":"Rose","prior":26,"aliases":["Roses","Gulab"]},{"canonical":"Lotus","prior":14,"aliases":["Kamal","Water lily lotus"]},{"canonical":"Sunflower","prior":12,"aliases":["Surajmukhi"]},{"canonical":"Marigold","prior":10,"aliases":["Genda","Gainda","Zendu","Genda phool"]},{"canonical":"Jasmine","prior":10,"aliases":["Mogra","Chameli","Malli","Mallige","Juhi"]},{"canonical":"Lily","prior":8,"aliases":["Lilies"]},{"canonical":"Tulip","prior":8,"aliases":["Tulips"]},{"canonical":"Hibiscus","prior":6,"aliases":["Gudhal","Jaswand","Shoe flower","Chembarathi","Jaba","Joba"]},{"canonical":"Orchid","prior":5,"aliases":["Orchids"]},{"canonical":"Daisy","prior":4,"aliases":["Daisies"]},{"canonical":"Lavender","prior":3,"aliases":[]},{"canonical":"Daffodil","prior":2,"aliases":["Narcissus"]},{"canonical":"Carnation","prior":2,"aliases":[]},{"canonical":"Chrysanthemum","prior":2,"aliases":["Guldaudi","Shevanti","Sevanthi","Mum"]},{"canonical":"Dahlia","prior":2,"aliases":[]},{"canonical":"Poppy","prior":1,"aliases":[]},{"canonical":"Lilac","prior":1,"aliases":[]},{"canonical":"Iris","prior":1,"aliases":[]},{"canonical":"Hydrangea","prior":1,"aliases":[]},{"canonical":"Peony","prior":1,"aliases":[]},{"canonical":"Bougainvillea","prior":1,"aliases":["Bougainvillaea"]},{"canonical":"Frangipani","prior":1,"aliases":["Plumeria","Champa","Gulchin","Temple tree"]},{"canonical":"Neelakurinji","prior":1,"aliases":["Kurinji","Strobilanthes"]},{"canonical":"Parijat","prior":1,"aliases":["Harsingar","Night-flowering jasmine","Night jasmine","Shefali","Shiuli"]},{"canonical":"Tuberose","prior":1,"aliases":["Rajnigandha","Nishigandha"]},{"canonical":"Champak","prior":0.5,"aliases":["Sonchafa","Magnolia champaca","Chempakam"]},{"canonical":"Periwinkle","prior":0.5,"aliases":["Sadabahar","Vinca","Nayantara"]},{"canonical":"Morning glory","prior":0.5,"aliases":[]},{"canonical":"Cherry blossom","prior":0.5,"aliases":["Sakura"]},{"canonical":"Forget-me-not","prior":0.5,"aliases":["Forget me not"]},{"canonical":"Bluebell","prior":0.5,"aliases":[]},{"canonical":"Buttercup","prior":0.5,"aliases":[]},{"canonical":"Violet","prior":0.5,"aliases":[]},{"canonical":"Pansy","prior":0.5,"aliases":[]},{"canonical":"Petunia","prior":0.5,"aliases":[]},{"canonical":"Zinnia","prior":0.5,"aliases":[]},{"canonical":"Cosmos","prior":0.3,"aliases":[]},{"canonical":"Begonia","prior":0.3,"aliases":[]},{"canonical":"Gerbera","prior":1,"aliases":["Gerbera daisy"]},{"canonical":"Aster","prior":0.3,"aliases":[]},{"canonical":"Gardenia","prior":0.3,"aliases":[]},{"canonical":"Camellia","prior":0.3,"aliases":[]},{"canonical":"Azalea","prior":0.3,"aliases":[]},{"canonical":"Rhododendron","prior":0.5,"aliases":["Buransh","Burans"]},{"canonical":"Foxglove","prior":0.3,"aliases":[]},{"canonical":"Snapdragon","prior":0.3,"aliases":[]},{"canonical":"Sweet pea","prior":0.3,"aliases":[]},{"canonical":"Water lily","prior":0.5,"aliases":["Kumudini","Nymphaea","Shapla"]},{"canonical":"Brahma kamal","prior":0.5,"aliases":["Brahmakamal","Brahma kamala"]},{"canonical":"Magnolia","prior":0.3,"aliases":[]},{"canonical":"Gladiolus","prior":0.5,"aliases":[]},{"canonical":"Dandelion","prior":0.5,"aliases":[]},{"canonical":"Lily of the valley","prior":0.3,"aliases":[]},{"canonical":"Edelweiss","prior":0.2,"aliases":[]},{"canonical":"Anemone","prior":0.2,"aliases":[]},{"canonical":"Ranunculus","prior":0.2,"aliases":[]},{"canonical":"Amaryllis","prior":0.2,"aliases":[]},{"canonical":"Crocus","prior":0.3,"aliases":[]},{"canonical":"Freesia","prior":0.2,"aliases":[]},{"canonical":"Geranium","prior":0.3,"aliases":[]},{"canonical":"Honeysuckle","prior":0.2,"aliases":[]},{"canonical":"Wisteria","prior":0.3,"aliases":[]},{"canonical":"Calendula","prior":0.2,"aliases":["Pot marigold"]},{"canonical":"Primrose","prior":0.2,"aliases":[]},{"canonical":"Kanakambaram","prior":0.2,"aliases":["Firecracker flower","Aboli","Crossandra"]},{"canonical":"Mussaenda","prior":0.1,"aliases":[]},{"canonical":"Ixora","prior":0.3,"aliases":["Jungle geranium","Rugmini"]},{"canonical":"Oleander","prior":0.3,"aliases":["Kaner","Arali"]},{"canonical":"Crown flower","prior":0.2,"aliases":["Aak","Madar","Calotropis","Erukku"]},{"canonical":"Bird of paradise","prior":0.2,"aliases":["Strelitzia"]},{"canonical":"Heliconia","prior":0.1,"aliases":["Lobster claw"]},{"canonical":"Protea","prior":0.1,"aliases":[]},{"canonical":"Rafflesia","prior":0.2,"aliases":["Corpse flower"]},{"canonical":"Saffron crocus","prior":0.1,"aliases":[]},{"canonical":"Sweet william","prior":0.05,"aliases":[]},{"canonical":"Hollyhock","prior":0.1,"aliases":[]},{"canonical":"Lupin","prior":0.1,"aliases":["Lupine"]},{"canonical":"Delphinium","prior":0.1,"aliases":["Larkspur"]},{"canonical":"Phlox","prior":0.05,"aliases":[]},{"canonical":"Salvia","prior":0.1,"aliases":[]},{"canonical":"Nasturtium","prior":0.1,"aliases":[]}]', NULL, 'Think of a temple offering, a wedding garland, a Dutch spring, a Valentine''s bouquet and a Kerala hillside every twelve years.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-out-weather', 'Name a kind of weather.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Bengal''s kalbaisakhi, or nor''wester, is a violent afternoon storm of April and May. North India''s scorching summer wind is the loo, and the ''mango showers'' of the south arrive just before the monsoon as the mangoes ripen.', 'https://en.wikipedia.org/wiki/Weather', 'Wikipedia: Weather', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, '[{"canonical":"Rain","prior":22,"aliases":["Rainy","Raining","Rainfall","Barish","Baarish","Showers","Shower"]},{"canonical":"Sunny","prior":18,"aliases":["Sunshine","Sun","Sunlight","Dhoop"]},{"canonical":"Snow","prior":12,"aliases":["Snowy","Snowfall","Snowing","Barf"]},{"canonical":"Cloudy","prior":10,"aliases":["Clouds","Overcast","Grey skies","Gray skies"]},{"canonical":"Windy","prior":8,"aliases":["Wind","Breezy","Breeze"]},{"canonical":"Fog","prior":8,"aliases":["Foggy","Kohra"]},{"canonical":"Storm","prior":6,"aliases":["Stormy"]},{"canonical":"Thunderstorm","prior":6,"aliases":["Thunder","Thunder and lightning","Lightning"]},{"canonical":"Hail","prior":3,"aliases":["Hailstorm","Hailstones","Ole"]},{"canonical":"Humid","prior":3,"aliases":["Humidity","Muggy","Sticky","Sultry"]},{"canonical":"Monsoon","prior":3,"aliases":["Monsoon rain","Monsoons"]},{"canonical":"Heatwave","prior":3,"aliases":["Heat wave","Loo","Hot wind"]},{"canonical":"Drizzle","prior":2,"aliases":["Drizzling","Light rain","Boondabandi"]},{"canonical":"Hot","prior":2,"aliases":["Heat","Scorching","Garmi"]},{"canonical":"Cold","prior":2,"aliases":["Chilly","Freezing","Thand"]},{"canonical":"Cold wave","prior":1,"aliases":["Cold snap","Shitlehar"]},{"canonical":"Mist","prior":1,"aliases":["Misty"]},{"canonical":"Smog","prior":1,"aliases":[]},{"canonical":"Sleet","prior":1,"aliases":[]},{"canonical":"Blizzard","prior":1,"aliases":["Snowstorm"]},{"canonical":"Frost","prior":1,"aliases":["Frosty"]},{"canonical":"Dust storm","prior":1,"aliases":["Aandhi","Andhi","Sandstorm"]},{"canonical":"Cyclone","prior":1,"aliases":[]},{"canonical":"Tornado","prior":1,"aliases":["Twister"]},{"canonical":"Hurricane","prior":1,"aliases":[]},{"canonical":"Typhoon","prior":0.5,"aliases":[]},{"canonical":"Haze","prior":0.5,"aliases":["Hazy"]},{"canonical":"Dew","prior":0.5,"aliases":["Os"]},{"canonical":"Clear sky","prior":0.5,"aliases":["Clear","Clear skies"]},{"canonical":"Pleasant","prior":0.5,"aliases":["Mild","Fair"]},{"canonical":"Rainbow","prior":0.5,"aliases":[]},{"canonical":"Cloudburst","prior":0.5,"aliases":[]},{"canonical":"Kalbaisakhi","prior":0.3,"aliases":["Nor''wester","Norwester","Kalbaishakhi"]},{"canonical":"Mango showers","prior":0.2,"aliases":["Mango shower"]},{"canonical":"Western disturbance","prior":0.2,"aliases":[]},{"canonical":"Gale","prior":0.3,"aliases":["Gusty"]},{"canonical":"Squall","prior":0.2,"aliases":[]},{"canonical":"Drought","prior":0.3,"aliases":["Dry spell","Dry"]},{"canonical":"Freezing rain","prior":0.1,"aliases":["Ice storm"]},{"canonical":"Black ice","prior":0.05,"aliases":[]},{"canonical":"Whiteout","prior":0.1,"aliases":[]},{"canonical":"Graupel","prior":0.02,"aliases":[]},{"canonical":"Heat dome","prior":0.05,"aliases":[]},{"canonical":"Polar vortex","prior":0.05,"aliases":[]},{"canonical":"Downpour","prior":0.3,"aliases":["Heavy rain","Torrential rain","Pouring"]},{"canonical":"Flash flood","prior":0.1,"aliases":[]},{"canonical":"Sun shower","prior":0.1,"aliases":["Monkey''s wedding"]},{"canonical":"Indian summer","prior":0.05,"aliases":[]}]', NULL, 'Think of a Delhi morning in January, a Mumbai July, a Rajasthan afternoon in May and a day in Gulmarg.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-out-gem', 'Name a gemstone.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Until diamonds were found in Brazil in the 1720s, India''s Golconda region was the world''s only known source of them, and the Koh-i-Noor almost certainly came from its mines.', 'https://en.wikipedia.org/wiki/Gemstone', 'Wikipedia: Gemstone', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, '[{"canonical":"Diamond","prior":26,"aliases":["Heera","Hira","Diamonds","Koh-i-Noor","Kohinoor"]},{"canonical":"Ruby","prior":18,"aliases":["Manik","Manikya","Rubies"]},{"canonical":"Emerald","prior":14,"aliases":["Panna","Emeralds"]},{"canonical":"Sapphire","prior":12,"aliases":["Neelam","Blue sapphire","Sapphires"]},{"canonical":"Pearl","prior":8,"aliases":["Moti","Pearls"]},{"canonical":"Topaz","prior":6,"aliases":[]},{"canonical":"Amethyst","prior":4,"aliases":[]},{"canonical":"Opal","prior":3,"aliases":[]},{"canonical":"Garnet","prior":3,"aliases":[]},{"canonical":"Coral","prior":3,"aliases":["Moonga","Red coral","Munga"]},{"canonical":"Yellow sapphire","prior":2,"aliases":["Pukhraj","Pushparag"]},{"canonical":"Jade","prior":2,"aliases":[]},{"canonical":"Turquoise","prior":2,"aliases":["Firoza","Feroza"]},{"canonical":"Aquamarine","prior":2,"aliases":[]},{"canonical":"Onyx","prior":2,"aliases":[]},{"canonical":"Cat''s eye","prior":2,"aliases":["Lehsunia","Lahsuniya","Cats eye","Chrysoberyl cat''s eye","Vaidurya"]},{"canonical":"Hessonite","prior":1,"aliases":["Gomed","Gomedh"]},{"canonical":"Peridot","prior":1,"aliases":[]},{"canonical":"Tourmaline","prior":1,"aliases":[]},{"canonical":"Lapis lazuli","prior":1,"aliases":["Lapis"]},{"canonical":"Moonstone","prior":1,"aliases":[]},{"canonical":"Zircon","prior":1,"aliases":[]},{"canonical":"Citrine","prior":1,"aliases":[]},{"canonical":"Tanzanite","prior":1,"aliases":[]},{"canonical":"Alexandrite","prior":0.5,"aliases":[]},{"canonical":"Spinel","prior":0.5,"aliases":[]},{"canonical":"Agate","prior":0.5,"aliases":[]},{"canonical":"Jasper","prior":0.5,"aliases":[]},{"canonical":"Amber","prior":0.5,"aliases":[]},{"canonical":"Tiger''s eye","prior":0.5,"aliases":["Tigers eye","Tiger eye"]},{"canonical":"Malachite","prior":0.3,"aliases":[]},{"canonical":"Obsidian","prior":0.3,"aliases":[]},{"canonical":"Rose quartz","prior":0.5,"aliases":[]},{"canonical":"Quartz","prior":0.5,"aliases":["Crystal","Sphatik","Rock crystal"]},{"canonical":"Bloodstone","prior":0.2,"aliases":[]},{"canonical":"Kunzite","prior":0.1,"aliases":[]},{"canonical":"Morganite","prior":0.2,"aliases":[]},{"canonical":"Iolite","prior":0.1,"aliases":[]},{"canonical":"Beryl","prior":0.3,"aliases":[]},{"canonical":"Sunstone","prior":0.1,"aliases":[]},{"canonical":"Labradorite","prior":0.1,"aliases":[]},{"canonical":"Carnelian","prior":0.2,"aliases":[]},{"canonical":"Jet","prior":0.1,"aliases":[]},{"canonical":"Black opal","prior":0.1,"aliases":[]},{"canonical":"Fire opal","prior":0.1,"aliases":[]},{"canonical":"Pink sapphire","prior":0.05,"aliases":[]},{"canonical":"Padparadscha","prior":0.02,"aliases":[]},{"canonical":"Benitoite","prior":0.02,"aliases":[]},{"canonical":"Painite","prior":0.05,"aliases":[]},{"canonical":"Taaffeite","prior":0.02,"aliases":[]},{"canonical":"Diopside","prior":0.02,"aliases":[]},{"canonical":"Sodalite","prior":0.05,"aliases":[]},{"canonical":"Rhodonite","prior":0.02,"aliases":[]},{"canonical":"Chrysoprase","prior":0.05,"aliases":[]},{"canonical":"Moissanite","prior":0.1,"aliases":[]},{"canonical":"Cubic zirconia","prior":0.1,"aliases":["CZ","American diamond"]},{"canonical":"Larimar","prior":0.02,"aliases":[]},{"canonical":"Ammolite","prior":0.02,"aliases":[]},{"canonical":"Sugilite","prior":0.02,"aliases":[]}]', NULL, 'Think of the navratna ring, birthstones for each month, and the stones set in a crown.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-out-cloud', 'Name a type of cloud.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Clouds got their Latin names from Luke Howard, an English chemist, in 1802: cumulus means heap, stratus means layer and cirrus means a curl of hair. A big cumulonimbus can tower higher than Mount Everest.', 'https://en.wikipedia.org/wiki/List_of_cloud_types', 'Wikipedia: List of cloud types', '2026-11-21', 'CC BY-SA 4.0', 'science', 2, 0, '[{"canonical":"Cumulus","prior":22,"aliases":[]},{"canonical":"Cirrus","prior":16,"aliases":[]},{"canonical":"Stratus","prior":14,"aliases":[]},{"canonical":"Cumulonimbus","prior":12,"aliases":["Thunderhead","Thundercloud","Thunder cloud"]},{"canonical":"Nimbus","prior":8,"aliases":[]},{"canonical":"Nimbostratus","prior":4,"aliases":[]},{"canonical":"Altostratus","prior":3,"aliases":[]},{"canonical":"Altocumulus","prior":3,"aliases":["Mackerel sky"]},{"canonical":"Cirrostratus","prior":2,"aliases":[]},{"canonical":"Cirrocumulus","prior":2,"aliases":[]},{"canonical":"Stratocumulus","prior":2,"aliases":[]},{"canonical":"Contrail","prior":2,"aliases":["Vapour trail","Vapor trail"]},{"canonical":"Rain cloud","prior":2,"aliases":["Rain clouds"]},{"canonical":"Storm cloud","prior":1,"aliases":[]},{"canonical":"Fog","prior":1,"aliases":["Mist"]},{"canonical":"Mammatus","prior":1,"aliases":[]},{"canonical":"Lenticular","prior":1,"aliases":["Lenticular cloud","UFO cloud"]},{"canonical":"Noctilucent","prior":0.5,"aliases":["Noctilucent cloud","Night clouds"]},{"canonical":"Shelf cloud","prior":0.5,"aliases":["Arcus"]},{"canonical":"Funnel cloud","prior":0.5,"aliases":[]},{"canonical":"Wall cloud","prior":0.3,"aliases":[]},{"canonical":"Roll cloud","prior":0.3,"aliases":["Morning Glory cloud"]},{"canonical":"Anvil cloud","prior":0.3,"aliases":["Anvil","Incus"]},{"canonical":"Pyrocumulus","prior":0.3,"aliases":["Fire cloud","Flammagenitus"]},{"canonical":"Nacreous","prior":0.2,"aliases":["Mother-of-pearl cloud","Polar stratospheric cloud"]},{"canonical":"Kelvin-Helmholtz","prior":0.2,"aliases":["Wave cloud","Fluctus"]},{"canonical":"Asperitas","prior":0.1,"aliases":["Undulatus asperatus"]},{"canonical":"Pileus","prior":0.1,"aliases":["Cap cloud"]},{"canonical":"Fractus","prior":0.1,"aliases":["Scud"]},{"canonical":"Virga","prior":0.1,"aliases":[]},{"canonical":"Castellanus","prior":0.05,"aliases":[]},{"canonical":"Fallstreak hole","prior":0.05,"aliases":["Hole punch cloud"]},{"canonical":"Cumulus congestus","prior":0.1,"aliases":["Towering cumulus"]}]', NULL, 'Think of fluffy heaps, wispy curls, flat grey sheets, towering storm clouds and the trails behind jet planes.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-out-disaster', 'Name a natural disaster.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The 2004 Indian Ocean tsunami, set off by a magnitude 9.1 earthquake off Sumatra, struck coasts from Indonesia to Somalia. Cyclone, hurricane and typhoon are names for the same kind of storm in different oceans.', 'https://en.wikipedia.org/wiki/Natural_disaster', 'Wikipedia: Natural disaster', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, '[{"canonical":"Earthquake","prior":24,"aliases":["Earthquakes","Quake","Bhukamp","Bhookamp"]},{"canonical":"Flood","prior":20,"aliases":["Floods","Flooding","Baadh","Badh"]},{"canonical":"Tsunami","prior":14,"aliases":["Tidal wave"]},{"canonical":"Cyclone","prior":10,"aliases":["Cyclones","Tropical cyclone"]},{"canonical":"Volcanic eruption","prior":8,"aliases":["Volcano","Eruption","Volcanoes"]},{"canonical":"Hurricane","prior":8,"aliases":[]},{"canonical":"Tornado","prior":6,"aliases":["Twister"]},{"canonical":"Landslide","prior":6,"aliases":["Landslides","Landslip"]},{"canonical":"Drought","prior":4,"aliases":["Sukha","Akal"]},{"canonical":"Wildfire","prior":4,"aliases":["Forest fire","Bushfire","Bush fire"]},{"canonical":"Avalanche","prior":4,"aliases":["Snow avalanche"]},{"canonical":"Typhoon","prior":2,"aliases":[]},{"canonical":"Heatwave","prior":2,"aliases":["Heat wave"]},{"canonical":"Cloudburst","prior":2,"aliases":["Cloud burst"]},{"canonical":"Blizzard","prior":1,"aliases":["Snowstorm"]},{"canonical":"Hailstorm","prior":1,"aliases":["Hail"]},{"canonical":"Thunderstorm","prior":1,"aliases":["Lightning","Lightning strike"]},{"canonical":"Sandstorm","prior":1,"aliases":["Dust storm","Aandhi"]},{"canonical":"Famine","prior":1,"aliases":[]},{"canonical":"Mudslide","prior":1,"aliases":["Mudflow","Mud slide"]},{"canonical":"Sinkhole","prior":0.5,"aliases":[]},{"canonical":"Storm surge","prior":0.5,"aliases":[]},{"canonical":"Cold wave","prior":0.5,"aliases":["Cold snap","Extreme cold"]},{"canonical":"Pandemic","prior":0.5,"aliases":["Epidemic","Plague"]},{"canonical":"Locust swarm","prior":0.3,"aliases":["Locusts","Locust plague"]},{"canonical":"Meteor strike","prior":0.3,"aliases":["Asteroid impact","Meteorite","Meteor"]},{"canonical":"Solar storm","prior":0.2,"aliases":["Solar flare","Geomagnetic storm"]},{"canonical":"Glacial lake outburst flood","prior":0.2,"aliases":["GLOF","Glacier burst"]},{"canonical":"Flash flood","prior":0.5,"aliases":["Flash floods"]},{"canonical":"Ice storm","prior":0.1,"aliases":[]},{"canonical":"Limnic eruption","prior":0.05,"aliases":[]},{"canonical":"Lahar","prior":0.05,"aliases":[]},{"canonical":"Waterspout","prior":0.1,"aliases":[]},{"canonical":"Derecho","prior":0.05,"aliases":[]},{"canonical":"Dzud","prior":0.01,"aliases":[]},{"canonical":"Coastal erosion","prior":0.05,"aliases":[]},{"canonical":"Rockfall","prior":0.1,"aliases":["Rock fall"]},{"canonical":"Storm","prior":0.5,"aliases":["Severe storm","Windstorm"]}]', NULL, 'Think of what shakes the ground, what rises over riverbanks, what spins, what erupts and what slides down a mountainside.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-out-root', 'Name a vegetable that grows underground.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Not every underground vegetable is a root: a potato is a swollen stem, an onion is layers of leaves, and a carrot is a true root. The peanut flowers above ground, then pushes its pods into the soil to ripen.', 'https://en.wikipedia.org/wiki/Root_vegetable', 'Wikipedia: Root vegetable', '2026-11-21', 'CC BY-SA 4.0', 'food', 1, 0, '[{"canonical":"Potato","prior":26,"aliases":["Potatoes","Aloo","Alu","Batata"]},{"canonical":"Carrot","prior":20,"aliases":["Carrots","Gajar"]},{"canonical":"Onion","prior":14,"aliases":["Onions","Pyaz","Pyaaz","Kanda"]},{"canonical":"Radish","prior":10,"aliases":["Mooli","Muli","Daikon","Radishes"]},{"canonical":"Beetroot","prior":8,"aliases":["Beet","Beets","Chukandar"]},{"canonical":"Garlic","prior":6,"aliases":["Lahsun","Lehsun"]},{"canonical":"Ginger","prior":6,"aliases":["Adrak"]},{"canonical":"Sweet potato","prior":4,"aliases":["Shakarkandi","Shakarkand","Sweet potatoes"]},{"canonical":"Turnip","prior":4,"aliases":["Shalgam","Turnips"]},{"canonical":"Yam","prior":2,"aliases":["Suran","Jimikand","Elephant foot yam","Ratalu","Kand"]},{"canonical":"Taro","prior":2,"aliases":["Arbi","Colocasia","Arvi","Chamagadda","Seppankizhangu"]},{"canonical":"Turmeric","prior":2,"aliases":["Haldi","Raw turmeric"]},{"canonical":"Tapioca","prior":2,"aliases":["Cassava","Kappa","Maravalli kizhangu","Yuca"]},{"canonical":"Peanut","prior":1,"aliases":["Groundnut","Moongphali","Peanuts"]},{"canonical":"Parsnip","prior":1,"aliases":[]},{"canonical":"Lotus root","prior":1,"aliases":["Kamal kakdi","Bhein","Nadru","Lotus stem"]},{"canonical":"Shallot","prior":1,"aliases":["Shallots","Sambar onion","Small onion"]},{"canonical":"Spring onion","prior":0.3,"aliases":["Scallion","Green onion","Hara pyaz"]},{"canonical":"Celeriac","prior":0.3,"aliases":["Celery root"]},{"canonical":"Jerusalem artichoke","prior":0.3,"aliases":["Sunchoke"]},{"canonical":"Horseradish","prior":0.3,"aliases":[]},{"canonical":"Wasabi","prior":0.3,"aliases":[]},{"canonical":"Jicama","prior":0.2,"aliases":["Mexican turnip"]},{"canonical":"Rutabaga","prior":0.3,"aliases":["Swede"]},{"canonical":"Salsify","prior":0.1,"aliases":[]},{"canonical":"Burdock","prior":0.1,"aliases":["Gobo"]},{"canonical":"Konjac","prior":0.1,"aliases":[]},{"canonical":"Galangal","prior":0.2,"aliases":[]},{"canonical":"Arrowroot","prior":0.3,"aliases":["Ararot"]},{"canonical":"Yacon","prior":0.05,"aliases":[]},{"canonical":"Mango ginger","prior":0.1,"aliases":["Amba haldi"]},{"canonical":"Oca","prior":0.02,"aliases":[]},{"canonical":"Ulluco","prior":0.02,"aliases":[]},{"canonical":"Mashua","prior":0.01,"aliases":[]},{"canonical":"Chinese artichoke","prior":0.02,"aliases":["Crosne"]},{"canonical":"Purple yam","prior":0.2,"aliases":["Ube","Kandmool"]}]', NULL, 'Think of what''s sizzled at the start of a curry, what goes into a winter halwa, the stuffing of a paratha and a pink salad.');
